              <select
                value={aboutCtaBuilder.emphasisStyle || 'soft'}
                onChange={(e) => handleAboutCtaBuilderChange('emphasisStyle', e.target.value)}
                className='w-full rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900/70 text-gray-900 dark:text-gray-100 px-3 py-2 focus:outline-none focus:ring-2 focus:ring-accent'>
                <option value='soft'>Soft Panel</option>
                <option value='strong'>Strong Panel</option>
                <option value='outline'>Outline Surface</option>
              </select>
            </div>

            <label className='flex items-center gap-2 text-sm text-gray-700 dark:text-gray-300 xl:pt-6'>
              <input
                type='checkbox'
                checked={aboutCtaBuilder.showSecondaryButton ?? true}
                onChange={(e) => handleAboutCtaBuilderChange('showSecondaryButton', e.target.checked)}
                className='rounded border-gray-300 text-accent focus:ring-accent'
              />
              Show secondary button
            </label>
          </div>
        </div>

        <div className='border-t border-gray-200 dark:border-gray-700 pt-4 space-y-3'>
          <div className='flex items-center justify-between gap-3'>
            <div>
              <h5 className='text-sm font-semibold text-gray-900 dark:text-white'>About Section Order</h5>
              <p className='text-xs text-gray-500 dark:text-gray-400 mt-1'>Control the top-to-bottom order of blocks on the public About page.</p>
            </div>

            <button
              type='button'
              onClick={resetAboutSectionOrder}
              className='px-2.5 py-1.5 text-xs rounded-md border border-gray-300 dark:border-gray-600 text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-gray-800'>
              Reset Order
            </button>
          </div>

          <div className='space-y-2'>
            {sectionOrder.map((sectionKey, index, order) => {
              const item = ABOUT_SECTION_ITEMS.find((entry) => entry.key === sectionKey)
              const isVisible = sectionVisibility[item?.visibilityKey] ?? true

              if (!item) return null

              return (
                <div key={item.key} className='flex items-center justify-between gap-3 rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900/60 px-3 py-2'>
                  <div className='flex items-center gap-3 min-w-0'>
                    <span className='flex h-6 w-6 flex-shrink-0 items-center justify-center rounded-full bg-accent/15 text-xs font-semibold text-accent'>{index + 1}</span>

                    <div className='min-w-0'>
                      <p className='text-sm font-medium text-gray-900 dark:text-white'>{item.label}</p>
                      <p className='text-xs text-gray-500 dark:text-gray-400'>{isVisible ? 'Visible on page' : 'Hidden by visibility settings'}</p>
                    </div>
                  </div>

                  <div className='flex items-center gap-2'>
                    <button
                      type='button'
                      onClick={() => moveAboutSectionOrderItem(item.key, 'up')}
                      disabled={index === 0}
                      className='px-2.5 py-1.5 text-xs rounded-md border border-gray-300 dark:border-gray-600 text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-gray-800 disabled:opacity-50'>
                      Up
                    </button>

                    <button
                      type='button'
                      onClick={() => moveAboutSectionOrderItem(item.key, 'down')}
                      disabled={index === order.length - 1}
                      className='px-2.5 py-1.5 text-xs rounded-md border border-gray-300 dark:border-gray-600 text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-gray-800 disabled:opacity-50'>
                      Down
                    </button>
                  </div>
                </div>
              )
            })}
          </div>
        </div>

        <div className='border-t border-gray-200 dark:border-gray-700 pt-4 space-y-3'>
          <div className='flex items-center justify-between gap-3'>
            <div>
              <h5 className='text-sm font-semibold text-gray-900 dark:text-white'>About Section Backgrounds</h5>
              <p className='text-xs text-gray-500 dark:text-gray-400 mt-1'>Control the background treatment for each About page block.</p>
            </div>

            <button
              type='button'
              onClick={resetAboutSectionBackgrounds}
              className='px-2.5 py-1.5 text-xs rounded-md border border-gray-300 dark:border-gray-600 text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-gray-800'>
              Reset Backgrounds
            </button>
          </div>

          <div className='space-y-3'>
            {ABOUT_SECTION_ITEMS.map((item) => {
              const backgroundValue = sectionBackgrounds[item.key] || 'default'

              return (
                <div key={item.key} className='rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900/60 p-3'>
                  <label className='block text-sm font-medium text-gray-900 dark:text-white mb-3'>{item.label}</label>

                  <select
                    value={backgroundValue}
                    onChange={(e) => handleAboutSectionBackgroundChange(item.key, e.target.value)}
                    className='w-full rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900/70 text-gray-900 dark:text-gray-100 px-3 py-2 focus:outline-none focus:ring-2 focus:ring-accent'>
                    <option value='default'>Default Theme</option>
                    <option value='transparent'>Transparent</option>
                    <option value='soft'>Soft Tint</option>
                    <option value='panel'>Panel Surface</option>
                    <option value='accent'>Accent Tint</option>
                  </select>
                </div>
              )
            })}
          </div>
        </div>

        <div className='border-t border-gray-200 dark:border-gray-700 pt-4 space-y-4'>
          <div className='flex items-center justify-between gap-3'>
            <div>
              <h6 className='text-sm font-semibold text-gray-900 dark:text-white'>Current Render Order</h6>
              <p className='text-xs text-gray-500 dark:text-gray-400 mt-1'>This is the order the About page will use after saving, with visibility applied per block.</p>
            </div>
            <span className='text-xs text-gray-500 dark:text-gray-400'>Total: {sectionOrder.length}</span>
          </div>

          <div className='space-y-2'>
            {sectionOrder.map((sectionKey, index) => {
              const item = ABOUT_SECTION_ITEMS.find((entry) => entry.key === sectionKey)
              const isVisible = sectionVisibility[item?.visibilityKey] ?? true

              if (!item) return null

              return (
                <div key={item.key} className='flex items-center justify-between gap-3 rounded-lg border border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-900/70 px-3 py-2'>
                  <div className='flex items-center gap-3 min-w-0'>
                    <span className='flex h-6 w-6 flex-shrink-0 items-center justify-center rounded-full bg-accent/15 text-xs font-semibold text-accent'>{index + 1}</span>

                    <div className='min-w-0'>
                      <p className='text-sm font-medium text-gray-900 dark:text-white'>{item.label}</p>
                      <p className='text-xs text-gray-500 dark:text-gray-400'>{isVisible ? 'Will render on page' : 'Hidden and skipped in public render'}</p>
                    </div>
                  </div>

                  <span
                    className={`px-2 py-1 rounded-full text-[11px] font-semibold ${
                      isVisible ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-300' : 'bg-gray-200 text-gray-700 dark:bg-gray-800 dark:text-gray-300'
                    }`}>
                    {isVisible ? 'Visible' : 'Hidden'}
                  </span>
                </div>
              )
            })}
          </div>
        </div>

        <div className='border-t border-gray-200 dark:border-gray-700 pt-8 space-y-4'>
          <div>
            <h5 className='text-sm font-semibold text-gray-900 dark:text-white'>Builder Summary Preview</h5>
            <p className='text-xs text-gray-500 dark:text-gray-400 mt-1'>Review the current About page builder configuration before saving it to the public site.</p>
          </div>

          <div className='grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-3'>
            {[
              { label: 'Content Alignment', value: CONTENT_ALIGN_LABELS[aboutHeroBuilder.contentAlign || 'left'] || 'Left' },
              { label: 'Content Width', value: aboutHeroBuilder.contentWidth || 'wide' },
              { label: 'Eyebrow', value: (aboutHeroBuilder.showEyebrow ?? true) ? 'Shown' : 'Hidden' },
              { label: 'Visible Sections', value: String(visibleSectionsCount) },
              { label: 'Hidden Sections', value: String(hiddenSectionsCount) },
              { label: 'Hero Background', value: BACKGROUND_PRESET_LABELS[sectionBackgrounds.hero || 'default'] || 'Default Theme' },
              { label: 'Highlights Width', value: aboutHighlightsBuilder.contentWidth || 'wide' },
              { label: 'Highlights Layout', value: ABOUT_HIGHLIGHTS_LAYOUT_LABELS[aboutHighlightsBuilder.cardLayout || 'stacked'] || 'Stacked' },
              { label: 'Highlights Icons', value: (aboutHighlightsBuilder.showIcons ?? true) ? 'Shown' : 'Hidden' },
              { label: 'CTA Width', value: aboutCtaBuilder.contentWidth || 'wide' },
              { label: 'CTA Buttons', value: CTA_LAYOUT_LABELS[aboutCtaBuilder.buttonLayout || 'stacked-mobile'] || 'Stacked Mobile / Row Desktop' },
              { label: 'CTA Emphasis', value: ABOUT_CTA_EMPHASIS_LABELS[aboutCtaBuilder.emphasisStyle || 'soft'] || 'Soft Panel' },
              { label: 'Secondary CTA', value: (aboutCtaBuilder.showSecondaryButton ?? true) ? 'Shown' : 'Hidden' }
            ].map((item) => (
              <div key={item.label} className='rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900/60 p-3'>
                <p className='text-[11px] font-semibold uppercase tracking-[0.16em] text-gray-500 dark:text-gray-400'>{item.label}</p>
                <p className='mt-2 text-sm font-medium text-gray-900 dark:text-white'>{item.value}</p>
              </div>
            ))}
          </div>
        </div>

        <div className='flex flex-wrap items-center gap-2 pt-2'>
          <button type='button' onClick={handleSaveSiteBuilderSection} disabled={savingSection === 'siteBuilder'} className='px-4 py-2 rounded-lg bg-accent text-white hover:bg-accent/90 disabled:opacity-60'>
            {savingSection === 'siteBuilder' ? 'Saving...' : 'Save'}
          </button>
        </div>
      </div>
    )
  }

  const renderSectionFields = (sectionId, section) => {
    if (sectionId === 'home') {
      return (
        <div className='mt-4 grid grid-cols-1 lg:grid-cols-3 gap-4'>
          {HOME_FIELD_GROUPS.map((group) => {
            const groupFields = section.fields.filter((field) => group.keys.includes(field.key))
            if (!groupFields.length) return null

            return (
              <div key={group.title} className='rounded-lg border border-gray-200 dark:border-gray-700 bg-gray-50/70 dark:bg-gray-900/40 p-4'>
                <h4 className='text-lg font-bold text-gray-900 dark:text-white mb-3'>{group.title}</h4>
                {renderHomeGroupFields(sectionId, groupFields)}
              </div>
            )
          })}
        </div>
      )
    }

    if (sectionId === 'pricing') {
      return (
        <div className='mt-4 space-y-4'>
          <div className='space-y-3'>{section.fields.map((field) => renderField(sectionId, field))}</div>
          {renderPricingLayoutEditor()}
          {renderPricingPlansEditor()}
        </div>
      )
    }

    if (sectionId === 'testimonials') {
      return (
        <div className='mt-4 space-y-4'>
          <div className='space-y-3'>{section.fields.map((field) => renderField(sectionId, field))}</div>
          {renderTestimonialsLayoutEditor()}
          {renderTestimonialsEditor()}
        </div>
      )
    }

    return <div className='mt-4 space-y-3'>{section.fields.map((field) => renderField(sectionId, field))}</div>
  }

  return (
    <div>
      <div className='mb-6'>
        <h2 className='text-2xl font-bold text-gray-900 dark:text-white'>Settings</h2>
        <p className='text-sm text-gray-500 dark:text-gray-400 mt-1'>Admin configuration center</p>
      </div>

      {loading ? (
        <div className='rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 p-5'>
          <p className='text-gray-700 dark:text-gray-300'>Loading settings...</p>
        </div>
      ) : (
        <div>
          {(() => {
            const activeView = getSettingsView(activeSectionId)
            const sectionId = activeView.sectionId
            const section = SECTION_DEFS[sectionId]

            return (
              <div className='rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 p-5'>
                <div className='flex flex-wrap items-start justify-between gap-3'>
                  <div>
                    <p className='text-xs font-semibold uppercase tracking-[0.18em] text-accent mb-2'>{activeView.pageTitle}</p>
                    <h3 className='text-lg font-semibold text-gray-900 dark:text-white'>{activeView?.sectionTitle || section?.title || activeView?.pageTitle}</h3>
                    <p className='text-sm text-gray-500 dark:text-gray-400 mt-2'>{activeView?.sectionDescription || activeView?.pageDescription}</p>
                  </div>
                </div>

                {!section || !activeView?.isImplemented ? (
                  <div className='mt-6 rounded-lg border border-dashed border-gray-300 dark:border-gray-700 bg-gray-50/70 dark:bg-gray-900/40 p-6'>
                    <h4 className='text-base font-semibold text-gray-900 dark:text-white'>Builder Page Placeholder</h4>
                    <p className='text-sm text-gray-500 dark:text-gray-400 mt-2'>{activeView?.pageDescription || 'This settings page will be implemented in a later step.'}</p>
                  </div>
                ) : (
                  <>
                    <div className='mt-4 flex items-center gap-2'>
                      <input
                        id={`enabled-${activeSectionId}`}
                        type='checkbox'
                        checked={['home.layout', 'about.layout'].includes(activeSectionId) ? !!drafts.siteBuilder?.enabled : !!drafts[sectionId]?.enabled}
                        onChange={(e) => handleEnabledChange(['home.layout', 'about.layout'].includes(activeSectionId) ? 'siteBuilder' : sectionId, e.target.checked)}
                        className='rounded border-gray-300 text-accent focus:ring-accent'
                      />
                      <label htmlFor={`enabled-${activeSectionId}`} className='text-sm text-gray-700 dark:text-gray-300'>
                        Enabled
                      </label>
                    </div>

                    {activeSectionId === 'home.layout' && renderHomeHeroBuilderPanel()}
                    {activeSectionId === 'about.layout' && renderAboutLayoutPanel()}

                    {!['home.layout', 'about.layout'].includes(activeSectionId) && renderSectionFields(sectionId, section)}

                    <div className='mt-4 text-xs text-gray-500 dark:text-gray-400'>
                      Last updated:{' '}
                      {(['home.layout', 'about.layout'].includes(activeSectionId) ? sectionMap.siteBuilder?.updatedAt : sectionMap[sectionId]?.updatedAt)
                        ? new Date(['home.layout', 'about.layout'].includes(activeSectionId) ? sectionMap.siteBuilder.updatedAt : sectionMap[sectionId].updatedAt).toLocaleString()
                        : 'N/A'}
                    </div>

                    {!['home.layout', 'about.layout'].includes(activeSectionId) && (
                      <div className='mt-4 flex flex-wrap items-center gap-2'>
                        <button onClick={() => handleSaveSection(sectionId)} disabled={savingSection === sectionId} className='px-4 py-2 rounded-lg bg-accent text-white hover:bg-accent/90 disabled:opacity-60'>
                          {savingSection === sectionId ? 'Saving...' : 'Save Section'}
                        </button>
                      </div>
                    )}
                  </>
                )}
              </div>
            )
          })()}
        </div>
      )}
    </div>
  )
}

export default AdminSettings

import { useState } from 'react'
import { FaChartBar, FaUsers, FaProjectDiagram, FaBullhorn, FaNewspaper, FaCog, FaBars, FaTimes, FaChevronDown, FaChevronRight } from 'react-icons/fa'
import { motion } from 'framer-motion'
import { useAuth } from '../../context/AuthContext'
import { canAccessAdminSection } from '../../utils/accessRoles'
import { DEFAULT_SETTINGS_SECTION, SETTINGS_GROUPS } from './settingsNavigation'

const AdminSidebar = ({ activeSection, setActiveSection, activeSettingsSection, setActiveSettingsSection }) => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false)
  const [isSettingsOpen, setIsSettingsOpen] = useState(true)
  const [expandedSettingsParents, setExpandedSettingsParents] = useState({
    'site-builder-home-page': true
  })
  const { currentUser } = useAuth()

  const navigationItems = [
    { id: 'dashboard', label: 'Dashboard', icon: <FaChartBar /> },
    { id: 'users', label: 'Users', icon: <FaUsers /> },
    { id: 'projects', label: 'Projects', icon: <FaProjectDiagram /> },
    { id: 'announcements', label: 'Announcements', icon: <FaBullhorn /> },
    { id: 'blog', label: 'Blog', icon: <FaNewspaper /> },
    { id: 'settings', label: 'Settings', icon: <FaCog /> }
  ].filter((item) => canAccessAdminSection(currentUser, item.id))

  const handleMainNavClick = (itemId) => {
    setActiveSection(itemId)

    if (itemId === 'settings') {
      setIsSettingsOpen(true)
      if (!activeSettingsSection) {
        setActiveSettingsSection(DEFAULT_SETTINGS_SECTION)
      }
    }

    setIsMobileMenuOpen(false)
  }

  const handleSettingsItemClick = (itemId) => {
    setActiveSection('settings')
    setActiveSettingsSection(itemId)
    setIsMobileMenuOpen(false)
  }

  const toggleSettingsParent = (key) => {
    setExpandedSettingsParents((prev) => ({
      ...prev,
      [key]: !prev[key]
    }))
  }

  return (
    <>
      <button className='lg:hidden fixed top-[84px] left-4 z-50 p-2 rounded-lg bg-accent text-white shadow-lg' onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}>
        {isMobileMenuOpen ? <FaTimes /> : <FaBars />}
      </button>

      <div
        className={`fixed left-0 top-[68px] z-40 h-[calc(100vh-68px)] w-[240px] overflow-y-auto bg-gradient-to-br from-light/5 via-light/[0.02] to-transparent shadow-lg backdrop-blur-sm transition-transform duration-300 ease-out dark:from-light/5 dark:via-light/[0.02]
          ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'} lg:sticky lg:top-[68px] lg:block lg:h-[calc(100vh-68px)] lg:w-64 lg:flex-shrink-0 lg:translate-x-0`}
        aria-hidden={!isMobileMenuOpen && typeof window !== 'undefined' && window.innerWidth < 1024}>
        <div className='flex min-h-full flex-col'>
          <nav className='space-y-1 p-4 pt-6'>
            {navigationItems.map((item) => {
              const isActive = activeSection === item.id
              const isSettingsItem = item.id === 'settings'

              return (
                <div key={item.id}>
                  <motion.button
                    onClick={() => handleMainNavClick(item.id)}
                    className={`w-full flex items-center justify-between px-4 py-3 text-left rounded-lg transition-all duration-200
                      ${isActive ? 'bg-accent text-white' : 'text-gray-600 dark:text-gray-300 hover:bg-light/5 dark:hover:bg-light/10'}`}
                    whileHover={{ scale: 1.02, translateX: 5 }}
                    whileTap={{ scale: 0.98 }}
                    transition={{ duration: 0.2 }}>
                    <span className='flex items-center'>
                      <span className={`mr-3 text-xl ${isActive ? 'text-white' : 'text-accent'}`}>{item.icon}</span>
                      <span className='font-medium'>{item.label}</span>
                    </span>

                    {isSettingsItem && (
                      <span
                        onClick={(e) => {
                          e.stopPropagation()
                          setIsSettingsOpen((prev) => !prev)
                        }}
                        className='p-1 rounded hover:bg-black/10 dark:hover:bg-white/10'>
                        {isSettingsOpen ? <FaChevronDown size={12} /> : <FaChevronRight size={12} />}
                      </span>
                    )}
                  </motion.button>

                  {isSettingsItem && isSettingsOpen && (
                    <div className='mt-2 ml-7 space-y-4'>
                      {SETTINGS_GROUPS.map((group) => (
                        <div key={group.id} className='space-y-1'>
                          <p className='px-3 text-[11px] font-semibold uppercase tracking-[0.18em] text-gray-400 dark:text-gray-500'>{group.label}</p>

                          <div className='space-y-1'>
                            {group.items.map((settingsItem, index) => {
                              if (settingsItem.children?.length) {
                                const parentKey = `${group.id}-${settingsItem.label.toLowerCase().replace(/\s+/g, '-')}`
                                const isExpanded = expandedSettingsParents[parentKey] ?? false
                                const hasActiveChild = settingsItem.children.some((child) => activeSection === 'settings' && activeSettingsSection === child.id)

                                return (
                                  <div key={parentKey} className='space-y-1'>
                                    <button
                                      type='button'
                                      onClick={() => toggleSettingsParent(parentKey)}
                                      className={`w-full flex items-center justify-between text-left text-sm rounded-md px-3 py-2 transition ${
                                        hasActiveChild ? 'bg-accent/10 text-accent font-medium' : 'text-gray-600 dark:text-gray-300 hover:bg-light/5 dark:hover:bg-light/10'
                                      }`}>
                                      <span>{settingsItem.label}</span>
                                      <span>{isExpanded ? <FaChevronDown size={11} /> : <FaChevronRight size={11} />}</span>
                                    </button>

                                    {isExpanded && (
                                      <div className='ml-3 space-y-1 border-l border-gray-200 dark:border-gray-700 pl-3'>
                                        {settingsItem.children.map((child) => {
                                          const isSettingsActive = activeSection === 'settings' && activeSettingsSection === child.id

                                          return (
                                            <button
                                              key={child.id}
                                              type='button'
                                              onClick={() => handleSettingsItemClick(child.id)}
                                              className={`w-full text-left text-sm rounded-md px-3 py-2 transition ${
                                                isSettingsActive ? 'bg-accent/15 text-accent font-medium' : 'text-gray-600 dark:text-gray-300 hover:bg-light/5 dark:hover:bg-light/10'
                                              }`}>
                                              {child.label}
                                            </button>
                                          )
                                        })}
                                      </div>
                                    )}
                                  </div>
                                )
                              }

                              const isSettingsActive = activeSection === 'settings' && activeSettingsSection === settingsItem.id

                              return (
                                <button
                                  key={settingsItem.id || `${group.id}-${index}`}
                                  type='button'
                                  onClick={() => handleSettingsItemClick(settingsItem.id)}
                                  className={`w-full text-left text-sm rounded-md px-3 py-2 transition ${
                                    isSettingsActive ? 'bg-accent/15 text-accent font-medium' : 'text-gray-600 dark:text-gray-300 hover:bg-light/5 dark:hover:bg-light/10'
                                  }`}>
                                  {settingsItem.label}
                                </button>
                              )
                            })}
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              )
            })}
          </nav>
        </div>
      </div>

      {isMobileMenuOpen && <div className='fixed inset-0 bg-black bg-opacity-50 z-30 lg:hidden' onClick={() => setIsMobileMenuOpen(false)} />}
    </>
  )
}

export default AdminSidebar

import { useState, useEffect } from 'react'
import { getAdminDashboardStats } from '../../services/userService'
import AdminAlertsPanel from './AdminAlertsPanel'
import AdminAuditLogPanel from './AdminAuditLogPanel'
import StatCard from './StatCard'
import { FaUsers, FaProjectDiagram, FaCheckCircle, FaMoneyBillWave, FaUserCheck, FaDollarSign, FaBullseye, FaLayerGroup, FaChartLine } from 'react-icons/fa'

const defaultStats = {
  totalUsers: 0,
  activeProjects: 0,
  completedProjects: 0,
  revenue: 0,
  comparisons: {
    users: 0,
    activeProjects: 0,
    completedProjects: 0,
    revenue: 0
  },
  alertSummary: {
    total: 0,
    critical: 0,
    warning: 0,
    info: 0
  },
  alerts: [],
  healthSignals: {
    lockedUsers: 0,
    inactiveUsers: 0,
    unverifiedUsers: 0,
    passwordResetRequiredUsers: 0,
    stalledProjects: 0
  },
  kpis: {
    activeUserRate: 0,
    avgCompletedProjectValue: 0,
    completionRate: 0,
    newProjectsLast30: 0,
    newProjectsTrend: 0
  }
}

const AdminStats = ({ onOpenSection }) => {
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState('')
  const [stats, setStats] = useState(defaultStats)

  useEffect(() => {
    fetchDashboardStats()
  }, [])

  const fetchDashboardStats = async () => {
    setIsLoading(true)
    setError('')

    try {
      const data = await getAdminDashboardStats()

      setStats({
        ...defaultStats,
        ...data,
        comparisons: {
          ...defaultStats.comparisons,
          ...(data?.comparisons || {})
        },
        alertSummary: {
          ...defaultStats.alertSummary,
          ...(data?.alertSummary || {})
        },
        healthSignals: {
          ...defaultStats.healthSignals,
          ...(data?.healthSignals || {})
        },
        kpis: {
          ...defaultStats.kpis,
          ...(data?.kpis || {})
        },
        alerts: Array.isArray(data?.alerts) ? data.alerts : []
      })
    } catch (err) {
      console.error('Error fetching dashboard stats:', err)
      setError(err.response?.data?.message || 'Failed to load dashboard stats.')
    } finally {
      setIsLoading(false)
    }
  }

  const statCards = [
    {
      title: 'Total Users',
      value: isLoading ? '...' : stats.totalUsers.toLocaleString(),
      icon: <FaUsers />,
      trend: stats.comparisons.users
    },
    {
      title: 'Active Projects',
      value: isLoading ? '...' : stats.activeProjects.toLocaleString(),
      icon: <FaProjectDiagram />,
      trend: stats.comparisons.activeProjects
    },
    {
      title: 'Completed Projects',
      value: isLoading ? '...' : stats.completedProjects.toLocaleString(),
      icon: <FaCheckCircle />,
      trend: stats.comparisons.completedProjects
    },
    {
      title: 'Revenue',
      value: isLoading ? '...' : `$${stats.revenue.toLocaleString()}`,
      icon: <FaMoneyBillWave />,
      trend: stats.comparisons.revenue
    }
  ]

  const kpiCards = [
    {
      title: 'Active User Rate',
      value: isLoading ? '...' : `${stats.kpis?.activeUserRate ?? 0}%`,
      icon: <FaUserCheck />
    },
    {
      title: 'Avg Completed Value',
      value: isLoading ? '...' : `$${(stats.kpis?.avgCompletedProjectValue ?? 0).toLocaleString()}`,
      icon: <FaDollarSign />
    },
    {
      title: 'Completion Rate',
      value: isLoading ? '...' : `${stats.kpis?.completionRate ?? 0}%`,
      icon: <FaBullseye />
    },
    {
      title: 'New Projects (30d)',
      value: isLoading ? '...' : (stats.kpis?.newProjectsLast30 ?? 0).toLocaleString(),
      icon: <FaLayerGroup />,
      trend: stats.kpis?.newProjectsTrend ?? 0
    }
  ]

  return (
    <div>
      <div className='flex items-center justify-between mb-6'>
        <div>
          <h2 className='text-2xl font-bold text-gray-900 dark:text-white'>Dashboard Overview</h2>
          <p className='text-sm text-gray-500 dark:text-gray-400 mt-1'>Metrics comparison: Current 30 days vs Previous 30 days</p>
        </div>
        <button onClick={fetchDashboardStats} className='px-4 py-2 bg-accent text-white rounded-lg hover:bg-accent/90 transition-all text-sm font-medium'>
          Refresh Stats
        </button>
      </div>

      {error && <div className='mb-6 rounded-xl border border-red-200 dark:border-red-900/40 bg-red-50 dark:bg-red-900/20 px-4 py-3 text-sm text-red-700 dark:text-red-300'>{error}</div>}

      <div className='grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6'>
        {statCards.map((stat, index) => (
          <StatCard key={index} {...stat} isLoading={isLoading} />
        ))}
      </div>

      <div className='mt-8'>
        <div className='flex items-center gap-2 mb-4'>
          <FaChartLine className='text-accent' />
          <h3 className='text-lg font-semibold text-gray-900 dark:text-white'>Advanced KPI Metrics</h3>
        </div>
        <div className='grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6'>
          {kpiCards.map((stat, index) => (
            <StatCard key={`kpi-${index}`} {...stat} isLoading={isLoading} />
          ))}
        </div>
      </div>

      <AdminAlertsPanel isLoading={isLoading} alertSummary={stats.alertSummary} alerts={stats.alerts} healthSignals={stats.healthSignals} onOpenSection={onOpenSection} />
      <AdminAuditLogPanel />
    </div>
  )
}

