    const lastLoginDate = new Date(user.lastLogin)
    const threshold = new Date(Date.now() - INACTIVE_THRESHOLD_DAYS * 24 * 60 * 60 * 1000)

    return lastLoginDate < threshold ? 'Inactive' : 'Active'
  }

