import React, { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import { FaBriefcase, FaPlus, FaEdit, FaTrash, FaPlay, FaPause, FaCalendar } from 'react-icons/fa'
import CreateAnnouncementModal from '../../modal/CreateAnnouncementModal'
import { getUserAnnouncements, deleteAnnouncement, toggleAnnouncementStatus } from '../../services/announcementService'
import LoadingSpinner from '../shared/LoadingSpinner'
import AvailabilityCalendar from '../shared/AvailabilityCalendar'

const FreelanceTab = ({ user }) => {
  const isVerified = Boolean(user?.isEmailVerified)
  // Modal state
  const [isModalOpen, setIsModalOpen] = useState(false)

  const [announcements, setAnnouncements] = useState([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [editingAnnouncement, setEditingAnnouncement] = useState(null)

  // Fetch announcements when component mounts
  useEffect(() => {
    fetchAnnouncements()
  }, [])

  const fetchAnnouncements = async () => {
    try {
      setLoading(true)
      setError('')
      const data = await getUserAnnouncements()
      setAnnouncements(data)
    } catch (err) {
      console.error('Error fetching announcements:', err)
      setError('Failed to load announcements')
    } finally {
      setLoading(false)
    }
  }

  const handleDeleteAnnouncement = async (announcementId) => {
    if (window.confirm('Are you sure you want to delete this announcement?')) {
      try {
        await deleteAnnouncement(announcementId)
        setAnnouncements(announcements.filter((a) => a._id !== announcementId))
      } catch (err) {
        console.error('Error deleting announcement:', err)
        setError('Failed to delete announcement')
      }
    }
  }

  const handleEditAnnouncement = (announcement) => {
    setEditingAnnouncement(announcement)
    setIsModalOpen(true)
  }

  const handleToggleStatus = async (announcementId) => {
    try {
      const response = await toggleAnnouncementStatus(announcementId)
      const updatedAnnouncement = response.announcement
      setAnnouncements(announcements.map((a) => (a._id === announcementId ? updatedAnnouncement : a)))
    } catch (err) {
      console.error('Error toggling announcement status:', err)
      setError('Failed to toggle announcement status')
    }
  }

  return (
    <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -20 }} transition={{ duration: 0.3 }} className='space-y-6'>
      {/* Header with Create Announcement Button */}
      <div className='flex items-center justify-between'>
        <div className='flex items-center gap-3'>
          <FaBriefcase className='text-accent text-xl' />
          <h2 className='text-2xl font-bold theme-text'>My Freelance Announcements</h2>
        </div>
        <motion.button
          onClick={() => {
            if (!isVerified) return
            setIsModalOpen(true)
          }}
          disabled={!isVerified}
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          className='flex items-center gap-2 bg-accent text-white px-4 py-2 rounded-lg hover:bg-accent/90 transition-colors disabled:opacity-50 disabled:cursor-not-allowed'>
          <FaPlus />
          <span>Create Announcement</span>
        </motion.button>
      </div>

      {!isVerified && (
        <div className='rounded-lg border border-amber-300/40 bg-amber-500/10 px-4 py-3 text-sm text-amber-700 dark:text-amber-300'>
          Verify your email to publish freelance announcements. You can still edit your profile, but announcement publishing stays locked until verification is complete.
        </div>
      )}

      {/* Announcements List or Empty State */}
      <div className='bg-gradient-to-br dark:from-light/5 dark:via-light/[0.02] from-primary/5 via-primary/[0.02] to-transparent p-8 rounded-lg text-center border border-primary/10 dark:border-light/10 backdrop-blur-sm'>
        {loading ? (
          <div className='flex justify-center py-8'>
            <LoadingSpinner />
          </div>
        ) : error ? (
          <div className='bg-red-100 dark:bg-red-900/30 text-red-700 dark:text-red-300 p-4 rounded-lg'>{error}</div>
        ) : announcements.length === 0 ? (
          <div className='space-y-4 text-center'>
            <FaBriefcase className='text-5xl text-primary/40 dark:text-light/40 mx-auto' />
            <p className='theme-text-secondary text-lg'>No announcements yet. Create your first freelance announcement to get started!</p>
            <motion.button
              onClick={() => {
                if (!isVerified) return
                setIsModalOpen(true)
              }}
              disabled={!isVerified}
              whileHover={isVerified ? { scale: 1.05 } : {}}
              whileTap={isVerified ? { scale: 0.95 } : {}}
              className='inline-flex items-center gap-2 bg-accent text-white px-6 py-3 rounded-lg hover:bg-accent/90 transition-colors disabled:opacity-50 disabled:cursor-not-allowed'>
              <FaPlus />
              <span>{isVerified ? 'Create Your First Announcement' : 'Verify Email to Create Announcement'}</span>
            </motion.button>
          </div>
        ) : (
          <div className='grid grid-cols-1 md:grid-cols-3 gap-4'>
            {announcements.map((announcement, index) => (
              <motion.div
                key={announcement._id}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                whileHover={{
                  scale: 1.02,
                  transition: { duration: 0.1 }
                }}
                transition={{ duration: 0.2, delay: index * 0.1 }}
                className='p-6 rounded-lg bg-gradient-to-br dark:from-light/5 dark:via-light/[0.02] from-primary/5 via-primary/[0.02] to-transparent hover:shadow-lg hover:-translate-y-1 transition-all duration-300 group backdrop-blur-sm border border-primary/10 dark:border-light/10'>
                {/* Title Section */}
                <div className='flex items-start gap-4 mb-4'>
                  <div className='flex-1'>
                    <h3 className='flex text-xl font-bold mb-2 theme-text'>{announcement.title}</h3>
                    <div className='flex gap-2 flex-wrap'>
                      {announcement.skills.slice(0, 2).map((skill, idx) => (
                        <span key={idx} className='inline-block px-2 py-1 rounded-full text-xs font-medium bg-accent/20 text-accent'>
                          {skill}
                        </span>
                      ))}
                    </div>
                  </div>
                </div>

                {/* Rate Section */}
                <div className='flex items-center justify-between mb-3'>
                  <div className='flex items-center gap-1'>
                    <span className='font-medium theme-text'>Hourly Rate</span>
                  </div>
                  <span className='font-bold text-accent text-lg'>Γé¼{announcement.hourlyRate}/hr</span>
                </div>

                {/* Background Section */}
                <div className='flex items-center gap-2 theme-text-secondary text-sm line-clamp-2'>
                  <span>{announcement.background}</span>
                </div>

                {/* Status Badge */}
                <div className='mt-4 flex items-center justify-between'>
                  <span
                    className={`inline-block px-3 py-1 rounded-full text-xs font-bold ${
                      announcement.isActive ? 'bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-300' : 'bg-primary/10 dark:bg-light/10 text-primary/70 dark:text-light/70'
                    }`}>
                    {announcement.isActive ? 'ΓùÅ Active' : 'Γùï Paused'}
                  </span>
                  <div className='flex gap-2'>
                    <motion.button
                      whileHover={{ scale: 1.1 }}
                      whileTap={{ scale: 0.9 }}
                      onClick={() => handleToggleStatus(announcement._id)}
                      className={`p-1.5 rounded transition-colors ${
                        announcement.isActive ? 'text-orange-600 dark:text-orange-300 hover:bg-orange-100 dark:hover:bg-orange-900/30' : 'text-green-600 dark:text-green-300 hover:bg-green-100 dark:hover:bg-green-900/30'
                      }`}
                      title={announcement.isActive ? 'Pause announcement' : 'Resume announcement'}>
                      {announcement.isActive ? <FaPause size={14} /> : <FaPlay size={14} />}
                    </motion.button>
                    <motion.button
                      whileHover={{ scale: 1.1 }}
                      whileTap={{ scale: 0.9 }}
                      onClick={() => handleEditAnnouncement(announcement)}
                      className='p-1.5 rounded text-blue-600 dark:text-blue-300 hover:bg-blue-100 dark:hover:bg-blue-900/30 transition-colors'>
                      <FaEdit size={14} />
                    </motion.button>
                    <motion.button
                      whileHover={{ scale: 1.1 }}
                      whileTap={{ scale: 0.9 }}
                      onClick={() => handleDeleteAnnouncement(announcement._id)}
                      className='p-1.5 rounded text-red-600 dark:text-red-300 hover:bg-red-100 dark:hover:bg-red-900/30 transition-colors'>
                      <FaTrash size={14} />
                    </motion.button>
                  </div>
                </div>
              </motion.div>
            ))}
          </div>
        )}
      </div>
      {/* Create Announcement Modal */}
      <CreateAnnouncementModal
        isOpen={isModalOpen}
        onClose={() => {
          setIsModalOpen(false)
          setEditingAnnouncement(null)
        }}
        editingAnnouncement={editingAnnouncement}
        isVerified={isVerified}
        onAnnouncementCreated={(updatedAnnouncement) => {
          if (editingAnnouncement) {
            // Update existing announcement
            setAnnouncements(announcements.map((a) => (a._id === updatedAnnouncement._id ? updatedAnnouncement : a)))
            setEditingAnnouncement(null)
          } else {
            // Add new announcement
            setAnnouncements([updatedAnnouncement, ...announcements])
          }
        }}
      />

      {/* Availability Calendar Section */}
      <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3, delay: 0.1 }} className='space-y-4'>
        <div className='flex items-center gap-3'>
          <FaCalendar className='text-accent text-xl' />
          <h2 className='text-2xl font-bold theme-text'>My Availability</h2>
        </div>
        <div className='bg-gradient-to-br dark:from-light/5 dark:via-light/[0.02] from-primary/5 via-primary/[0.02] to-transparent rounded-lg overflow-hidden border border-primary/10 dark:border-light/10'>
          <AvailabilityCalendar freelancerId={user?._id} isOwnProfile={true} isPublicView={false} />
        </div>
      </motion.div>
    </motion.div>
  )
}

export default FreelanceTab

import { motion } from 'framer-motion'
import { FaEnvelope } from 'react-icons/fa'
import SenderBlock from './SenderBlock'
import LoadingSpinner from '../shared/LoadingSpinner'

const GroupedMessagesList = ({ messages, loading, projectId, isProjectCreator, onRefresh, systemEvents = [] }) => {
  // Get current user to exclude from interested count
  const currentUser = JSON.parse(localStorage.getItem('user') || '{}')

  // Group ALL messages by sender (including owner's)
  const groupedMessages = messages.reduce((groups, message) => {
    const senderId = message.sender._id

    if (!groups[senderId]) {
      groups[senderId] = {
        sender: message.sender,
        messages: []
      }
    }

    groups[senderId].messages.push(message)
    return groups
  }, {})

  // Convert to array and sort by first message time
  const sortedGroups = Object.values(groupedMessages).sort((a, b) => {
    const timeA = new Date(a.messages[0].createdAt)
    const timeB = new Date(b.messages[0].createdAt)
    return timeB - timeA // Newest first
  })

  // Filter out owner for counting interested people
  const interestedCount = sortedGroups.filter((group) => {
    const senderId = group.sender._id || group.sender
    return senderId !== currentUser._id
  }).length

  if (loading) {
    return (
      <div className='flex justify-center py-8'>
        <LoadingSpinner />
      </div>
    )
  }

  if (!messages || messages.length === 0) {
    return (
      <div className='text-center py-12'>
        <FaEnvelope className='text-6xl theme-text-secondary mx-auto mb-4 opacity-30' />
        <h3 className='text-xl font-semibold theme-text mb-2'>No messages yet</h3>
        <p className='theme-text-secondary'>People interested in your project will appear here.</p>
      </div>
    )
  }

  return (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.3 }} className='space-y-8'>
      {/* Summary */}
      <div className='p-4 bg-gradient-to-br dark:from-light/5 dark:via-light/[0.02] from-primary/5 via-primary/[0.02] to-transparent rounded-lg border border-primary/10 dark:border-light/10 backdrop-blur-sm'>
        <p className='theme-text font-semibold'>
          {interestedCount} {interestedCount === 1 ? 'person' : 'people'} interested in this project
        </p>
      </div>

      {/* System events */}
      {systemEvents.length > 0 && (
        <div className='space-y-2'>
          {systemEvents.map((event, idx) => (
            <div key={`system-${idx}`} className='flex items-center gap-3 text-xs theme-text-secondary bg-accent/5 border border-accent/10 rounded-lg px-3 py-2'>
              <span className='font-semibold text-accent'>System</span>
              <span className='flex-1'>{event.text}</span>
              <span className='whitespace-nowrap'>{event.time ? new Date(event.time).toLocaleDateString() : ''}</span>
            </div>
          ))}
        </div>
      )}

      {/* Grouped messages */}
      {sortedGroups.map((group, index) => (
        <SenderBlock key={group.sender._id} sender={group.sender} messages={group.messages} index={index} projectId={projectId} isProjectCreator={isProjectCreator} onAssignSuccess={onRefresh} />
      ))}
    </motion.div>
  )
}

export default GroupedMessagesList

import { useState, useRef } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { FaEnvelope, FaEnvelopeOpen, FaClock, FaBriefcase, FaArrowRight, FaPaperPlane, FaChevronDown, FaPlus } from 'react-icons/fa'
import { useNavigate } from 'react-router-dom'
import { sendMessage, markMessageAsRead, sendMessageWithAttachments } from '../../services/messageService'
import LoadingSpinner from '../shared/LoadingSpinner'

const MessagesList = ({ messages, loading, onReplySent }) => {
  const navigate = useNavigate()

  // State for managing replies per project
  const [replyTexts, setReplyTexts] = useState({}) // { projectId: 'reply text' }
  const [sendingStates, setSendingStates] = useState({}) // { projectId: true/false }

  // State for managing expanded/collapsed conversations
  const [expandedConversations, setExpandedConversations] = useState({}) // { projectId: true/false }

  // File upload state
  const fileInputRefs = useRef({}) // { projectId: ref }
  const [selectedFiles, setSelectedFiles] = useState({}) // { projectId: [files] }

  // Toggle conversation expansion and mark unread incoming messages as read when opening
  const toggleConversation = async (conversationKey, groupMessages) => {
    const isOpening = !expandedConversations[conversationKey]

    setExpandedConversations((prev) => ({
      ...prev,
      [conversationKey]: !prev[conversationKey]
    }))

    if (!isOpening) return

    const unreadIncomingMessages = getUnreadIncomingMessages(groupMessages)
    if (unreadIncomingMessages.length === 0) return

    try {
      await Promise.all(unreadIncomingMessages.map((message) => markMessageAsRead(message._id)))

      if (onReplySent) {
        await onReplySent()
      }
    } catch (error) {
      console.error('Failed to mark messages as read:', error)
    }
  }

  // Get current user from localStorage
  const currentUser = JSON.parse(localStorage.getItem('user') || '{}')

  // Format date nicely
  const formatDate = (dateString) => {
    const date = new Date(dateString)
    const now = new Date()
    const diffInHours = Math.floor((now - date) / (1000 * 60 * 60))

    if (diffInHours < 1) return 'Just now'
    if (diffInHours < 24) return `${diffInHours}h ago`
    if (diffInHours < 48) return 'Yesterday'
    return date.toLocaleDateString()
  }

  // Group messages by project ID or conversation (for direct messages)
  const groupMessagesByProject = () => {
    const grouped = {}

    messages.forEach((message) => {
      // Project-based messages
      if (message.project) {
        const projectId = message.project._id
        if (!grouped[projectId]) {
          grouped[projectId] = {
            project: message.project,
            messages: [],
            isDirectMessage: false
          }
        }
        grouped[projectId].messages.push(message)
      } else {
        // Direct messages - group by the other user (not current user)
        const otherUserId = message.sender._id === currentUser._id ? message.receiver._id : message.sender._id
        const conversationKey = `direct-${otherUserId}`

        if (!grouped[conversationKey]) {
          const otherUser = message.sender._id === currentUser._id ? message.receiver : message.sender
          grouped[conversationKey] = {
            projectTitle: `Conversation with ${otherUser.firstName} ${otherUser.lastName}`,
            otherUser: otherUser,
            messages: [],
            isDirectMessage: true
          }
        }
        grouped[conversationKey].messages.push(message)
      }
    })

    return Object.values(grouped).sort((a, b) => {
      const aLastMessage = a.messages?.[a.messages.length - 1]
      const bLastMessage = b.messages?.[b.messages.length - 1]

      const aTime = aLastMessage?.createdAt ? new Date(aLastMessage.createdAt).getTime() : 0
      const bTime = bLastMessage?.createdAt ? new Date(bLastMessage.createdAt).getTime() : 0

      return bTime - aTime
    })
  }

  const canReplyToUser = (user) => {
    return user?.userType !== 'admin'
  }

  const getLastMessagePreviewData = (groupMessages) => {
    if (!Array.isArray(groupMessages) || groupMessages.length === 0) {
      return null
    }

    const lastMessage = groupMessages[groupMessages.length - 1]
    const isOwnMessage = lastMessage.sender?._id === currentUser._id || lastMessage.sender === currentUser._id
    const senderName = isOwnMessage ? 'You' : lastMessage.sender?.firstName || 'Unknown'

    return {
      lastMessage,
      senderName,
      timestamp: formatDate(lastMessage.createdAt)
    }
  }

  const getUnreadIncomingMessages = (groupMessages) => {
    if (!Array.isArray(groupMessages)) return []

    return groupMessages.filter((message) => {
      const receiverId = message.receiver?._id || message.receiver
      return !message.isRead && receiverId === currentUser._id
    })
  }

  const handleReply = async (conversationKeyOrProjectId, receiverId, isDirectMessage = false) => {
    const replyText = replyTexts[conversationKeyOrProjectId]
    const files = selectedFiles[conversationKeyOrProjectId]

    // Don't send if empty
    if (!replyText || !replyText.trim()) return

    try {
      // Mark as sending
      setSendingStates({ ...sendingStates, [conversationKeyOrProjectId]: true })

      // Send the message
      if (files && files.length > 0) {
        // With file attachments
        if (isDirectMessage) {
          await sendMessageWithAttachments(receiverId, replyText, Array.from(files), null, null)
        } else {
          await sendMessageWithAttachments(receiverId, replyText, Array.from(files), null, conversationKeyOrProjectId)
        }
      } else {
        // Without file attachments
        if (isDirectMessage) {
          await sendMessage(receiverId, replyText, null, null)
        } else {
          await sendMessage(receiverId, replyText, null, conversationKeyOrProjectId)
        }
      }

      // Clear the input and files
      setReplyTexts({ ...replyTexts, [conversationKeyOrProjectId]: '' })
      setSelectedFiles({ ...selectedFiles, [conversationKeyOrProjectId]: undefined })

      if (onReplySent) {
        await onReplySent()
      }
    } catch (error) {
      console.error('Failed to send reply:', error)
    } finally {
      // Mark as not sending
      setSendingStates({ ...sendingStates, [conversationKeyOrProjectId]: false })
    }
  }

  if (loading) {
    return (
      <div className='flex justify-center py-8'>
        <LoadingSpinner />
      </div>
    )
  }

  if (!messages || messages.length === 0) {
    return (
      <div className='text-center py-12'>
        <FaEnvelope className='text-6xl theme-text-secondary mx-auto mb-4 opacity-30' />
        <h3 className='text-xl font-semibold theme-text mb-2'>No messages yet</h3>
        <p className='theme-text-secondary'>Messages about projects will appear here.</p>
      </div>
    )
  }

  const groupedMessages = groupMessagesByProject()

  return (
    <div className='space-y-6'>
      {groupedMessages.map((group, groupIndex) => {
        const { project, otherUser, messages: groupMessages, isDirectMessage } = group

        // HANDLE DIRECT MESSAGES
        if (isDirectMessage) {
          const conversationKey = `direct-${otherUser._id}`
          const currentReplyText = replyTexts[conversationKey] || ''
          const isSending = sendingStates[conversationKey] || false
          const title = otherUser.userType === 'admin' ? 'Message from Administrator' : `Conversation with ${otherUser.firstName} ${otherUser.lastName}`
          const canReplyDirect = canReplyToUser(otherUser)
          const lastMessagePreview = getLastMessagePreviewData(groupMessages)
          const unreadIncomingMessages = getUnreadIncomingMessages(groupMessages)

          return (
            <motion.div
              key={conversationKey}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.3, delay: groupIndex * 0.05 }}
              className='bg-gradient-to-br dark:from-light/5 dark:via-light/[0.02] from-primary/5 via-primary/[0.02] to-transparent p-6 rounded-lg hover:shadow-lg hover:-translate-y-1 transition-all border border-primary/10 dark:border-light/10 backdrop-blur-sm'>
              {/* Direct Message Header */}
              <div className='mb-4 pb-4 border-b dark:border-light/10 border-primary/10 cursor-pointer' onClick={() => toggleConversation(conversationKey, groupMessages)}>
                <div className='flex items-center justify-between'>
                  <div className='flex items-center gap-3 flex-1'>
                    <motion.div animate={{ rotate: expandedConversations[conversationKey] ? 180 : 0 }} transition={{ duration: 0.3 }}>
                      <FaChevronDown className='theme-text-secondary' />
                    </motion.div>
                    <FaEnvelope className='text-accent' />
                    <div className='flex-1'>
                      <p className='font-semibold theme-text'>
                        <button
                          onClick={(e) => {
                            e.stopPropagation()
                            if (otherUser.userType !== 'admin') {
                              navigate(`/freelancer/${otherUser._id}`)
                            }
                          }}
                          className='hover:text-accent transition-colors cursor-pointer underline'>
                          {title}
                        </button>
                      </p>
                      <p className='text-sm theme-text-secondary'>{otherUser.userType === 'admin' ? 'Administrator notice' : 'Direct message'}</p>
                    </div>
                    <div className='flex items-center gap-2'>
                      {unreadIncomingMessages.length > 0 ? <span className='px-2.5 py-1 rounded-full bg-red-500 text-white text-xs font-semibold'>{unreadIncomingMessages.length} unread</span> : null}

                      <div className='px-3 py-1 bg-accent/10 rounded-full'>
                        <span className='text-sm font-semibold text-accent'>
                          {groupMessages.length} {groupMessages.length === 1 ? 'message' : 'messages'}
                        </span>
                      </div>
                    </div>
                  </div>
                </div>
              </div>

              {!expandedConversations[conversationKey] && lastMessagePreview && (
                <div className='ml-8'>
                  <div className='flex items-center gap-2 text-sm'>
                    <span className='font-semibold theme-text'>{lastMessagePreview.senderName}:</span>
                    <span className='theme-text-secondary line-clamp-1 flex-1'>{lastMessagePreview.lastMessage.content}</span>
                    <span className='text-xs theme-text-secondary whitespace-nowrap'>{lastMessagePreview.timestamp}</span>
                  </div>
                </div>
              )}

              {/* Messages List */}
              <AnimatePresence>
                {expandedConversations[conversationKey] && (
                  <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} transition={{ duration: 0.3 }} className='overflow-hidden'>
                    <div className='space-y-3 mb-4 pt-4'>
                      {groupMessages.map((message, msgIndex) => {
                        const isOwnMessage = message.sender._id === currentUser._id || message.sender === currentUser._id
                        return (
                          <motion.div
                            key={message._id}
                            initial={{ opacity: 0, x: isOwnMessage ? 10 : -10 }}
                            animate={{ opacity: 1, x: 0 }}
                            transition={{ duration: 0.2, delay: msgIndex * 0.05 }}
                            className={`flex ${isOwnMessage ? 'justify-end' : 'justify-start'}`}>
                            <div
                              className={`max-w-[70%] p-4 rounded-lg ${
                                isOwnMessage
                                  ? 'bg-gradient-to-br dark:from-accent/20 dark:to-accent/10 from-accent/10 to-accent/5 border border-accent/20'
                                  : 'bg-gradient-to-br dark:from-light/5 dark:via-light/[0.02] from-primary/5 via-primary/[0.02] to-transparent border border-primary/10 dark:border-light/10'
                              }`}>
                              {!isOwnMessage && (
                                <div className='flex items-center gap-2 mb-2'>
                                  <img
                                    src={message.sender?.profilePicture || `https://i.pravatar.cc/150?u=${message.sender?._id}`}
                                    alt={message.sender?.firstName}
                                    className='w-6 h-6 rounded-full object-cover cursor-pointer hover:opacity-80'
                                    onClick={() => {
                                      if (message.sender?.userType !== 'admin') {
                                        navigate(`/freelancer/${message.sender?._id}`)
                                      }
                                    }}
                                    title={message.sender?.userType === 'admin' ? 'Administrator' : 'View profile'}
                                  />
                                  {message.sender?.userType === 'admin' ? (
                                    <span className='text-sm font-semibold theme-text'>Administrator</span>
                                  ) : (
                                    <button onClick={() => navigate(`/freelancer/${message.sender?._id}`)} className='text-sm font-semibold theme-text hover:text-accent transition-colors underline'>
                                      {message.sender?.firstName} {message.sender?.lastName}
                                    </button>
                                  )}
                                </div>
                              )}
                              {message.subject && <p className='text-sm font-semibold text-accent mb-2'>{message.subject}</p>}
                              {/* Message content */}
                              <p className={`theme-text leading-relaxed mb-2 ${isOwnMessage ? 'text-right' : ''}`}>{message.content}</p>

                              {/* Attachments Display */}
                              {message.attachments && message.attachments.length > 0 && (
                                <div className='mt-3 pt-3 border-t border-gray-300 dark:border-gray-600'>
                                  <p className='text-xs font-semibold text-gray-600 dark:text-gray-400 mb-2'>≡ƒôÄ Attachments ({message.attachments.length})</p>
                                  <div className='space-y-2'>
                                    {message.attachments.map((attachment, idx) => (
                                      <a
                                        key={idx}
                                        href={`/${attachment.path}`}
                                        download={attachment.originalName}
                                        className='flex items-center gap-2 p-2 bg-gray-100 dark:bg-gray-700 rounded hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors text-sm break-all'>
                                        <span className='text-xs'>≡ƒôä</span>
                                        <span className='text-gray-700 dark:text-gray-300 flex-1 truncate'>{attachment.originalName}</span>
                                        <span className='text-xs text-primary/60 dark:text-light/60 whitespace-nowrap'>{attachment.size < 1024 ? attachment.size + 'B' : (attachment.size / 1024).toFixed(1) + 'KB'}</span>
                                      </a>
                                    ))}
                                  </div>
                                </div>
                              )}

                              {/* Timestamp */}
                              <div className={`flex items-center gap-1 text-xs theme-text-secondary ${isOwnMessage ? 'justify-end' : ''}`}>
                                <FaClock />
                                <span>{formatDate(message.createdAt)}</span>
                                {message.isRead && <FaEnvelopeOpen className='text-green-500 ml-1' title='Read' />}
                              </div>
                            </div>
                          </motion.div>
                        )
                      })}
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>

              {/* Reply Input or Admin Notice */}
              {expandedConversations[conversationKey] &&
                (canReplyDirect ? (
                  <div className='flex gap-2 pt-4 border-t dark:border-light/10 border-primary/10'>
                    <input
                      type='text'
                      value={currentReplyText}
                      onChange={(e) => setReplyTexts({ ...replyTexts, [conversationKey]: e.target.value })}
                      placeholder='Type your reply...'
                      className='flex-1 px-4 py-2 rounded-lg border border-primary/50 dark:border-light/10 theme-bg theme-text focus:outline-none focus:ring-2 focus:ring-accent/20 focus:border-accent'
                      onKeyPress={(e) => {
                        if (e.key === 'Enter' && !e.shiftKey) {
                          e.preventDefault()
                          handleReply(conversationKey, otherUser._id, true)
                        }
                      }}
                    />
                    <motion.button
                      onClick={() => handleReply(conversationKey, otherUser._id, true)}
                      disabled={!currentReplyText.trim() || isSending}
                      className='px-6 py-2 bg-accent text-white rounded-lg hover:bg-accent/90 disabled:opacity-50 disabled:cursor-not-allowed transition-all flex items-center gap-2'
                      whileHover={{ scale: 1.02 }}
                      whileTap={{ scale: 0.98 }}>
                      {isSending ? (
                        'Sending...'
                      ) : (
                        <>
                          <FaPaperPlane /> Reply
                        </>
                      )}
                    </motion.button>
                  </div>
                ) : (
                  <p className='text-sm theme-text-secondary pt-4 border-t dark:border-light/10 border-primary/10'>Replies are disabled for administrator notices.</p>
                ))}
            </motion.div>
          )
        }

        // HANDLE PROJECT-BASED MESSAGES (existing code)
        const otherPersonMessage = groupMessages.find((msg) => (msg.sender._id || msg.sender) !== currentUser._id)
        const isProjectOwner = (project.user._id || project.user) === currentUser._id
        const receiverId = isProjectOwner ? otherPersonMessage?.sender._id || otherPersonMessage?.sender : project.user._id || project.user

        const currentReplyText = replyTexts[project._id] || ''
        const isSending = sendingStates[project._id] || false
        const unreadIncomingMessages = getUnreadIncomingMessages(groupMessages)

        return (
          <motion.div
            key={project._id}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.3, delay: groupIndex * 0.05 }}
            className='bg-gradient-to-br dark:from-light/5 dark:via-light/[0.02] from-primary/5 via-primary/[0.02] to-transparent p-6 rounded-lg hover:shadow-lg hover:-translate-y-1 transition-all border border-primary/10 dark:border-light/10 backdrop-blur-sm'>
            {/* Project Header - Clickable Accordion */}
            <div className='mb-4 pb-4 border-b dark:border-light/10 border-primary/10 cursor-pointer' onClick={() => toggleConversation(project._id, groupMessages)}>
              <div className='flex items-center justify-between'>
                <div className='flex items-center gap-3 flex-1'>
                  {/* Expand/Collapse Icon */}
                  <motion.div animate={{ rotate: expandedConversations[project._id] ? 180 : 0 }} transition={{ duration: 0.3 }}>
                    <FaChevronDown className='theme-text-secondary' />
                  </motion.div>

                  {/* Project Info */}
                  <FaBriefcase className='text-accent' />
                  <div className='flex-1'>
                    <p className='font-semibold theme-text'>{project.title}</p>
                    {project.category && <p className='text-sm theme-text-secondary'>{project.category}</p>}
                  </div>

                  {/* Message Count Badge */}
                  <div className='flex items-center gap-2'>
                    {unreadIncomingMessages.length > 0 ? <span className='px-2.5 py-1 rounded-full bg-red-500 text-white text-xs font-semibold'>{unreadIncomingMessages.length} unread</span> : null}

                    <div className='px-3 py-1 bg-accent/10 rounded-full'>
                      <span className='text-sm font-semibold text-accent'>
                        {groupMessages.length} {groupMessages.length === 1 ? 'message' : 'messages'}
                      </span>
                    </div>
                  </div>
                </div>

                {/* View Project Button - Stop propagation to prevent accordion toggle */}
                <motion.button
                  onClick={(e) => {
                    e.stopPropagation() // Prevent accordion toggle when clicking button
                    navigate(`/project/${project._id}`)
                  }}
                  whileHover={{ scale: 1.05 }}
                  whileTap={{ scale: 0.95 }}
                  className='flex items-center gap-2 px-3 py-2 bg-accent/10 text-accent rounded-lg 
                  hover:bg-accent hover:text-white transition-all text-sm ml-3'>
                  View Project
                  <FaArrowRight />
                </motion.button>
              </div>

              {/* Last Message Preview (when collapsed) - Show most recent message */}
              {!expandedConversations[project._id] &&
                groupMessages.length > 0 &&
                (() => {
                  // Get the most recent message (first in sorted array)
                  const lastMessage = groupMessages[groupMessages.length - 1] // Newest at end
                  const isOwnMessage = lastMessage.sender._id === currentUser._id || lastMessage.sender === currentUser._id

                  // Format sender name: "You" for own messages, first name for others
                  const senderName = isOwnMessage ? 'You' : lastMessage.sender?.firstName || 'Unknown'

                  return (
                    <div className='mt-3 ml-8'>
                      <div className='flex items-center gap-2 text-sm'>
                        {/* Sender name with styling */}
                        <span className='font-semibold theme-text'>{senderName}:</span>
                        {/* Message preview - truncated */}
                        <span className='theme-text-secondary line-clamp-1 flex-1'>{lastMessage.content}</span>
                        {/* Timestamp */}
                        <span className='text-xs theme-text-secondary whitespace-nowrap'>{formatDate(lastMessage.createdAt)}</span>
                      </div>
                    </div>
                  )
                })()}
            </div>

            {/* Expanded Project Messages */}
            {expandedConversations[project._id] && (
              <AnimatePresence>
                <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} transition={{ duration: 0.3 }} className='overflow-hidden'>
                  <div className='space-y-3 mb-4 pt-4'>
                    {groupMessages.map((message, msgIndex) => {
                      const isOwnMessage = message.sender._id === currentUser._id || message.sender === currentUser._id
                      return (
                        <motion.div
                          key={message._id}
                          initial={{ opacity: 0, x: isOwnMessage ? 10 : -10 }}
                          animate={{ opacity: 1, x: 0 }}
                          transition={{ duration: 0.2, delay: msgIndex * 0.05 }}
                          className={`flex ${isOwnMessage ? 'justify-end' : 'justify-start'}`}>
                          <div
                            className={`max-w-[70%] p-4 rounded-lg backdrop-blur-sm ${isOwnMessage ? 'bg-gradient-to-br dark:from-accent/20 dark:to-accent/10 from-accent/10 to-accent/5 border border-accent/20' : 'bg-gradient-to-br dark:from-light/5 dark:via-light/[0.02] from-primary/5 via-primary/[0.02] to-transparent border border-primary/10 dark:border-light/10'}`}>
                            {!isOwnMessage && (
                              <div className='flex items-center gap-2 mb-2'>
                                <img
                                  src={message.sender?.profilePicture || `https://i.pravatar.cc/150?u=${message.sender?._id}`}
                                  alt={message.sender?.firstName}
                                  className='w-6 h-6 rounded-full object-cover cursor-pointer hover:opacity-80'
                                  onClick={() => {
                                    if (message.sender?.userType !== 'admin') {
                                      navigate(`/freelancer/${message.sender?._id}`)
                                    }
                                  }}
                                  title={message.sender?.userType === 'admin' ? 'Administrator' : 'View profile'}
                                />
                                {message.sender?.userType === 'admin' ? (
                                  <span className='text-sm font-semibold theme-text'>Administrator</span>
                                ) : (
                                  <button onClick={() => navigate(`/freelancer/${message.sender?._id}`)} className='text-sm font-semibold theme-text hover:text-accent transition-colors underline'>
                                    {message.sender?.firstName} {message.sender?.lastName}
                                  </button>
                                )}
                              </div>
                            )}
                            {message.subject && <p className='text-sm font-semibold text-accent mb-2'>{message.subject}</p>}
                            <p className={`theme-text leading-relaxed mb-2 ${isOwnMessage ? 'text-right' : ''}`}>{message.content}</p>

                            {/* Attachments Display */}
                            {message.attachments && message.attachments.length > 0 && (
                              <div className='mt-3 pt-3 border-t border-gray-300 dark:border-gray-600'>
                                <p className='text-xs font-semibold text-gray-600 dark:text-gray-400 mb-2'>≡ƒôÄ Attachments ({message.attachments.length})</p>
                                <div className='space-y-2'>
                                  {message.attachments.map((attachment, idx) => (
                                    <a
                                      key={idx}
                                      href={`/${attachment.path}`}
                                      download={attachment.originalName}
                                      className='flex items-center gap-2 p-2 bg-gray-100 dark:bg-gray-700 rounded hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors text-sm break-all'>
                                      <span className='text-xs'>≡ƒôä</span>
                                      <span className='text-gray-700 dark:text-gray-300 flex-1 truncate'>{attachment.originalName}</span>
                                      <span className='text-xs text-gray-500 dark:text-gray-400 whitespace-nowrap'>{attachment.size < 1024 ? attachment.size + 'B' : (attachment.size / 1024).toFixed(1) + 'KB'}</span>
                                    </a>
                                  ))}
                                </div>
                              </div>
                            )}

                            <div className={`flex items-center gap-1 text-xs theme-text-secondary ${isOwnMessage ? 'justify-end' : ''}`}>
                              <FaClock />
                              <span>{formatDate(message.createdAt)}</span>
                              {message.isRead && <FaEnvelopeOpen className='text-green-500 ml-1' title='Read' />}
                            </div>
                          </div>
                        </motion.div>
                      )
                    })}
                  </div>
                </motion.div>
              </AnimatePresence>
            )}

            {/* Reply Input - Only show if there's another person in the conversation */}
            {expandedConversations[project._id] && otherPersonMessage && (
              <div className='pt-4 border-t dark:border-light/10 border-primary/10'>
                {/* File Display Preview */}
                {selectedFiles[project._id] && selectedFiles[project._id].length > 0 && (
                  <div className='mb-3 p-3 bg-blue-50 dark:bg-blue-900/30 rounded-lg border border-blue-200 dark:border-blue-800'>
                    <p className='text-xs font-semibold text-blue-700 dark:text-blue-300 mb-2'>≡ƒôÄ Selected Files:</p>
                    <div className='space-y-1'>
                      {Array.from(selectedFiles[project._id]).map((file, idx) => (
                        <div key={idx} className='flex items-center justify-between text-xs text-blue-600 dark:text-blue-400'>
                          <span>{file.name}</span>
                          <button
                            type='button'
                            onClick={() => {
                              const newFiles = Array.from(selectedFiles[project._id]).filter((_, i) => i !== idx)
                              if (newFiles.length === 0) {
                                setSelectedFiles({ ...selectedFiles, [project._id]: undefined })
                              } else {
                                setSelectedFiles({ ...selectedFiles, [project._id]: newFiles })
                              }
                            }}
                            className='text-blue-500 hover:text-blue-700'>
                            Remove
                          </button>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* Input Area */}
                <div className='flex gap-2'>
                  <input
                    type='text'
                    value={currentReplyText}
                    onChange={(e) => setReplyTexts({ ...replyTexts, [project._id]: e.target.value })}
                    placeholder='Type your reply...'
                    className='flex-1 px-4 py-2 rounded-lg border dark:border-gray-700 border-gray-300 theme-bg theme-text focus:outline-none focus:border-accent'
                    onKeyPress={(e) => {
                      if (e.key === 'Enter' && !e.shiftKey) {
                        e.preventDefault()
                        handleReply(project._id, receiverId)
                      }
                    }}
                  />

                  {/* File Upload Button */}
                  <input
                    ref={(el) => {
                      if (el) fileInputRefs.current[project._id] = el
                    }}
                    type='file'
                    multiple
                    accept='*/*'
                    onChange={(e) => setSelectedFiles({ ...selectedFiles, [project._id]: e.target.files })}
                    className='hidden'
                  />
                  <motion.button
                    type='button'
                    onClick={() => fileInputRefs.current[project._id]?.click()}
                    className='px-4 py-2 bg-gray-200 dark:bg-gray-700 text-gray-700 dark:text-gray-300 rounded-lg hover:bg-gray-300 dark:hover:bg-gray-600 transition-all'
                    whileHover={{ scale: 1.02 }}
                    whileTap={{ scale: 0.98 }}
                    title='Attach files'>
                    <FaPlus />
                  </motion.button>

                  {/* Send Button */}
                  <motion.button
                    onClick={() => handleReply(project._id, receiverId)}
                    disabled={!currentReplyText.trim() || isSending}
                    className='px-6 py-2 bg-accent text-white rounded-lg hover:bg-accent/90 disabled:opacity-50 disabled:cursor-not-allowed transition-all flex items-center gap-2'
                    whileHover={{ scale: 1.02 }}
                    whileTap={{ scale: 0.98 }}>
                    {isSending ? (
                      'Sending...'
                    ) : (
                      <>
                        <FaPaperPlane />
                        Reply
                      </>
                    )}
                  </motion.button>
                </div>
              </div>
            )}
          </motion.div>
        )
      })}
    </div>
  )
}

export default MessagesList

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import {
  FaUser,
  FaEnvelope,
  FaPhone,
  FaMapMarkerAlt,
  FaTools,
  FaBook,
  FaGlobe,
  FaGithub,
  FaLinkedin,
  FaTwitter,
  FaStar,
  FaLanguage,
  FaCertificate,
  FaList,
  FaBriefcase,
  FaSyncAlt,
  FaChevronDown,
  FaClock,
  FaEye
} from 'react-icons/fa'
import { toast } from 'react-toastify'
import { useAuth } from '../../context/AuthContext'
import LoadingSpinner from '../shared/LoadingSpinner'
import { calculateProfileCompleteness } from '../../utils/profileCompleteness'

// Initial form state with empty values
const initialFormState = {
  fullName: '',
  email: '',
  phone: '',
  location: '',
  skills: '',
  bio: '',
  headline: '',
  availabilityStatus: 'available',
  profileVisibility: 'public',
  responseTime: 'within_24_hours',
  servicesOffered: '',
  tools: '',
  workPreference: 'flexible',
  yearsOfExperience: '',
  minimumProjectBudget: '',
  preferredProjectSize: 'flexible',
  preferredEngagements: '',
  timezone: '',
  availabilityDetails: '',
  industries: '',
  showLocationPublic: true,
  showHourlyRate: true,
  allowDirectMessages: true,
  allowProjectInvites: true,
  emailNotificationsEnabled: true,
  emailNotificationsMessages: true,
  emailNotificationsConnections: true,
  emailNotificationsProjects: true,
  website: '',
  github: '',
  linkedin: '',
  twitter: '',
  hourlyRate: '',
  experienceLevel: 'entry',
  languages: '',
  certifications: '',
  serviceCategories: '',
  upworkProfile: '',
  fiverrProfile: '',
  profilePicture: ''
}

const ProfileSettings = () => {
  const { currentUser, updateUserProfile } = useAuth()
  const profileCompleteness = calculateProfileCompleteness(currentUser)
  const missingRequired = profileCompleteness?.missingRequired ?? []
  const missingOptional = profileCompleteness?.missingOptional ?? []
  const userRole = currentUser?.userType || 'freelancer'
  // Show freelancer fields for freelancer, both roles, and admin
  const showFreelancerSection = userRole === 'freelancer' || userRole === 'both' || userRole === 'admin'

  const [formData, setFormData] = useState(initialFormState)
  const [savedFormData, setSavedFormData] = useState(initialFormState)
  const [errors, setErrors] = useState({})
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [isLoading, setIsLoading] = useState(!currentUser)

  // Helper function to populate form with user data
  const populateFormWithUserData = (user) => {
    if (!user) return

    const nextFormData = {
      fullName: `${user.firstName || ''} ${user.lastName || ''}`.trim(),
      email: user.email || '',
      phone: user.phone || '',
      location: user.location || '',
      skills: user.skills || '',
      bio: user.bio || '',
      headline: user.headline || '',
      availabilityStatus: user.availabilityStatus || 'available',
      profileVisibility: user.profileVisibility || 'public',
      responseTime: user.responseTime || 'within_24_hours',
      servicesOffered: user.servicesOffered || '',
      tools: user.tools || '',
      workPreference: user.workPreference || 'flexible',
      yearsOfExperience: user.yearsOfExperience ?? '',
      minimumProjectBudget: user.minimumProjectBudget ?? '',
      preferredProjectSize: user.preferredProjectSize || 'flexible',
      preferredEngagements: Array.isArray(user.preferredEngagements) ? user.preferredEngagements.join(', ') : '',
      timezone: user.timezone || '',
      availabilityDetails: user.availabilityDetails || '',
      industries: user.industries || '',
      showLocationPublic: user.showLocationPublic ?? true,
      showHourlyRate: user.showHourlyRate ?? true,
      allowDirectMessages: user.allowDirectMessages ?? true,
      allowProjectInvites: user.allowProjectInvites ?? true,
      emailNotificationsEnabled: user.emailNotificationsEnabled ?? true,
      emailNotificationsMessages: user.emailNotificationsMessages ?? true,
      emailNotificationsConnections: user.emailNotificationsConnections ?? true,
      emailNotificationsProjects: user.emailNotificationsProjects ?? true,
      website: user.website || '',
      github: user.github || '',
      linkedin: user.linkedin || '',
      twitter: user.twitter || '',
      profilePicture: user.profilePicture || '',
      hourlyRate: user.hourlyRate ?? '',
      experienceLevel: user.experienceLevel || 'entry',
      languages: user.languages || '',
      certifications: user.certifications || '',
      serviceCategories: user.serviceCategories || '',
      upworkProfile: user.upworkProfile || '',
      fiverrProfile: user.fiverrProfile || ''
    }

    setFormData(nextFormData)
    setSavedFormData(nextFormData)
    setIsLoading(false)
  }

  // Update form data when currentUser becomes available
  useEffect(() => {
    if (!currentUser) {
      setIsLoading(true)
      return
    }

    populateFormWithUserData(currentUser)
  }, [currentUser])

  // Handle form field changes
  const handleChange = (e) => {
    const { name, value, type, checked } = e.target
    const nextValue = type === 'checkbox' ? checked : value

    setFormData((prev) => {
      if (name === 'emailNotificationsEnabled') {
        if (!checked) {
          return {
            ...prev,
            emailNotificationsEnabled: false,
            emailNotificationsMessages: false,
            emailNotificationsConnections: false,
            emailNotificationsProjects: false
          }
        }

        const hasAnyEmailCategoryEnabled = prev.emailNotificationsMessages || prev.emailNotificationsConnections || prev.emailNotificationsProjects

        return {
          ...prev,
          emailNotificationsEnabled: true,
          emailNotificationsMessages: hasAnyEmailCategoryEnabled ? prev.emailNotificationsMessages : true,
          emailNotificationsConnections: hasAnyEmailCategoryEnabled ? prev.emailNotificationsConnections : true,
          emailNotificationsProjects: hasAnyEmailCategoryEnabled ? prev.emailNotificationsProjects : true
        }
      }

      return {
        ...prev,
        [name]: nextValue
      }
    })

    setErrors((prev) => {
      if (!prev[name]) return prev

      const nextErrors = { ...prev }
      delete nextErrors[name]
      return nextErrors
    })
  }

  const hasUnsavedChanges = JSON.stringify(formData) !== JSON.stringify(savedFormData)
  const currentAvatarUrl = formData.profilePicture || `https://i.pravatar.cc/150?u=${currentUser?._id || 'default'}`
  const savedAvatarUrl = savedFormData.profilePicture || `https://i.pravatar.cc/150?u=${currentUser?._id || 'default'}`
  const hasAvatarChanges = currentAvatarUrl !== savedAvatarUrl
  const activeEmailPreferenceCount = [formData.emailNotificationsMessages, formData.emailNotificationsConnections, formData.emailNotificationsProjects].filter(Boolean).length

  // Validate all form fields and return if valid
  const validateForm = () => {
    const newErrors = {}

    if (!formData.fullName.trim()) {
      newErrors.fullName = 'Full name is required'
    }

    if (!formData.email.trim()) {
      newErrors.email = 'Email is required'
    } else if (!/^\S+@\S+\.\S+$/.test(formData.email)) {
      newErrors.email = 'Please enter a valid email'
    }

    if (!formData.headline.trim()) {
      newErrors.headline = 'Professional headline is required'
    }

    if (!formData.skills.trim()) {
      newErrors.skills = 'Skills are required'
    }

    if (!formData.bio.trim()) {
      newErrors.bio = 'Bio is required'
    }

    if (!formData.servicesOffered.trim()) {
      newErrors.servicesOffered = 'Services offered is required'
    }

    if (formData.phone && !/^\+[0-9 ]{8,20}$/.test(formData.phone.replace(/_/g, ''))) {
      newErrors.phone = 'Please enter a valid phone number'
    }

    const numericFields = [
      { name: 'hourlyRate', label: 'Hourly rate' },
      { name: 'minimumProjectBudget', label: 'Minimum project budget' },
      { name: 'yearsOfExperience', label: 'Years of experience' }
    ]

    numericFields.forEach(({ name, label }) => {
      if (formData[name] !== '' && (Number.isNaN(Number(formData[name])) || Number(formData[name]) < 0)) {
        newErrors[name] = `${label} must be 0 or greater`
      }
    })

    const urlFields = ['website', 'github', 'linkedin', 'twitter', 'upworkProfile', 'fiverrProfile']
    urlFields.forEach((field) => {
      if (formData[field] && !/^(https?:\/\/)?([\da-z.-]+)\.([a-z.]{2,6})([/\w .-]*)*\/?$/.test(formData[field])) {
        newErrors[field] = 'Please enter a valid URL'
      }
    })

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  // Submit form data to API
  const handleSubmit = async (e) => {
    e.preventDefault()

    if (validateForm()) {
      setIsSubmitting(true)

      try {
        // Split fullName into firstName and lastName
        const nameParts = formData.fullName.split(' ')
        const firstName = nameParts[0] || ''
        const lastName = nameParts.slice(1).join(' ') || ''

        // Prepare the data for the API
        const profileData = {
          firstName,
          lastName,
          phone: formData.phone,
          location: formData.location,
          skills: formData.skills,
          bio: formData.bio,
          headline: formData.headline,
          availabilityStatus: formData.availabilityStatus,
          profileVisibility: formData.profileVisibility,
          responseTime: formData.responseTime,
          servicesOffered: formData.servicesOffered,
          tools: formData.tools,
          workPreference: formData.workPreference,
          yearsOfExperience: formData.yearsOfExperience === '' ? undefined : Number(formData.yearsOfExperience),
          minimumProjectBudget: formData.minimumProjectBudget === '' ? undefined : Number(formData.minimumProjectBudget),
          preferredProjectSize: formData.preferredProjectSize,
          preferredEngagements: formData.preferredEngagements
            .split(',')
            .map((item) => item.trim())
            .filter(Boolean),
          timezone: formData.timezone,
          availabilityDetails: formData.availabilityDetails,
          industries: formData.industries,
          showLocationPublic: formData.showLocationPublic,
          showHourlyRate: formData.showHourlyRate,
          allowDirectMessages: formData.allowDirectMessages,
          allowProjectInvites: formData.allowProjectInvites,
          emailNotificationsEnabled: formData.emailNotificationsEnabled,
          emailNotificationsMessages: formData.emailNotificationsMessages,
          emailNotificationsConnections: formData.emailNotificationsConnections,
          emailNotificationsProjects: formData.emailNotificationsProjects,
          website: formData.website,
          github: formData.github,
          linkedin: formData.linkedin,
          twitter: formData.twitter,
          profilePicture: formData.profilePicture,
          hourlyRate: formData.hourlyRate === '' ? undefined : Number(formData.hourlyRate),
          experienceLevel: formData.experienceLevel,
          languages: formData.languages,
          certifications: formData.certifications,
          serviceCategories: formData.serviceCategories,
          upworkProfile: formData.upworkProfile,
          fiverrProfile: formData.fiverrProfile
        }

        // Send profile update to API
        const response = await updateUserProfile(profileData)

        // Update the form state with the response to refresh the image display
        setFormData((prev) => {
          const nextFormData = {
            ...prev,
            profilePicture: response.profilePicture || prev.profilePicture
          }

          setSavedFormData(nextFormData)
          return nextFormData
        })

        setErrors({})
        toast.success('Changes saved successfully!')
      } catch (error) {
        const message = error.response?.data?.message || 'Failed to save changes. Please try again.'
        const validationErrors = error.response?.data?.errors

        if (validationErrors && typeof validationErrors === 'object') {
          const nextErrors = {}

          Object.entries(validationErrors).forEach(([field, details]) => {
            if (details?.message) {
              nextErrors[field] = details.message
            }
          })

          if (Object.keys(nextErrors).length > 0) {
            setErrors(nextErrors)
          }
        }

        toast.error(message)
      } finally {
        setIsSubmitting(false)
      }
    }
  }

  // Reset form to current user data or initial state
  const handleReset = () => {
    if (!hasUnsavedChanges) return

    if (currentUser) {
      populateFormWithUserData(currentUser)
    } else {
      setFormData(initialFormState)
      setSavedFormData(initialFormState)
      setIsLoading(false)
    }

    setErrors({})
    setIsSubmitting(false)
    toast.info('Form has been reset')
  }

  // Utility function for input field CSS classes
  const inputClasses = (errorField) => `
    w-full pl-10 p-3 rounded-lg
    theme-input theme-text
    transition-all duration-300
    border ${errors[errorField] ? 'border-red-500' : 'dark:border-light/10 border-primary/10'}
    dark:placeholder:text-light/40 placeholder:text-primary/40
    dark:focus:placeholder:text-light/60 focus:placeholder:text-primary/60
    focus:outline-none focus:ring-2 focus:ring-accent/50
  `
  const selectShellClasses = (errorField) => `
    relative rounded-lg
    bg-primary/15 dark:bg-light/12
    transition-all duration-300
    border ${errors[errorField] ? 'border-red-500' : 'border-primary/15 dark:border-light/10'}
    shadow-[inset_0_1px_0_rgba(255,255,255,0.04)]
    hover:border-accent/35 hover:bg-primary/20 dark:hover:bg-light/15
    focus-within:border-accent/45
    focus-within:ring-2 focus-within:ring-accent/50
  `
  const selectFieldClasses = `
    w-full min-h-[50px] bg-transparent theme-text
    pl-10 pr-10 py-3 rounded-lg
    appearance-none theme-select
    focus:outline-none
  `
  const selectIconClasses = 'absolute left-3 top-1/2 -translate-y-1/2 text-accent text-[16px] pointer-events-none'
  const selectChevronClasses = 'absolute right-3 top-1/2 -translate-y-1/2 text-accent text-[14px] pointer-events-none'
  const toggleClasses = 'h-4 w-4 rounded border-primary/20 text-accent focus:ring-accent/50 dark:border-light/20 dark:bg-transparent'

  return (
    <motion.div className='space-y-8' initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.5 }}>
      {isLoading ? (
        <div className='flex justify-center items-center h-64'>
          <LoadingSpinner />
        </div>
      ) : (
        <>
          <motion.div className='mb-6 p-4 rounded-lg bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700' initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3 }}>
            <div className='flex items-center justify-between gap-4 flex-wrap'>
              <div>
                <p className='text-sm theme-text-secondary'>Profile completion</p>
                <p className='text-xl font-bold theme-text'>{profileCompleteness?.percentage ?? 0}%</p>
              </div>
              <div className='text-sm theme-text-secondary'>
                <p>Missing required: {missingRequired.length}</p>
                <p>Missing optional: {missingOptional.length}</p>
              </div>
            </div>

            <div className='flex items-center justify-between gap-4 flex-wrap'>
              {missingRequired.length > 0 && (
                <div className='mt-3'>
                  <p className='text-xs uppercase tracking-wide text-red-500 mb-1'>Required fields to complete</p>
                  <p className='text-sm theme-text-secondary'>{missingRequired.map((item) => item.label).join(', ')}</p>
                </div>
              )}
              <div className='text-sm theme-text-secondary'>
                <p className={hasUnsavedChanges ? 'text-amber-500' : 'theme-text-secondary'}>{hasUnsavedChanges ? 'Changes not saved yet' : 'Profile is up to date'}</p>
              </div>
            </div>
          </motion.div>

          <form onSubmit={handleSubmit}>
            <motion.div className='grid lg:grid-cols-2 gap-6 mb-8' initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.6 }}>
              {/* Basic Information */}
              <motion.div className='p-6 rounded-lg bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 h-full'>
                <h3 className='text-xl font-semibold theme-text mb-2'>Basic Information</h3>
                <p className='text-sm theme-text-secondary mb-4'>Details people use to recognize you and understand your background quickly.</p>
                <div className='grid gap-5'>
                  <div className='p-4 rounded-xl theme-input border theme-border'>
                    <div className='mb-4'>
                      <p className='text-xs uppercase tracking-wide theme-text-muted mb-2'>Identity</p>
                    </div>

                    <div className='space-y-5'>
                      <div className='flex flex-col items-center text-center p-4 rounded-xl bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700'>
                        <img key={currentAvatarUrl} src={currentAvatarUrl} alt='Profile' className='w-24 h-24 rounded-full border-2 border-gray-300 dark:border-gray-600 shadow-lg mb-4 object-cover' />

                        <div className='flex flex-wrap items-center justify-center gap-3'>
                          <motion.button
                            type='button'
                            onClick={() => {
                              const randomSeed = Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15)
                              const newAvatarUrl = `https://i.pravatar.cc/150?u=${randomSeed}`
                              setFormData((prev) => ({ ...prev, profilePicture: newAvatarUrl }))
                            }}
                            className='flex items-center gap-2 bg-accent text-white px-4 py-2 rounded-lg hover:bg-accent/90 hover:shadow-lg transition-all duration-300'
                            whileHover={{ scale: 1.05 }}
                            whileTap={{ scale: 0.95 }}>
                            <FaSyncAlt className='text-sm' />
                            <span className='text-sm font-medium'>Generate New Avatar</span>
                          </motion.button>

                          {hasAvatarChanges && (
                            <motion.button
                              type='button'
                              onClick={() =>
                                setFormData((prev) => ({
                                  ...prev,
                                  profilePicture: savedFormData.profilePicture
                                }))
                              }
                              className='px-4 py-2 rounded-lg border dark:border-light/10 border-primary/10 theme-text hover:text-accent hover:border-accent/40 hover:shadow-md transition-all duration-300'
                              whileHover={{ scale: 1.05 }}
                              whileTap={{ scale: 0.95 }}>
                              Use Current Avatar
                            </motion.button>
                          )}
                        </div>
                      </div>

                      <div>
                        <label className='block mb-2 theme-text-secondary text-sm'>Full Name</label>
                        <div className='relative'>
                          <span className='absolute left-3 top-4 text-accent text-[16px]'>
                            <FaUser />
                          </span>
                          <input type='text' name='fullName' value={formData.fullName} onChange={handleChange} className={inputClasses('fullName')} placeholder='Enter your full name' />
                          {errors.fullName && (
                            <motion.p initial={{ opacity: 0 }} animate={{ opacity: 1 }} className='text-red-500 text-sm mt-1'>
                              {errors.fullName}
                            </motion.p>
                          )}
                        </div>
                      </div>
                    </div>
                  </div>

                  <div className='p-4 rounded-xl theme-input border theme-border'>
                    <div className='mb-4'>
                      <p className='text-xs uppercase tracking-wide theme-text-muted mb-2'>Contact</p>
                      <p className='text-sm theme-text-secondary'>Show the primary ways clients or collaborators can identify and reach you.</p>
                    </div>

                    <div className='space-y-4'>
                      <div>
                        <label className='block mb-2 theme-text-secondary text-sm'>Email</label>
                        <div className='relative'>
                          <span className='absolute left-3 top-4 text-accent text-[16px]'>
                            <FaEnvelope />
                          </span>
                          <input
                            type='email'
                            name='email'
                            value={formData.email}
                            onChange={handleChange}
                            readOnly
                            className={`${inputClasses('email')} cursor-not-allowed opacity-80`}
                            placeholder='Enter your email address'
                          />
                          <p className='text-xs theme-text-muted mt-2'>Email changes require a separate verification flow and cannot be edited here.</p>
                          {errors.email && (
                            <motion.p initial={{ opacity: 0 }} animate={{ opacity: 1 }} className='text-red-500 text-sm mt-1'>
                              {errors.email}
                            </motion.p>
                          )}
                        </div>
                      </div>

                      <div>
                        <label className='block mb-2 theme-text-secondary text-sm'>Phone Number</label>
                        <div className='relative'>
                          <span className='absolute left-3 top-4 text-accent text-[16px]'>
                            <FaPhone />
                          </span>
                          <input type='tel' name='phone' value={formData.phone} onChange={handleChange} className={inputClasses('phone')} placeholder='Enter your phone number' />
                          {errors.phone && (
                            <motion.p initial={{ opacity: 0 }} animate={{ opacity: 1 }} className='text-red-500 text-sm mt-1'>
                              {errors.phone}
                            </motion.p>
                          )}
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              </motion.div>

              {/* Right Column: Public Presence */}
              <motion.div className='flex flex-col gap-6 h-full' initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.6, delay: 0.1 }}>
                <motion.div className='p-6 rounded-lg bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 flex-1'>
                  <h3 className='text-xl font-semibold theme-text mb-2'>Public Presence</h3>
                  <p className='text-sm theme-text-secondary mb-4'>Shape how people discover you, review your work, and understand your public profile at a glance.</p>
                  <div className='space-y-4'>
                    <div>
                      <label className='block mb-2 theme-text-secondary text-sm'>Professional Headline</label>
                      <div className='relative'>
                        <span className='absolute left-3 top-4 text-accent text-[16px]'>
                          <FaBriefcase />
                        </span>
                        <input type='text' name='headline' value={formData.headline} onChange={handleChange} className={inputClasses('headline')} placeholder='Frontend developer focused on fast, polished client work' />
                        {errors.headline && (
                          <motion.p initial={{ opacity: 0 }} animate={{ opacity: 1 }} className='text-red-500 text-sm mt-1'>
                            {errors.headline}
                          </motion.p>
                        )}
                      </div>
                    </div>

                    <div>
                      <label className='block mb-2 theme-text-secondary text-sm'>Bio</label>
                      <div className='relative'>
                        <span className='absolute left-3 top-4 text-accent text-[16px]'>
                          <FaBook />
                        </span>
                        <textarea
                          name='bio'
                          value={formData.bio}
                          onChange={handleChange}
                          className={inputClasses('bio')}
                          rows='4'
                          placeholder='Briefly describe your background, strengths, and the kind of work you do best'
                        />
                        {errors.bio && (
                          <motion.p initial={{ opacity: 0 }} animate={{ opacity: 1 }} className='text-red-500 text-sm mt-1'>
                            {errors.bio}
                          </motion.p>
                        )}
                      </div>
                    </div>

                    <div>
                      <label className='block mb-2 theme-text-secondary text-sm'>Location</label>
                      <div className='relative'>
                        <span className='absolute left-3 top-4 text-accent text-[16px]'>
                          <FaMapMarkerAlt />
                        </span>
                        <input type='text' name='location' value={formData.location} onChange={handleChange} className={inputClasses('location')} placeholder='Enter your location' />
                      </div>
                    </div>
                    <div>
                      <label className='block mb-2 theme-text-secondary text-sm'>Timezone</label>
                      <div className='relative'>
                        <span className='absolute left-3 top-4 text-accent text-[16px]'>
                          <FaGlobe />
                        </span>
                        <input type='text' name='timezone' value={formData.timezone} onChange={handleChange} className={inputClasses('timezone')} placeholder='Europe/Vilnius' />
                      </div>
                    </div>
                    {[
                      { name: 'website', label: 'Portfolio', icon: <FaGlobe />, placeholder: 'Enter your portfolio URL' },
                      { name: 'github', label: 'GitHub', icon: <FaGithub />, placeholder: 'Enter your GitHub profile' },
                      { name: 'linkedin', label: 'LinkedIn', icon: <FaLinkedin />, placeholder: 'Enter your LinkedIn profile' },
                      { name: 'twitter', label: 'Twitter', icon: <FaTwitter />, placeholder: 'Enter your Twitter handle' }
                    ].map((social) => (
                      <div key={social.name}>
                        <label className='block mb-2 theme-text-secondary text-sm'>{social.label}</label>
                        <div className='relative'>
                          <span className='absolute left-3 top-4 text-accent text-[16px]'>{social.icon}</span>
                          <input type='url' name={social.name} value={formData[social.name]} onChange={handleChange} className={inputClasses(social.name)} placeholder={social.placeholder} />
                          {errors[social.name] && (
                            <motion.p initial={{ opacity: 0 }} animate={{ opacity: 1 }} className='text-red-500 text-sm mt-1'>
                              {errors[social.name]}
                            </motion.p>
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                </motion.div>
              </motion.div>
            </motion.div>

            {showFreelancerSection && (
              <motion.div
                className='p-6 rounded-lg bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 mb-8'
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.65 }}>
                <h3 className='text-xl font-semibold theme-text mb-2'>Visibility & Contact Preferences</h3>
