                              {errors[platform.name]}
                            </motion.p>
                          )}
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              </motion.div>
            )}

            <div className='space-y-3'>
              <p className='text-sm theme-text-secondary'>{hasUnsavedChanges ? 'You have profile edits ready to save or reset.' : 'No pending profile changes.'}</p>

              <div className='flex flex-col sm:flex-row gap-4'>
                <motion.button
                  type='button'
                  onClick={handleReset}
                  className='flex-1 bg-primary/20 dark:bg-light/10 text-primary dark:text-light font-medium py-3 px-6 rounded-lg
