              disabled:opacity-50 disabled:cursor-not-allowed
              flex items-center justify-center gap-2'
                  whileHover={hasUnsavedChanges && !isSubmitting ? { scale: 1.02 } : undefined}
                  whileTap={hasUnsavedChanges && !isSubmitting ? { scale: 0.98 } : undefined}
                  disabled={isSubmitting || !hasUnsavedChanges}>
                  {isSubmitting && <LoadingSpinner size='sm' className='border-t-2 border-white' />}
                  {isSubmitting ? 'Saving Changes...' : hasUnsavedChanges ? 'Save Changes' : 'No Changes to Save'}
                </motion.button>
              </div>
            </div>
          </form>
        </>
      )}
    </motion.div>
  )
}

export default ProfileSettings

import React, { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import { FaProjectDiagram, FaCheckCircle, FaClock, FaStar, FaWallet, FaBullhorn, FaEnvelopeOpenText, FaUserFriends, FaHistory } from 'react-icons/fa'
import { getUserStats, getMyConnections } from '../../services/userService'
import { getUserAnnouncements } from '../../services/announcementService'
import { getUserMessages } from '../../services/messageService'
import LoadingSpinner from '../shared/LoadingSpinner'

const ProfileStats = ({ user, profileCompleteness, onOpenSettings, onOpenProjects, onOpenMessages, onOpenFreelance, onOpenConnections }) => {
  const [statsData, setStatsData] = useState(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)
  const [recentAnnouncements, setRecentAnnouncements] = useState([])
  const [recentMessages, setRecentMessages] = useState([])

  useEffect(() => {
    const fetchStats = async () => {
      try {
        setLoading(true)

        const [stats, announcements, messages, connections] = await Promise.all([getUserStats(), getUserAnnouncements().catch(() => []), getUserMessages().catch(() => []), getMyConnections().catch(() => null)])

        const currentUserId = user?._id
        const extractId = (value) => (typeof value === 'string' ? value : value?._id)

        const announcementCount = Array.isArray(announcements) ? announcements.length : 0
        const unreadMessages = Array.isArray(messages) ? messages.filter((message) => !message.isRead && extractId(message.receiver) === currentUserId).length : 0
        const connectionsCount = connections?.summary?.connectionsCount || 0
        const incomingConnectionsCount = connections?.summary?.incomingCount || 0

        const normalizedAnnouncements = Array.isArray(announcements) ? announcements : []
        const normalizedMessages = Array.isArray(messages) ? messages : []

        setRecentAnnouncements(normalizedAnnouncements)
        setRecentMessages(normalizedMessages)

        const formattedStats = [
          {
            icon: <FaProjectDiagram />,
            label: 'Total Projects',
            value: stats.totalProjects.toString(),
            trend: stats.totalProjectsTrend >= 0 ? `+${stats.totalProjectsTrend}` : `${stats.totalProjectsTrend}`
          },
          {
            icon: <FaCheckCircle />,
            label: 'Completed',
            value: stats.completed.toString(),
            trend: stats.completedTrend >= 0 ? `+${stats.completedTrend}` : `${stats.completedTrend}`
          },
          {
            icon: <FaClock />,
            label: 'In Progress',
            value: stats.inProgress.toString(),
            trend: stats.inProgressTrend >= 0 ? `+${stats.inProgressTrend}` : `${stats.inProgressTrend}`
          },
          {
            icon: <FaStar />,
            label: 'Success Rate',
            value: `${stats.successRate}%`,
            trend: stats.successRateTrend >= 0 ? `+${stats.successRateTrend}%` : `${stats.successRateTrend}%`
          },
          {
            icon: <FaWallet />,
            label: 'Total Earnings',
            value: `Γé¼${stats.totalEarnings.toLocaleString()}`,
            trend: stats.totalEarningsTrend >= 0 ? `+Γé¼${stats.totalEarningsTrend.toLocaleString()}` : `Γé¼${stats.totalEarningsTrend.toLocaleString()}`
          },
          {
            icon: <FaBullhorn />,
            label: 'Announcements',
            value: announcementCount.toString(),
            trend: 'Live'
          },
          {
            icon: <FaEnvelopeOpenText />,
            label: 'Unread Messages',
            value: unreadMessages.toString(),
            trend: unreadMessages > 0 ? 'Needs attention' : 'All caught up'
          },
          {
            icon: <FaUserFriends />,
            label: 'Connections',
            value: connectionsCount.toString(),
            trend: incomingConnectionsCount > 0 ? `${incomingConnectionsCount} pending` : 'Network active'
          }
        ]

        setStatsData(formattedStats)
      } catch (err) {
        console.error('Failed to fetch stats:', err)
        setError(err)
      } finally {
        setLoading(false)
      }
    }

    fetchStats()
  }, [user?._id])

  if (loading) {
    return (
      <motion.div className='space-y-8' initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.5 }}>
        <motion.h2 className='text-2xl font-bold theme-text'>Dashboard Overview</motion.h2>
        <div className='flex justify-center py-12'>
          <LoadingSpinner />
        </div>
      </motion.div>
    )
  }

  if (error) {
    return (
      <motion.div className='space-y-8' initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.5 }}>
        <motion.h2 className='text-2xl font-bold theme-text'>Dashboard Overview</motion.h2>
        <div className='p-6 bg-red-500/10 border border-red-500 rounded-lg'>
          <p className='theme-text text-red-500'>Failed to load statistics. Please try again later.</p>
        </div>
      </motion.div>
    )
  }

  const stats = statsData || []
  const completion = profileCompleteness?.percentage ?? 0
  const missingRequired = profileCompleteness?.missingRequired ?? []
  const missingOptional = profileCompleteness?.missingOptional ?? []
  const requiredPreview = missingRequired.slice(0, 3)
  const optionalPreview = missingOptional.slice(0, 3)

  const quickActions = [
    onOpenProjects
      ? {
          key: 'projects',
          label: 'View Projects',
          description: 'Open your projects tab',
          onClick: onOpenProjects
        }
      : null,
    onOpenConnections
      ? {
          key: 'connections',
          label: 'Open Connections',
          description: 'Review your network and pending requests',
          onClick: onOpenConnections
        }
      : null,
    onOpenMessages
      ? {
          key: 'messages',
          label: 'Open Messages',
          description: 'Review recent conversations',
          onClick: onOpenMessages
        }
      : null,
    onOpenFreelance
      ? {
          key: 'freelance',
          label: 'Manage Freelance',
          description: 'Update your freelancer presence',
          onClick: onOpenFreelance
        }
      : null,
    onOpenSettings
      ? {
          key: 'settings',
          label: 'Complete Profile',
          description: 'Update missing profile details',
          onClick: onOpenSettings
        }
      : null
  ].filter(Boolean)

  const formatRelativeDate = (value) => {
    if (!value) return 'Recently'
    const date = new Date(value)
    if (Number.isNaN(date.getTime())) return 'Recently'

    const now = new Date()
    const diffMs = now - date
    const diffHours = Math.floor(diffMs / (1000 * 60 * 60))

    if (diffHours < 1) return 'Just now'
    if (diffHours < 24) return `${diffHours}h ago`

    const diffDays = Math.floor(diffHours / 24)
    if (diffDays < 7) return `${diffDays}d ago`

    return date.toLocaleDateString()
  }

  const recentAnnouncementItems = recentAnnouncements
    .slice()
    .sort((a, b) => new Date(b.createdAt || b.updatedAt || 0) - new Date(a.createdAt || a.updatedAt || 0))
    .slice(0, 2)
    .map((announcement) => ({
      key: `announcement-${announcement._id}`,
      title: announcement.title || 'Announcement updated',
      meta: announcement.isActive ? 'Announcement is live' : 'Announcement is paused',
      time: formatRelativeDate(announcement.updatedAt || announcement.createdAt)
    }))

  const recentMessageItems = recentMessages
    .slice()
    .sort((a, b) => new Date(b.createdAt || 0) - new Date(a.createdAt || 0))
    .slice(0, 2)
    .map((message) => {
      const isIncoming = (typeof message.receiver === 'string' ? message.receiver : message.receiver?._id) === user?._id
      const otherUser = isIncoming ? message.sender : message.receiver
      const otherName = otherUser?.userType === 'admin' ? 'Administrator' : `${otherUser?.firstName || ''} ${otherUser?.lastName || ''}`.trim() || 'User'

      return {
        key: `message-${message._id}`,
        title: message.subject || `Message ${isIncoming ? 'from' : 'to'} ${otherName}`,
        meta: message.isRead ? 'Read message' : 'Unread message',
        time: formatRelativeDate(message.createdAt)
      }
    })

  const profileReminderItem =
    missingRequired.length > 0 || missingOptional.length > 0
      ? [
          {
            key: 'profile-reminder',
            title: missingRequired.length > 0 ? 'Profile needs attention' : 'Profile can be improved',
            meta: missingRequired.length > 0 ? `${missingRequired.length} required field(s) still missing` : `${missingOptional.length} optional field(s) can still be added`,
            time: 'Action needed'
          }
        ]
      : [
          {
            key: 'profile-complete',
            title: 'Profile completion is on track',
            meta: 'All required profile fields are complete',
            time: `${completion}% complete`
          }
        ]

  const activityItems = [...profileReminderItem, ...recentAnnouncementItems, ...recentMessageItems].slice(0, 5)

  return (
    <motion.div className='space-y-8' initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.5 }}>
      <motion.h2 className='text-2xl font-bold theme-text' initial={{ opacity: 0, y: -20 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.5 }}>
        Dashboard Overview
      </motion.h2>

      <div className='grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-6'>
        {stats.map((stat, index) => (
          <motion.div
            key={index}
            className='p-6 rounded-lg bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 hover:shadow-lg hover:scale-[1.02] transition-all duration-300'
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.3, delay: index * 0.08 }}
            whileHover={{
              scale: 1.02,
              transition: { duration: 0.2 }
            }}>
            <div className='flex flex-col gap-4'>
              <motion.div className='text-2xl text-accent' initial={{ scale: 0 }} animate={{ scale: 1 }} transition={{ duration: 0.3, delay: index * 0.08 + 0.2 }}>
                {stat.icon}
              </motion.div>
              <div>
                <motion.div className='text-2xl font-bold theme-text' initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.3, delay: index * 0.08 + 0.3 }}>
                  {stat.value}
                </motion.div>
                <div className='theme-text-secondary text-sm'>{stat.label}</div>
                <motion.div className='text-green-500 text-sm mt-2' initial={{ opacity: 0, x: -10 }} animate={{ opacity: 1, x: 0 }} transition={{ duration: 0.3, delay: index * 0.08 + 0.4 }}>
                  {stat.trend}
                </motion.div>
              </div>
            </div>
          </motion.div>
        ))}
      </div>

      <motion.div
        className='p-6 rounded-lg bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700'
        initial={{ opacity: 0, y: 16 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.35, delay: 0.08 }}>
        <div className='flex items-center gap-3 mb-4'>
          <FaHistory className='text-accent' />
          <div>
            <p className='text-xs uppercase tracking-wide theme-text-secondary'>Recent Activity</p>
            <h3 className='text-lg font-semibold theme-text mt-1'>Latest account updates</h3>
          </div>
        </div>

        <div className='space-y-3'>
          {activityItems.map((item) => (
            <div key={item.key} className='flex items-start justify-between gap-4 p-4 rounded-lg bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 hover:shadow-md transition-all duration-300'>
              <div>
                <p className='font-medium theme-text'>{item.title}</p>
                <p className='text-sm theme-text-secondary mt-1'>{item.meta}</p>
              </div>
              <span className='text-xs theme-text-secondary whitespace-nowrap'>{item.time}</span>
            </div>
          ))}
        </div>
      </motion.div>

      {quickActions.length > 0 && (
        <motion.div
          className='p-6 rounded-lg bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700'
          initial={{ opacity: 0, y: 16 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.35, delay: 0.05 }}>
          <div className='flex items-center justify-between gap-4 mb-4'>
            <div>
              <p className='text-xs uppercase tracking-wide theme-text-secondary'>Quick Actions</p>
              <h3 className='text-lg font-semibold theme-text mt-1'>Jump to common tasks</h3>
            </div>
          </div>

          <div className='grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-3'>
            {quickActions.map((action) => (
              <button
                key={action.key}
                type='button'
                onClick={action.onClick}
                className='text-left p-4 rounded-lg border border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-900 hover:border-accent/50 hover:bg-gray-100 dark:hover:bg-gray-800 hover:shadow-md hover:scale-[1.02] transition-all duration-300'>
                <p className='font-medium theme-text'>{action.label}</p>
                <p className='text-sm theme-text-secondary mt-1'>{action.description}</p>
              </button>
            ))}
          </div>
        </motion.div>
      )}

      <motion.div className='p-6 rounded-lg bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700' initial={{ opacity: 0, y: 16 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.35 }}>
        <div className='flex flex-col md:flex-row md:items-center md:justify-between gap-4'>
          <div>
            <p className='text-sm theme-text-secondary'>Profile Completion</p>
            <p className='text-2xl font-bold theme-text mt-1'>{completion}%</p>
          </div>

          <div className='text-sm theme-text-secondary'>
            <p>Missing required: {missingRequired.length}</p>
            <p>Missing optional: {missingOptional.length}</p>
          </div>
        </div>

        <div className='mt-4 w-full h-3 rounded-full bg-primary/20 dark:bg-light/10 overflow-hidden'>
          <motion.div className='h-full bg-gradient-to-r from-accent to-accent/70' initial={{ width: 0 }} animate={{ width: `${completion}%` }} transition={{ duration: 0.6 }} />
        </div>

        <div className='mt-4 grid grid-cols-1 md:grid-cols-2 gap-3'>
          <div className='p-3 rounded-lg bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700'>
            <p className='text-xs uppercase tracking-wide theme-text-secondary mb-2'>Missing required</p>
            {requiredPreview.length > 0 ? (
              <ul className='space-y-1'>
                {requiredPreview.map((item) => (
                  <li key={item.key} className='text-sm text-red-500'>
                    ΓÇó {item.label}
                  </li>
                ))}
              </ul>
            ) : (
              <p className='text-sm text-green-500'>All required fields are complete.</p>
            )}
          </div>

          <div className='p-3 rounded-lg bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700'>
            <p className='text-xs uppercase tracking-wide theme-text-secondary mb-2'>Recommended next</p>
            {optionalPreview.length > 0 ? (
              <ul className='space-y-1'>
                {optionalPreview.map((item) => (
                  <li key={item.key} className='text-sm theme-text-secondary'>
                    ΓÇó {item.label}
                  </li>
                ))}
              </ul>
            ) : (
              <p className='text-sm text-green-500'>Optional fields are complete.</p>
            )}
          </div>
        </div>

        {(missingRequired.length > 0 || missingOptional.length > 0) && (
          <div className='mt-4'>
            <button type='button' onClick={() => onOpenSettings?.()} className='px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent/90 hover:shadow-lg transition-all duration-300'>
              Complete Profile in Settings
            </button>
          </div>
        )}
      </motion.div>
    </motion.div>
  )
}

export default ProfileStats

import { useState, useEffect } from 'react'
import { useNavigate, useLocation } from 'react-router-dom'
import { motion } from 'framer-motion'
import { FaEye, FaBriefcase, FaLightbulb, FaHeart, FaStar } from 'react-icons/fa'
import ProjectModal from '../../modal/ProjectModal'
import AssignModal from '../../modal/AssignModal'
import RatingModal from '../../modal/RatingModal'
import { useAuth } from '../../context/AuthContext' // Import useAuth hook
import { getUserProjects, getInterestedProjects, removeFromInterested, removeAssignee, publishProject, deleteProject } from '../../services/projectService'
import { getFavoriteProjects, addToFavorites, removeFromFavorites } from '../../services/userService'
import { getFreelancerRatings } from '../../services/ratingService'
import { getProjectStatusBadgeClass, formatProjectStatusLabel, getProjectPriorityBadgeClass, formatProjectPriorityLabel } from '../../utils/projectStatusUI'
import LoadingSpinner from '../shared/LoadingSpinner'

const ProjectsList = () => {
  const navigate = useNavigate()
  const location = useLocation()
  const { currentUser } = useAuth() // Get the current user
  const [projectType, setProjectType] = useState('all')
  const [isModalOpen, setIsModalOpen] = useState(false)
  const [modalMode, setModalMode] = useState('create')
  const [projects, setProjects] = useState([]) // State for projects
  const [loading, setLoading] = useState(true) // Loading state
  const [error, setError] = useState(null) // Error state
  const [selectedProject, setSelectedProject] = useState(null)
  const [isAssignModalOpen, setIsAssignModalOpen] = useState(false)
  const [favorites, setFavorites] = useState([])
  const [statusFilter, setStatusFilter] = useState('all')
  const [isRatingModalOpen, setIsRatingModalOpen] = useState(false)
  const [selectedFreelancerForRating, setSelectedFreelancerForRating] = useState(null)
  const [selectedProjectForRating, setSelectedProjectForRating] = useState(null)
  const [freelancerRatingsCache, setFreelancerRatingsCache] = useState({})
  const [ratingUserType, setRatingUserType] = useState('freelancer')

  const isLockedStatus = (status) => ['under_review', 'completed', 'archived', 'cancelled', 'cancelled_by_admin', 'deleted_by_owner'].includes(status)

  const openModal = () => {
    setModalMode('create')
    setSelectedProject(null)
    setIsModalOpen(true)
  }
  const closeModal = () => {
    setIsModalOpen(false)
    setModalMode('create')
    setSelectedProject(null)
  }

  // Fetch projects when component mounts
  useEffect(() => {
    fetchProjects()
  }, [])

  // Fetch favorites when component mounts
  useEffect(() => {
    if (!currentUser) return // Skip if no user

    const loadFavorites = async () => {
      try {
        const favProjects = await getFavoriteProjects()
        // Extract just the IDs
        const favoriteIds = favProjects.map((fav) => fav._id)
        setFavorites(favoriteIds)
      } catch (error) {
        console.error('Error loading favorites:', error)
      }
    }

    loadFavorites()
  }, [currentUser])

  // Reload projects and favorites when user navigates back to this page
  useEffect(() => {
    if (currentUser) {
      fetchProjects()
    }
  }, [location.pathname, currentUser])

  // Load freelancer ratings to check which projects have been rated
  useEffect(() => {
    if (!currentUser?._id) return

    const loadMyRatings = async () => {
      try {
        await getFreelancerRatings(currentUser._id)
      } catch (error) {
        console.error('Error loading ratings:', error)
      }
    }

    loadMyRatings()
  }, [currentUser])

  // Load freelancer ratings for all freelancers in projects
  useEffect(() => {
    if (!projects || projects.length === 0) return

    const loadFreelancerRatings = async () => {
      const freelancerIds = new Set()

      // Collect all unique freelancer IDs from projects
      projects.forEach((project) => {
        if (project.assignee?._id) {
          freelancerIds.add(project.assignee._id)
        }
      })

      // Fetch ratings for each freelancer
      const newCache = { ...freelancerRatingsCache }

      for (const freelancerId of freelancerIds) {
        if (newCache[freelancerId]) {
          continue
        }

        try {
          const ratingsData = await getFreelancerRatings(freelancerId)
          newCache[freelancerId] = ratingsData
        } catch (error) {
          console.error(`Error loading ratings for freelancer ${freelancerId}:`, error)
        }
      }

      setFreelancerRatingsCache(newCache)
    }

    loadFreelancerRatings()
  }, [projects])

  // Function to fetch projects and favorites
  const fetchProjects = async () => {
    try {
      setLoading(true)

      // Fetch created, interested, and favorite projects
      const [createdProjects, interestedProjects] = await Promise.all([getUserProjects(), getInterestedProjects()])

      // Combine and remove duplicates
      const allProjects = [...createdProjects]

      // Add interested projects
      interestedProjects.forEach((interestedProject) => {
        if (!allProjects.some((p) => p._id === interestedProject._id)) {
          allProjects.push(interestedProject)
        }
      })

      // Also fetch and merge favorite projects
      if (currentUser) {
        try {
          const favProjects = await getFavoriteProjects()
          const favoriteIds = favProjects.map((fav) => fav._id)
          setFavorites(favoriteIds)

          // Add favorite project objects to allProjects if not already there
          favProjects.forEach((favProject) => {
            if (!allProjects.some((p) => p._id === favProject._id)) {
              allProjects.push(favProject)
            }
          })
        } catch (error) {
          console.error('Error loading favorites:', error)
        }
      }

      const sortedProjects = [...allProjects].sort((a, b) => new Date(b.createdAt || 0).getTime() - new Date(a.createdAt || 0).getTime())

      setProjects(sortedProjects)
      setError(null)
    } catch (err) {
      console.error('Error fetching projects:', err)
      setError('Failed to load projects. Please try again later.')
    } finally {
      setLoading(false)
    }
  }

  const isCreator = (project) => project.user._id === currentUser._id || project.user === currentUser._id

  const isFavorited = (projectId) => {
    return favorites.includes(projectId)
  }

  const isInterested = (project) =>
    project.interestedUsers?.some((u) => {
      const userId = u.userId._id ? u.userId._id : u.userId
      return userId === currentUser._id
    })

  const isAssignee = (project) => (project.assignee?._id ? project.assignee._id === currentUser._id : project.assignee === currentUser._id)

  // Determine project type based on relationship to current user
  const getProjectType = (project) => {
    if (isCreator(project)) return 'created'
    if (isAssignee(project)) return 'freelance' // assigned work
    if (isInterested(project)) return 'interested' // contacted but not assigned
    return 'other'
  }

  // Apply tab filter first
  let filteredProjects =
    projectType === 'all'
      ? projects.filter((project) => project.status !== 'archived')
      : projectType === 'favorites'
        ? projects.filter((project) => isFavorited(project._id) && project.status !== 'archived' && project.status !== 'completed')
        : projectType === 'archived'
          ? projects.filter((project) => project.status === 'archived')
          : projectType === 'completed'
            ? projects.filter((project) => project.status === 'completed')
            : projects.filter((project) => getProjectType(project) === projectType && project.status !== 'archived' && project.status !== 'completed')

  // Apply status filter if "All Projects" tab is selected
  if (projectType === 'all' && statusFilter !== 'all') {
    filteredProjects = filteredProjects.filter((project) => project.status === statusFilter)
  }

  return (
    <motion.div className='space-y-8' initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.5 }}>
      <motion.div className='flex justify-between items-center' initial={{ opacity: 0, y: -20 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.5 }}>
        <h2 className='text-2xl font-bold theme-text'>My Projects</h2>
        <motion.button onClick={openModal} className='px-4 py-2 bg-accent text-white rounded-lg hover:bg-accent/90 transition-all duration-300' whileHover={{ scale: 1.05 }} whileTap={{ scale: 0.95 }}>
          New Project
        </motion.button>
      </motion.div>

      {/* Project Modal - Pass fetchProjects function to refresh after creation */}
      <ProjectModal isOpen={isModalOpen} onClose={closeModal} onProjectCreated={fetchProjects} mode={modalMode} initialData={selectedProject} onProjectUpdated={fetchProjects} />

      {/* Project Type Filter */}
      <motion.div className='flex gap-4 flex-wrap' initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.5, delay: 0.2 }}>
        <motion.button
          onClick={() => setProjectType('all')}
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          className={`flex items-center gap-2 px-4 py-2 rounded-lg transition-all duration-300
            ${projectType === 'all' ? 'bg-accent text-white' : 'bg-accent/10 text-accent'}`}>
          All Projects
        </motion.button>
        <motion.button
          onClick={() => setProjectType('freelance')}
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          className={`flex items-center gap-2 px-4 py-2 rounded-lg transition-all duration-300
            ${projectType === 'freelance' ? 'bg-accent text-white' : 'bg-accent/10 text-accent'}`}>
          <FaBriefcase />
          Freelance Work
        </motion.button>
        <motion.button
          onClick={() => setProjectType('created')}
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          className={`flex items-center gap-2 px-4 py-2 rounded-lg transition-all duration-300
            ${projectType === 'created' ? 'bg-accent text-white' : 'bg-accent/10 text-accent'}`}>
          <FaLightbulb />
          My Listings
        </motion.button>
        <motion.button
          onClick={() => setProjectType('interested')}
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          className={`flex items-center gap-2 px-4 py-2 rounded-lg transition-all duration-300
            ${projectType === 'interested' ? 'bg-accent text-white' : 'bg-accent/10 text-accent'}`}>
          <FaEye />
          Interested
        </motion.button>
        <motion.button
          onClick={() => setProjectType('favorites')}
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          className={`flex items-center gap-2 px-4 py-2 rounded-lg transition-all duration-300
    ${projectType === 'favorites' ? 'bg-accent text-white' : 'bg-accent/10 text-accent'}`}>
          <FaHeart />
          Favorites
        </motion.button>
        <motion.button
          onClick={() => setProjectType('completed')}
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          className={`flex items-center gap-2 px-4 py-2 rounded-lg transition-all duration-300
    ${projectType === 'completed' ? 'bg-accent text-white' : 'bg-accent/10 text-accent'}`}>
          <FaCheck />
          Completed
        </motion.button>
        <motion.button
          onClick={() => setProjectType('archived')}
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          className={`flex items-center gap-2 px-4 py-2 rounded-lg transition-all duration-300
    ${projectType === 'archived' ? 'bg-accent text-white' : 'bg-accent/10 text-accent'}`}>
          <FaArchive />
          Archived
        </motion.button>
      </motion.div>

      {/* Status Filter - Only show when "All Projects" tab is selected */}
      {projectType === 'all' && (
        <motion.select
          value={statusFilter}
          onChange={(e) => setStatusFilter(e.target.value)}
          className='px-4 py-2 rounded-lg border-2 border-accent/20 theme-bg theme-text transition-all duration-300 hover:border-accent/50 focus:border-accent focus:outline-none'
          initial={{ opacity: 0, x: -20 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.3 }}>
          <option value='all'>All Statuses</option>
          <option value='active'>Active</option>
          <option value='in_progress'>In Progress</option>
          <option value='under_review'>Under Review</option>
          <option value='completed'>Completed</option>
          <option value='paused'>Paused</option>
          <option value='cancelled'>Cancelled</option>
          <option value='cancelled_by_admin'>Canceled by Admin</option>
        </motion.select>
      )}

      {/* Loading State */}
      {loading && (
        <div className='flex justify-center py-10'>
          <LoadingSpinner />
        </div>
      )}

      {/* Error State */}
      {error && (
        <div className='bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded relative' role='alert'>
          <strong className='font-bold'>Error!</strong>
          <span className='block sm:inline'> {error}</span>
        </div>
      )}

      {/* Empty State */}
      {!loading && !error && filteredProjects.length === 0 && (
        <div className='text-center py-10'>
          <FaLightbulb className='mx-auto text-4xl text-primary/40 dark:text-light/40 mb-4' />
          <h3 className='text-xl font-medium theme-text mb-2'>No projects found</h3>
          <p className='theme-text-secondary'>
            {projectType === 'all'
              ? "You don't have any projects yet. Create a new project to get started!"
              : projectType === 'created'
                ? "You haven't created any projects yet. Click 'New Project' to create one!"
                : projectType === 'freelance'
                  ? "You aren't working on any freelance projects yet. Browse available projects to get started!"
                  : projectType === 'interested'
                    ? "You haven't shown interest in any projects yet. Browse projects to get started!"
                    : projectType === 'favorites'
                      ? 'No favorite projects yet. Click the heart icon on any project to add it to your favorites!'
                      : projectType === 'completed'
                        ? 'No completed projects yet. Once projects are finished and reviewed, they will appear here!'
                        : projectType === 'archived'
                          ? 'No archived projects yet. Completed projects can be archived to keep your workspace clean!'
                          : 'No projects found in this category.'}
          </p>
        </div>
      )}

      {/* Project List */}
      {!loading && !error && filteredProjects.length > 0 && (
        <motion.div className='grid gap-6' initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.5, delay: 0.3 }}>
          {filteredProjects.map((project, index) => (
            <motion.div
              key={project._id}
              className='p-6 rounded-lg bg-gradient-to-br dark:from-light/10 dark:to-light/5 from-primary/10 to-primary/5 hover:shadow-lg transition-all duration-300 group backdrop-blur-sm'
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.3, delay: index * 0.1 }}
              whileHover={{ scale: 1.01 }}>
              {/* Project content */}
              <div className='flex justify-between items-start'>
                <div className='flex-1'>
                  <div className='flex items-center gap-3 mb-2'>
                    <motion.div initial={{ scale: 0 }} animate={{ scale: 1 }} transition={{ duration: 0.3, delay: index * 0.1 + 0.2 }}>
                      {getProjectType(project) === 'freelance' ? <FaBriefcase className='text-accent text-xl' /> : <FaLightbulb className='text-accent text-xl' />}
                    </motion.div>
                    <div className='flex items-center justify-between w-full'>
                      <h3 className='text-xl font-semibold theme-text'>{project.title}</h3>
                      <motion.button
                        onClick={async (e) => {
                          e.stopPropagation()
                          try {
                            if (isFavorited(project._id)) {
                              await removeFromFavorites(project._id)
                              setFavorites(favorites.filter((id) => id !== project._id))
                            } else {
                              await addToFavorites(project._id)
                              setFavorites([...favorites, project._id])
                            }
                          } catch (error) {
                            console.error('Error toggling favorite:', error)
                          }
                        }}
                        className='ml-2'
                        whileHover={{ scale: 1.2 }}
                        whileTap={{ scale: 0.9 }}>
                        <FaHeart className={`text-2xl ${isFavorited(project._id) ? 'text-red-500' : 'text-primary/40 dark:text-light/40'}`} />
                      </motion.button>
                    </div>
                  </div>
                  <p className='theme-text-secondary text-sm mb-3'>{project.description}</p>
                  <div className='flex items-center gap-4'>
                    <div className='flex items-center gap-2'>
                      <span className={`px-3 py-1 rounded-full text-sm font-medium ${getProjectStatusBadgeClass(project.status)}`}>{formatProjectStatusLabel(project.status)}</span>
                      <span className={`px-3 py-1 rounded-full text-sm font-medium ${getProjectPriorityBadgeClass(project.priority)}`}>{formatProjectPriorityLabel(project.priority)} Priority</span>
                    </div>

                    {project.assignee && (isCreator(project) || isAssignee(project)) && (
                      <div className='text-sm text-accent'>
                        Assigned: {project.assignee.firstName} {project.assignee.lastName}
                      </div>
                    )}
                    <div className='theme-text-secondary text-sm mt-[2px]'>Due: {new Date(project.deadline).toLocaleDateString()}</div>
                  </div>
                </div>
                <div className='text-right'>
                  <div className='theme-text font-bold'>Γé¼{project.budget}</div>
                  <motion.button
                    onClick={() => navigate(`/project/${project._id}`)}
                    className='mt-2 flex items-center gap-2 px-4 py-2 rounded-lg bg-accent/10 text-accent hover:bg-accent hover:text-white transition-all duration-300'
                    whileHover={{ scale: 1.05 }}
                    whileTap={{ scale: 0.95 }}>
                    <FaEye />
                    <span>View</span>
                  </motion.button>
                  {(() => {
                    const isCompleted = project.status === 'completed'
                    const hasAssignee = project.assignee
                    const isCreatorCheck = isCreator(project)
                    const freelancerId = hasAssignee ? project.assignee._id : null
                    const freelancerRatings = freelancerId ? freelancerRatingsCache[freelancerId] : null
                    const hasRated = freelancerRatings?.ratings?.some((r) => r.projectId === project._id && r.ratedBy._id === currentUser._id)

                    // Button will show if project is completed, has assignee, user is creator, and hasn't rated yet
                    return isCompleted && hasAssignee && isCreatorCheck && !hasRated
                  })() && (
                    <motion.button
                      onClick={() => {
                        setSelectedFreelancerForRating(project.assignee)
                        setSelectedProjectForRating(project)
                        setIsRatingModalOpen(true)
                      }}
                      className='mt-2 flex items-center gap-2 px-4 py-2 rounded-lg bg-yellow-50 dark:bg-yellow-900/20 text-yellow-600 dark:text-yellow-300 hover:bg-yellow-100 dark:hover:bg-yellow-900/40 transition-all duration-300'
                      whileHover={{ scale: 1.05 }}
                      whileTap={{ scale: 0.95 }}>
                      <FaStar />
                      <span>Rate Freelancer</span>
                    </motion.button>
                  )}

                  {/* Rate Client button - for freelancers on assigned projects */}
                  {project.status === 'completed' &&
                    project.assignee &&
                    isAssignee(project) &&
                    !freelancerRatingsCache[project.user._id]?.ratings?.some((r) => r.projectId === project._id && r.ratedBy._id === currentUser._id) && (
                      <motion.button
                        onClick={() => {
                          setSelectedFreelancerForRating({ _id: project.user._id, firstName: project.user.firstName, lastName: project.user.lastName, profilePicture: project.user.profilePicture })
                          setSelectedProjectForRating(project)
                          setIsRatingModalOpen(true)
                          setRatingUserType('client')
                        }}
                        className='mt-2 flex items-center gap-2 px-4 py-2 rounded-lg bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-300 hover:bg-blue-100 dark:hover:bg-blue-900/40 transition-all duration-300'
                        whileHover={{ scale: 1.05 }}
                        whileTap={{ scale: 0.95 }}>
                        <FaStar />
                        <span>Rate Client</span>
                      </motion.button>
                    )}
                  {(() => {
                    // Check if user is interested in this project (but not the creator or assigned)
                    const isCreator = project.user._id === currentUser._id || project.user === currentUser._id
                    const isInterested = project.interestedUsers?.some((u) => {
                      const userId = u.userId._id ? u.userId._id : u.userId
                      return userId === currentUser._id
                    })

                    // Only show Remove button if: NOT creator AND interested AND NOT assigned
                    return !isCreator && isInterested && !isAssignee(project)
                  })() && (
                    <motion.button
                      onClick={async () => {
                        try {
                          await removeFromInterested(project._id)
                          await fetchProjects()
                        } catch (err) {
                          console.error('Error removing from interested:', err)
                        }
                      }}
                      className='mt-2 flex items-center gap-2 px-4 py-2 rounded-lg bg-red-500/10 text-red-500 hover:bg-red-500 hover:text-white transition-all duration-300'
                      whileHover={{ scale: 1.05 }}
                      whileTap={{ scale: 0.95 }}>
                      <FaHeart />
                      <span>Remove</span>
                    </motion.button>
                  )}
                </div>
              </div>

              {/* Progress Bar */}
              <div className='mt-6'>
                <div className='flex justify-between mb-2'>
                  <span className='theme-text-secondary text-sm'>Progress</span>
                  <span className='theme-text-secondary text-sm'>{project.progress || 0}%</span>
                </div>
                <div className='w-full bg-gray-200 rounded-full h-2.5 dark:bg-gray-700'>
                  <motion.div className='bg-accent h-2.5 rounded-full' initial={{ width: 0 }} animate={{ width: `${project.progress || 0}%` }} transition={{ duration: 0.5, delay: index * 0.1 + 0.4 }} />
                </div>
              </div>

              {/* Assign/Remove Actions (Creator only) */}
              {isCreator(project) && project.interestedUsers && project.interestedUsers.length > 0 && (
                <div className='mt-4 pt-4 border-t dark:border-light/10 border-primary/10'>
                  {!project.assignee ? (
                    <motion.button
                      onClick={() => {
                        setSelectedProject(project)
                        setIsAssignModalOpen(true)
                      }}
                      className='w-full py-2 bg-accent/10 text-accent hover:bg-accent hover:text-white rounded transition-all'
                      whileHover={{ scale: 1.02 }}
                      whileTap={{ scale: 0.98 }}>
                      Assign Project
                    </motion.button>
                  ) : (
                    <motion.button
                      onClick={async () => {
                        if (isLockedStatus(project.status)) return
                        try {
                          await removeAssignee(project._id)
                          await fetchProjects()
                        } catch (err) {
                          console.error('Error removing assignee:', err)
                        }
                      }}
                      disabled={isLockedStatus(project.status)}
                      className={`w-full py-2 rounded transition-all ${
                        isLockedStatus(project.status) ? 'bg-gray-400 text-white cursor-not-allowed opacity-60' : 'bg-red-500/10 text-red-500 hover:bg-red-500 hover:text-white'
                      }`}
                      whileHover={isLockedStatus(project.status) ? {} : { scale: 1.02 }}
                      whileTap={isLockedStatus(project.status) ? {} : { scale: 0.98 }}>
                      {isLockedStatus(project.status) ? 'Assigning Locked' : 'Remove Assignment'}
                    </motion.button>
                  )}
                </div>
              )}

              {/* Edit and Publish buttons for creator projects */}
              {isCreator(project) && (
                <div className='mt-2 space-y-2'>
                  <motion.button
                    onClick={() => {
                      if (isLockedStatus(project.status)) return
                      setSelectedProject(project)
                      setModalMode('edit')
                      setIsModalOpen(true)
                    }}
                    disabled={isLockedStatus(project.status)}
                    className={`w-full py-2 rounded transition-all ${
                      isLockedStatus(project.status) ? 'bg-gray-400 text-white cursor-not-allowed opacity-60' : 'bg-blue-500/10 text-blue-500 hover:bg-blue-500 hover:text-white'
                    }`}
                    whileHover={isLockedStatus(project.status) ? {} : { scale: 1.02 }}
                    whileTap={isLockedStatus(project.status) ? {} : { scale: 0.98 }}>
                    {isLockedStatus(project.status) ? 'Edit Locked' : 'Edit Project'}
                  </motion.button>

                  <motion.button
                    onClick={async () => {
                      const confirmed = window.confirm('Remove this project from your profile? Admin will still keep it in audit logs.')
                      if (!confirmed) return

                      try {
                        await deleteProject(project._id)
                        await fetchProjects()
                      } catch (err) {
                        console.error('Error deleting project from profile:', err)
                      }
                    }}
                    className='w-full py-2 bg-red-500/10 text-red-500 hover:bg-red-500 hover:text-white rounded transition-all'
                    whileHover={{ scale: 1.02 }}
                    whileTap={{ scale: 0.98 }}>
                    Delete from My Profile
                  </motion.button>

                  {project.status === 'draft' && (
                    <motion.button
                      onClick={async () => {
                        if (!currentUser?.isEmailVerified) {
                          window.alert('Verify your email before publishing projects.')
                          return
                        }

                        try {
                          await publishProject(project._id)
                          await fetchProjects()
                        } catch (err) {
                          console.error('Error publishing project:', err)
                        }
                      }}
                      disabled={!currentUser?.isEmailVerified}
                      className='w-full py-2 bg-green-500/10 text-green-500 hover:bg-green-500 hover:text-white rounded transition-all disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:bg-green-500/10 disabled:hover:text-green-500'
                      whileHover={currentUser?.isEmailVerified ? { scale: 1.02 } : {}}
                      whileTap={currentUser?.isEmailVerified ? { scale: 0.98 } : {}}>
                      {currentUser?.isEmailVerified ? 'Publish Project' : 'Verify Email to Publish'}
                    </motion.button>
                  )}
                </div>
              )}

              {/* Interested Users Badge */}
              {project.interestedUsers && project.interestedUsers.length > 0 && (
                <div className='mt-4 pt-4 border-t dark:border-light/10 border-primary/10'>
                  <p className='text-sm theme-text-secondary mb-2'>
                    {(() => {
                      const count = project.interestedUsers.length
                      const names = project.interestedUsers
                        .slice(0, 2)
                        .map((u) => u.userId?.firstName || 'User')
                        .join(', ')
                      const others = count - 2

                      if (count === 1) {
                        return `Interested: ${names}`
                      } else if (count <= 2) {
                        return `Interested: ${names}`
                      } else {
                        return `Interested: ${names} and ${others} ${others === 1 ? 'other' : 'others'}`
                      }
                    })()}
                  </p>
                </div>
              )}
            </motion.div>
          ))}
        </motion.div>
      )}

      {/* Assign Modal */}
      <AssignModal
        isOpen={isAssignModalOpen}
        onClose={() => {
          setIsAssignModalOpen(false)
          setSelectedProject(null)
        }}
        project={selectedProject}
        onAssignSuccess={fetchProjects}
      />
      {/* Rating Modal for manual rating of completed projects */}
      <RatingModal
        isOpen={isRatingModalOpen}
        onClose={() => {
          setIsRatingModalOpen(false)
          setSelectedFreelancerForRating(null)
          setSelectedProjectForRating(null)
          setRatingUserType('freelancer')
        }}
        freelancer={selectedFreelancerForRating}
        projectId={selectedProjectForRating?._id}
        ratedUserType={ratingUserType}
        onRatingSubmitted={() => {
          // Reload the freelancer's ratings after submission
          const loadFreelancerRatings = async () => {
            try {
              if (!selectedFreelancerForRating?._id) return
              const ratingsData = await getFreelancerRatings(selectedFreelancerForRating._id)
              setFreelancerRatingsCache((prev) => ({
                ...prev,
                [selectedFreelancerForRating._id]: ratingsData
              }))
            } catch (error) {
              console.error('Error loading freelancer ratings:', error)
            }
          }
          loadFreelancerRatings()
          fetchProjects()
        }}
      />
    </motion.div>
  )
}

export default ProjectsList

import { motion } from 'framer-motion'
import { FaStar, FaUser } from 'react-icons/fa'
import LoadingSpinner from '../shared/LoadingSpinner'

const RatingsSection = ({ ratings, stats, loading }) => {
  if (loading) {
    return (
      <div className='flex justify-center py-8'>
        <LoadingSpinner />
      </div>
    )
  }

  if (!ratings || !stats) {
    return (
      <div className='text-center py-8'>
        <p className='theme-text-secondary'>No ratings yet. Complete projects with clients to receive ratings.</p>
      </div>
    )
  }

  // Render star rating
  const renderStars = (score) => {
    return (
      <div className='flex gap-1'>
        {[1, 2, 3, 4, 5].map((star) => (
          <FaStar key={star} size={16} className={star <= score ? 'text-accent' : 'theme-text-muted'} />
        ))}
      </div>
    )
  }

  return (
    <div className='space-y-6'>
      {/* Rating Summary */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className='bg-gradient-to-br dark:from-light/5 dark:via-light/[0.02] from-primary/5 via-primary/[0.02] to-transparent p-6 rounded-lg border border-primary/10 dark:border-light/10 backdrop-blur-sm'>
        <div className='flex items-center justify-between mb-6'>
          <h2 className='text-2xl font-bold theme-text'>Your Ratings</h2>
          <div className='text-right'>
            <div className='flex items-center gap-2 mb-2'>
              <span className='text-4xl font-bold text-accent'>{stats.averageRating.toFixed(1)}</span>
              {renderStars(Math.round(stats.averageRating))}
            </div>
            <p className='text-sm theme-text-secondary'>
              Based on {stats.totalRatings} rating{stats.totalRatings !== 1 ? 's' : ''}
            </p>
          </div>
        </div>

        {/* Rating Distribution */}
        <div className='space-y-3'>
          {[5, 4, 3, 2, 1].map((stars) => (
            <div key={stars} className='flex items-center gap-4'>
              <div className='flex items-center gap-1 w-20'>
                <span className='text-sm font-medium theme-text'>{stars}</span>
                <FaStar size={12} className='text-accent' />
              </div>
              <div className='flex-1 h-2 theme-input rounded-full overflow-hidden'>
                <motion.div
                  initial={{ width: 0 }}
                  animate={{ width: `${(stats.distribution[stars] / stats.totalRatings) * 100}%` }}
                  transition={{ duration: 0.5, delay: (5 - stars) * 0.1 }}
                  className='h-full bg-accent'
                />
              </div>
              <span className='text-sm theme-text-secondary w-8'>{stats.distribution[stars]}</span>
            </div>
          ))}
        </div>
      </motion.div>

      {/* Individual Ratings */}
      {ratings.ratings && ratings.ratings.length > 0 ? (
        <div className='space-y-4'>
          <h3 className='text-lg font-bold theme-text'>Client Reviews</h3>
          {ratings.ratings.map((rating, index) => (
            <motion.div
              key={rating._id}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: index * 0.1 }}
              className='bg-gradient-to-br dark:from-light/5 dark:via-light/[0.02] from-primary/5 via-primary/[0.02] to-transparent p-4 rounded-lg border border-primary/10 dark:border-light/10 backdrop-blur-sm'>
              {/* Reviewer Info */}
              <div className='flex items-center gap-3 mb-3'>
                <div className='w-10 h-10 rounded-full bg-accent/10 flex items-center justify-center'>
                  {rating.ratedBy.profilePicture ? <img src={rating.ratedBy.profilePicture} alt={rating.ratedBy.firstName} className='w-10 h-10 rounded-full object-cover' /> : <FaUser className='text-accent' />}
                </div>
                <div className='flex-1'>
                  <p className='font-semibold theme-text'>
                    {rating.ratedBy.firstName} {rating.ratedBy.lastName}
                  </p>
                  <p className='text-xs theme-text-secondary'>{new Date(rating.createdAt).toLocaleDateString()}</p>
                </div>
                <div>{renderStars(rating.score)}</div>
              </div>

              {/* Review Feedback */}
              {rating.feedback && <p className='text-sm theme-text-secondary'>{rating.feedback}</p>}
            </motion.div>
          ))}
        </div>
      ) : (
        <p className='text-sm theme-text-secondary text-center py-4'>No reviews yet</p>
      )}
    </div>
  )
}

export default RatingsSection

import { useState } from 'react'
import { motion } from 'framer-motion'
import { FaLock, FaEye, FaEyeSlash } from 'react-icons/fa'
import { toast } from 'react-toastify'
import LoadingSpinner from '../shared/LoadingSpinner'
import { changeUserPassword } from '../../services/userService'

const SecuritySettings = () => {
  const [passwordData, setPasswordData] = useState({
    currentPassword: '',
    newPassword: '',
    confirmPassword: ''
  })

  const [showPasswords, setShowPasswords] = useState({
    currentPassword: false,
    newPassword: false,
    confirmPassword: false
  })

  const [errors, setErrors] = useState({})
  const [passwordStrength, setPasswordStrength] = useState(0)
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [passwordUpdated, setPasswordUpdated] = useState(false)
  const [sessionExpired, setSessionExpired] = useState(false)

  const validateForm = () => {
    const newErrors = {}

    // Current password validation
    if (!passwordData.currentPassword.trim()) {
      newErrors.currentPassword = 'Current password is required'
    }

    // New password validation
    if (!passwordData.newPassword) {
      newErrors.newPassword = 'New password is required'
    } else {
      // Password strength rules
      if (passwordData.newPassword.length < 8) {
        newErrors.newPassword = 'Password must be at least 8 characters'
      }
      if (!/[A-Z]/.test(passwordData.newPassword)) {
        newErrors.newPassword = 'Password must contain at least one uppercase letter'
      }
      if (!/[a-z]/.test(passwordData.newPassword)) {
        newErrors.newPassword = 'Password must contain at least one lowercase letter'
      }
      if (!/[0-9]/.test(passwordData.newPassword)) {
        newErrors.newPassword = 'Password must contain at least one number'
      }
      if (!/[!@#$%^&*]/.test(passwordData.newPassword)) {
        newErrors.newPassword = 'Password must contain at least one special character'
      }
    }

    if (passwordData.currentPassword && passwordData.newPassword && passwordData.currentPassword === passwordData.newPassword) {
      newErrors.newPassword = 'New password must be different from current password'
    }

    // Confirm password validation
    if (!passwordData.confirmPassword) {
      newErrors.confirmPassword = 'Please confirm your new password'
    } else if (passwordData.newPassword !== passwordData.confirmPassword) {
      newErrors.confirmPassword = 'Passwords do not match'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  // Each criteria adds 20% to strength
  const calculatePasswordStrength = (password) => {
    let strength = 0
    if (password.length >= 8) strength += 20
    if (/[A-Z]/.test(password)) strength += 20
    if (/[a-z]/.test(password)) strength += 20
    if (/[0-9]/.test(password)) strength += 20
    if (/[!@#$%^&*]/.test(password)) strength += 20
    return strength
  }

  // Random password generator
  const generateStrongPassword = () => {
    const lowercase = 'abcdefghijklmnopqrstuvwxyz'
    const uppercase = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    const numbers = '0123456789'
    const symbols = '!@#$%^&*'

    if (passwordUpdated) {
      setPasswordUpdated(false)
    }

    if (sessionExpired) {
      setSessionExpired(false)
    }

    const getRandomChar = (str) => str.charAt(Math.floor(Math.random() * str.length))

    let password = [getRandomChar(lowercase), getRandomChar(uppercase), getRandomChar(numbers), getRandomChar(symbols)]

    const allChars = lowercase + uppercase + numbers + symbols
    for (let i = password.length; i < 12; i++) {
      password.push(getRandomChar(allChars))
    }

    password = password.sort(() => Math.random() - 0.5)

    const newPassword = password.join('')

    setPasswordData((prev) => ({
      ...prev,
      newPassword,
      confirmPassword: ''
    }))

    setErrors((prev) => {
      const nextErrors = { ...prev }
      delete nextErrors.newPassword
      delete nextErrors.confirmPassword

      if (passwordData.currentPassword !== newPassword) {
        delete nextErrors.newPassword
      }

      return nextErrors
    })

    setPasswordStrength(calculatePasswordStrength(newPassword))
  }

  // Password requirements
  const PasswordRequirements = ({ password }) => {
    const requirements = [
      { label: 'At least 8 characters', test: (pwd) => pwd.length >= 8 },
      { label: 'Contains uppercase letter', test: (pwd) => /[A-Z]/.test(pwd) },
      { label: 'Contains lowercase letter', test: (pwd) => /[a-z]/.test(pwd) },
      { label: 'Contains number', test: (pwd) => /[0-9]/.test(pwd) },
      { label: 'Contains special character', test: (pwd) => /[!@#$%^&*]/.test(pwd) }
    ]

    return (
      <div className='mt-2 space-y-2'>
        {requirements.map((req, index) => (
          <motion.div key={index} className='flex items-center space-x-2' initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: index * 0.1 }}>
            <span className={`text-sm ${req.test(password) ? 'text-green-500' : 'text-red-500'}`}>{req.test(password) ? 'Γ£ô' : '├ù'}</span>
            <span className='text-sm theme-text-secondary'>{req.label}</span>
          </motion.div>
        ))}
      </div>
    )
  }

  // Updates strength when password changes
  const handleChange = (e) => {
    const { name, value } = e.target

    if (passwordUpdated) {
      setPasswordUpdated(false)
    }

    if (sessionExpired) {
      setSessionExpired(false)
    }

    setPasswordData((prev) => {
      const nextPasswordData = {
        ...prev,
        [name]: value
      }

      setErrors((prevErrors) => {
        const nextErrors = {
          ...prevErrors
        }

        delete nextErrors[name]

        if (name === 'currentPassword' || name === 'newPassword') {
          if (nextPasswordData.currentPassword !== nextPasswordData.newPassword) {
            delete nextErrors.newPassword
          }
        }

        if (name === 'newPassword' || name === 'confirmPassword') {
          if (nextPasswordData.newPassword === nextPasswordData.confirmPassword) {
            delete nextErrors.confirmPassword
          }
        }

        return nextErrors
      })

      return nextPasswordData
    })

    if (name === 'newPassword') {
      setPasswordStrength(calculatePasswordStrength(value))
    }
  }

  const handleSubmit = async (e) => {
    e.preventDefault()

    if (!validateForm()) return

    try {
      setIsSubmitting(true)
      setSessionExpired(false)

      const response = await changeUserPassword({
        currentPassword: passwordData.currentPassword,
        newPassword: passwordData.newPassword
      })

      toast.success(response.message || 'Password updated successfully.')

      setPasswordData({
        currentPassword: '',
        newPassword: '',
        confirmPassword: ''
      })
      setErrors({})
      setPasswordStrength(0)
      setPasswordUpdated(true)
      setShowPasswords({
        currentPassword: false,
        newPassword: false,
        confirmPassword: false
      })
    } catch (error) {
      const status = error.response?.status
      const message = error.response?.data?.message || 'Failed to update password.'
      setPasswordUpdated(false)

      if (status === 401) {
        setSessionExpired(true)
        toast.error('Your session has expired. Please sign in again before updating your password.')
        return
      }

      toast.error(message)

      if (message.toLowerCase().includes('current password')) {
        setErrors((prev) => ({
          ...prev,
          currentPassword: message
        }))
      }

      if (message.toLowerCase().includes('new password')) {
        setErrors((prev) => ({
          ...prev,
          newPassword: message
        }))
      }
    } finally {
      setIsSubmitting(false)
    }
  }

  const getInputClasses = (fieldName) => `
  w-full pl-10 p-3 rounded-lg
  theme-input theme-text
  transition-all duration-300
  border ${errors[fieldName] ? 'border-red-500' : 'dark:border-light/10 border-primary/10'}
  dark:placeholder:text-light/40 placeholder:text-primary/40
  dark:focus:placeholder:text-light/60 focus:placeholder:text-primary/60
  focus:outline-none focus:ring-2 focus:ring-accent/50
`

  const hasUppercase = /[A-Z]/.test(passwordData.newPassword)
  const hasLowercase = /[a-z]/.test(passwordData.newPassword)
  const hasNumber = /[0-9]/.test(passwordData.newPassword)
  const hasSpecialCharacter = /[!@#$%^&*]/.test(passwordData.newPassword)
  const hasMinimumLength = passwordData.newPassword.length >= 8
  const isNewPasswordDifferent = Boolean(passwordData.currentPassword && passwordData.newPassword && passwordData.currentPassword !== passwordData.newPassword)
  const doPasswordsMatch = Boolean(passwordData.newPassword && passwordData.confirmPassword && passwordData.newPassword === passwordData.confirmPassword)
  const hasStartedPasswordFlow = Boolean(passwordData.currentPassword || passwordData.newPassword || passwordData.confirmPassword)
  const canSubmitPassword = Boolean(
    passwordData.currentPassword &&
    passwordData.newPassword &&
    passwordData.confirmPassword &&
    hasMinimumLength &&
    hasUppercase &&
    hasLowercase &&
    hasNumber &&
    hasSpecialCharacter &&
    isNewPasswordDifferent &&
    doPasswordsMatch
  )

  return (
    <motion.div className='space-y-8' initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.5 }}>
      <motion.div
        className='p-6 rounded-lg bg-gradient-to-br dark:from-light/10 dark:to-light/5 from-primary/10 to-primary/5 border theme-border'
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6 }}>
        <h3 className='text-xl font-semibold theme-text mb-2'>Change Password</h3>
        <p className='text-sm theme-text-secondary mb-2'>Use a strong password you do not reuse elsewhere to keep your account protected.</p>
        <p className='text-xs theme-text-muted mb-4'>Your current password is required before a new one can be saved.</p>

        <form onSubmit={handleSubmit} className='space-y-6'>
          <div>
            <p className='text-xs uppercase tracking-wide theme-text-muted mb-4'>Verification</p>
            <div>
              <label className='block mb-2 theme-text-secondary text-sm'>Current Password</label>
              <div className='relative'>
                <span className='absolute left-3 top-4 text-accent text-[16px]'>
                  <FaLock />
                </span>
                <input
                  type={showPasswords.currentPassword ? 'text' : 'password'}
                  name='currentPassword'
                  value={passwordData.currentPassword}
                  onChange={handleChange}
                  className={getInputClasses('currentPassword')}
                  placeholder='Enter current password'
                />
                <button
                  type='button'
                  onClick={() =>
                    setShowPasswords((prev) => ({
                      ...prev,
                      currentPassword: !prev.currentPassword
                    }))
                  }
                  className='absolute right-3 top-4 text-accent text-[16px]'>
                  {showPasswords.currentPassword ? <FaEyeSlash /> : <FaEye />}
                </button>
                {errors.currentPassword && (
                  <motion.p initial={{ opacity: 0 }} animate={{ opacity: 1 }} className='text-red-500 text-sm mt-1'>
                    {errors.currentPassword}
                  </motion.p>
                )}
              </div>
            </div>

            <div className='pt-2 border-t dark:border-light/10 border-primary/10'>
              <p className='text-xs uppercase tracking-wide theme-text-muted mb-4'>New Password</p>

              <div className='space-y-6'>
                <div>
                  <label className='block mb-2 theme-text-secondary text-sm'>New Password</label>
                  <div className='relative'>
                    <span className='absolute left-3 top-4 text-accent text-[16px]'>
                      <FaLock />
                    </span>
                    <input
                      type={showPasswords.newPassword ? 'text' : 'password'}
                      name='newPassword'
                      value={passwordData.newPassword}
                      onChange={handleChange}
                      className={getInputClasses('newPassword')}
                      placeholder='Enter new password'
                    />
                    <button
                      type='button'
                      onClick={() =>
                        setShowPasswords((prev) => ({
                          ...prev,
                          newPassword: !prev.newPassword
                        }))
                      }
                      className='absolute right-3 top-4 text-accent text-[16px]'>
                      {showPasswords.newPassword ? <FaEyeSlash /> : <FaEye />}
                    </button>
                    {errors.newPassword && (
                      <motion.p initial={{ opacity: 0 }} animate={{ opacity: 1 }} className='text-red-500 text-sm mt-1'>
                        {errors.newPassword}
                      </motion.p>
                    )}
                  </div>

                  <div className='mt-3 flex items-center justify-between gap-3 flex-wrap'>
                    <p className='text-xs theme-text-muted'>Need help? Generate a strong password and store it in your password manager.</p>
                    <button
                      type='button'
                      onClick={generateStrongPassword}
                      className='inline-flex items-center gap-2 px-3 py-1.5 rounded-lg border dark:border-light/10 border-primary/10 theme-text hover:text-accent hover:border-accent/40 transition-colors'>
                      Generate Strong Password
                    </button>
                  </div>

                  {passwordData.newPassword ? (
                    <>
                      <div className='mt-3'>
                        <div className='h-2 w-full rounded-full overflow-hidden bg-primary/10 dark:bg-light/10'>
                          <motion.div
                            className={`h-full ${passwordStrength <= 40 ? 'bg-red-500' : passwordStrength <= 80 ? 'bg-yellow-500' : 'bg-green-500'}`}
                            initial={{ width: 0 }}
                            animate={{ width: `${passwordStrength}%` }}
                            transition={{ duration: 0.3 }}
                          />
                        </div>
                        <p className='text-sm mt-1 theme-text-secondary'>Password Strength: {passwordStrength <= 40 ? 'Weak' : passwordStrength <= 80 ? 'Medium' : 'Strong'}</p>
                      </div>

                      <PasswordRequirements password={passwordData.newPassword} />
                    </>
                  ) : (
                    <p className='text-sm theme-text-secondary mt-3'>Start typing a new password to see strength feedback and requirements.</p>
                  )}
                </div>

                <div>
                  <label className='block mb-2 theme-text-secondary text-sm'>Confirm Password</label>
                  <div className='relative'>
                    <span className='absolute left-3 top-4 text-accent text-[16px]'>
                      <FaLock />
                    </span>
                    <input
                      type={showPasswords.confirmPassword ? 'text' : 'password'}
                      name='confirmPassword'
                      value={passwordData.confirmPassword}
                      onChange={handleChange}
                      className={getInputClasses('confirmPassword')}
                      placeholder='Confirm new password'
                    />
                    <button
                      type='button'
                      onClick={() =>
                        setShowPasswords((prev) => ({
                          ...prev,
                          confirmPassword: !prev.confirmPassword
                        }))
                      }
                      className='absolute right-3 top-4 text-accent text-[16px]'>
                      {showPasswords.confirmPassword ? <FaEyeSlash /> : <FaEye />}
                    </button>
                    {errors.confirmPassword && (
                      <motion.p initial={{ opacity: 0 }} animate={{ opacity: 1 }} className='text-red-500 text-sm mt-1'>
                        {errors.confirmPassword}
                      </motion.p>
                    )}
                  </div>
                </div>
              </div>
            </div>
          </div>

          <div className='space-y-3'>
            {sessionExpired && (
              <motion.p initial={{ opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0 }} className='text-sm text-amber-600 dark:text-amber-400'>
                Your session expired before the password update completed. Sign in again, then retry this form.
              </motion.p>
            )}
            {passwordUpdated && (
              <motion.p initial={{ opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0 }} className='text-sm text-green-600 dark:text-green-400'>
                Password updated successfully. Use your new password the next time you sign in.
              </motion.p>
            )}
            <p className='text-sm theme-text-secondary'>
              {!hasStartedPasswordFlow
                ? 'Enter your current and new password to begin.'
                : isSubmitting
                  ? 'Updating your password now.'
                  : !canSubmitPassword
                    ? 'Complete all requirements and make sure both new password fields match before submitting.'
                    : 'Your password details are ready to submit.'}
            </p>

            <motion.button
              type='submit'
              className='w-full bg-accent text-white font-medium py-3 px-6 rounded-lg
              hover:bg-accent/90 transition-colors duration-300
              focus:outline-none focus:ring-2 focus:ring-accent/50
              disabled:opacity-50 disabled:cursor-not-allowed
              flex items-center justify-center gap-2'
              whileHover={canSubmitPassword && !isSubmitting ? { scale: 1.02 } : undefined}
              whileTap={canSubmitPassword && !isSubmitting ? { scale: 0.98 } : undefined}
              disabled={!canSubmitPassword || isSubmitting}>
              {isSubmitting && <LoadingSpinner size='sm' className='border-t-2 border-white' />}
              {isSubmitting ? 'Updating Password...' : 'Update Password'}
            </motion.button>
          </div>
        </form>
      </motion.div>
    </motion.div>
  )
}

export default SecuritySettings

import { useState } from 'react'
import { motion } from 'framer-motion'
import { FaClock } from 'react-icons/fa'
import { assignUserToProject } from '../../services/projectService'
import { sendMessage } from '../../services/messageService'
import LoadingSpinner from '../shared/LoadingSpinner'

const SenderBlock = ({ sender, messages, index, projectId, isProjectCreator, onAssignSuccess }) => {
  const [assigning, setAssigning] = useState(false)
  const [replyText, setReplyText] = useState('') // Store reply message
  const [sending, setSending] = useState(false) // Track sending state

  // Get current user to check if this is sender's own messages
  const currentUser = JSON.parse(localStorage.getItem('user') || '{}')
  const isOwnMessages = sender?._id === currentUser._id

  // Format time nicely
  const formatTime = (dateString) => {
    const date = new Date(dateString)
    const now = new Date()
    const diffInHours = Math.floor((now - date) / (1000 * 60 * 60))

    if (diffInHours < 1) return 'Just now'
    if (diffInHours < 24) return `${diffInHours}h ago`
    if (diffInHours < 48) return 'Yesterday'
    return date.toLocaleDateString()
  }

  const handleAssign = async () => {
    try {
      setAssigning(true)
      await assignUserToProject(projectId, sender._id)
      onAssignSuccess?.() // Refresh parent
    } catch (error) {
      console.error('Failed to assign user:', error)
    } finally {
      setAssigning(false)
    }
  }

  const handleReply = async () => {
    // Don't send if empty
    if (!replyText.trim()) return

    try {
      setSending(true)

      // Send the reply (we'll create this service function next)
      await sendMessage(projectId, sender._id, replyText)

      // Clear input and refresh
      setReplyText('')
      onAssignSuccess?.() // Refresh messages
    } catch (error) {
      console.error('Failed to send reply:', error)
    } finally {
      setSending(false)
    }
  }

  return (
    <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3, delay: index * 0.1 }} className='mb-6'>
      {/* Sender Header */}
      <div className='flex items-center gap-3 mb-4 pb-3 border-b dark:border-light/10 border-primary/10'>
        <img src={sender?.profilePicture || `https://i.pravatar.cc/150?u=${sender?._id}`} alt={sender?.firstName} className='w-12 h-12 rounded-full object-cover border-2 border-accent/20' />
        <div>
          <h3 className='font-semibold theme-text'>
            {sender?.firstName} {sender?.lastName}
          </h3>
          <p className='text-sm theme-text-secondary'>{sender?.email}</p>
        </div>
        {isProjectCreator && !isOwnMessages && (
          <motion.button
            onClick={handleAssign}
            disabled={assigning}
            className='px-3 py-1 bg-accent/10 text-accent hover:bg-accent hover:text-white rounded text-sm transition-all flex items-center justify-center gap-1'
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}>
            {assigning && <LoadingSpinner size='sm' className='border-t-2 border-accent' />}
            {assigning ? 'Assigning...' : 'Assign'}
          </motion.button>
        )}
      </div>

      {/* Messages from this sender */}
      <div className='space-y-3 pl-16'>
        {messages.map((message, msgIndex) => (
          <motion.div
            key={message._id}
            initial={{ opacity: 0, x: -10 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.2, delay: msgIndex * 0.05 }}
            className='bg-gradient-to-br dark:from-light/5 dark:via-light/[0.02] from-primary/5 via-primary/[0.02] to-transparent p-4 rounded-lg border border-primary/10 dark:border-light/10 backdrop-blur-sm'>
            {/* Message content */}
            <p className='theme-text leading-relaxed mb-2'>{message.content}</p>

            {/* Timestamp */}
            <div className='flex items-center gap-1 text-xs theme-text-secondary'>
              <FaClock />
              <span>{formatTime(message.createdAt)}</span>
            </div>
          </motion.div>
        ))}
      </div>

      {/* Reply Input (only for project creator) */}
      {isProjectCreator && !isOwnMessages && (
        <div className='mt-4 pl-16'>
          <div className='flex gap-2'>
            <input
              type='text'
              value={replyText}
              onChange={(e) => setReplyText(e.target.value)}
              placeholder='Type your reply...'
              className='flex-1 px-4 py-2 rounded-lg border border-primary/50 dark:border-light/10 theme-bg theme-text focus:outline-none focus:border-accent focus:ring-2 focus:ring-accent/20'
              onKeyPress={(e) => {
                // Send on Enter key
                if (e.key === 'Enter' && !e.shiftKey) {
                  e.preventDefault()
                  handleReply()
                }
              }}
            />
            <motion.button
              onClick={handleReply}
              disabled={!replyText.trim() || sending}
              className='px-6 py-2 bg-accent text-white rounded-lg hover:bg-accent/90 disabled:opacity-50 disabled:cursor-not-allowed transition-all flex items-center justify-center gap-2'
              whileHover={{ scale: 1.02 }}
              whileTap={{ scale: 0.98 }}>
              {sending && <LoadingSpinner size='sm' className='border-t-2 border-white' />}
              {sending ? 'Sending...' : 'Reply'}
            </motion.button>
          </div>
        </div>
      )}
    </motion.div>
  )
}

export default SenderBlock

import { motion } from 'framer-motion'
import GroupedMessagesList from '../Profile/GroupedMessageList'
import { getProjectById } from '../../services/projectService'
import { getProjectMessages } from '../../services/messageService'

const MessagesTab = ({ project, currentUser, messages, messagesLoading, negotiationTimeline, id }) => {
  // Only show if current user is project creator
  if (!project?.user?._id || currentUser?._id !== project.user._id) {
    return null
  }

  const handleRefresh = async () => {
    try {
      const updatedProject = await getProjectById(id)
      const updatedMessages = await getProjectMessages(id)
      // Note: Caller should handle state updates
      return { updatedProject, updatedMessages }
    } catch (error) {
      console.error('Error refreshing data:', error)
    }
  }

  return (
    <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3 }}>
      <GroupedMessagesList messages={messages} loading={messagesLoading} projectId={id} isProjectCreator={true} systemEvents={negotiationTimeline} onRefresh={handleRefresh} />
    </motion.div>
  )
}

export default MessagesTab

import { motion } from 'framer-motion'
import { useNavigate } from 'react-router-dom'
import { archiveProject } from '../../services/projectService'
import ProjectCompletionButton from '../shared/ProjectCompletionButton'
import RescheduleModal from '../../modal/RescheduleModal'

const ProjectActions = ({
  project,
  currentUser,
  isOwner,
  isAssignee,
  hasApplied,
  isFavorited,
  favoriteLoading,
  handleToggleFavorite,
  setIsEditModalOpen,
  setIsContactModalOpen,
  setIsSubmitModalOpen,
  setIsReviewModalOpen,
  isRescheduleModalOpen,
  setIsRescheduleModalOpen,
  loadProject
}) => {
  const navigate = useNavigate()

  const isLockedStatus = (status) => ['under_review', 'completed', 'archived', 'cancelled', 'cancelled_by_admin', 'deleted_by_owner'].includes(status)

  const handleArchiveProject = async () => {
    try {
      await archiveProject(project._id)
      loadProject()
    } catch (error) {
      console.error('Error archiving project:', error)
      alert('Failed to archive project')
    }
  }

  return (
    <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3 }} className='theme-card p-6 rounded-lg space-y-3'>
      {/* Edit Project Button - for owner only */}
      {isOwner && !['completed', 'archived', 'deleted_by_owner'].includes(project.status) && (
        <button
          onClick={() => {
            if (isLockedStatus(project.status)) return
            setIsEditModalOpen(true)
          }}
          disabled={isLockedStatus(project.status)}
          className={`w-full py-3 rounded-lg transition-all duration-300 ${
            isLockedStatus(project.status) ? 'bg-gray-400 text-white cursor-not-allowed opacity-60' : 'bg-blue-500/10 text-blue-500 hover:bg-blue-500 hover:text-white hover:shadow-lg'
          }`}>
          {isLockedStatus(project.status) ? 'Edit Locked' : 'Edit Project'}
        </button>
      )}

      {/* Apply / Express Interest CTA */}
      {!['completed', 'archived', 'deleted_by_owner'].includes(project.status) && (
        <>
          {currentUser && currentUser._id !== project.user?._id ? (
            <button
              onClick={() => setIsContactModalOpen(true)}
              className={`w-full py-3 rounded-lg transition-all duration-300 ${hasApplied ? 'bg-accent/10 text-accent hover:bg-accent hover:text-white hover:shadow-lg' : 'bg-accent text-white hover:bg-accent/90 hover:shadow-lg'}`}>
              {hasApplied ? 'Send Follow-up Message' : 'Apply for Project'}
            </button>
          ) : !currentUser ? (
            <button onClick={() => navigate('/login')} className='w-full py-3 bg-accent text-white rounded-lg hover:bg-accent/90 hover:shadow-lg transition-all duration-300'>
              Login to Apply
            </button>
          ) : (
            <button disabled className='w-full py-3 bg-gray-400 text-white rounded-lg cursor-not-allowed opacity-50'>
              Your Project
            </button>
          )}
        </>
      )}

      {/* Submit Project Button - for assignee in progress */}
      {isAssignee && project.status === 'in_progress' && (
        <button onClick={() => setIsSubmitModalOpen(true)} className='w-full py-3 bg-accent text-white rounded-lg hover:bg-accent/90 hover:shadow-lg transition-all duration-300'>
          Submit Project
        </button>
      )}

      {/* Pending Review Badge - for assignee under review */}
      {isAssignee && project.status === 'under_review' && (
        <button disabled className='w-full py-3 bg-gray-400 text-white rounded-lg cursor-not-allowed opacity-50'>
          Pending Review
        </button>
      )}

      {/* Pending Project Badge - for owner in progress */}
      {isOwner && project.status === 'in_progress' && (
        <button disabled className='w-full py-3 bg-gray-400 text-white rounded-lg cursor-not-allowed opacity-50'>
          Pending Project
        </button>
      )}

      {/* Review Submission Button - for owner under review */}
      {isOwner && project.status === 'under_review' && (
        <button onClick={() => setIsReviewModalOpen(true)} className='w-full py-3 bg-purple-500/10 text-purple-600 rounded-lg hover:bg-purple-500 hover:text-white hover:shadow-lg transition-all duration-300'>
          Review Submission
        </button>
      )}

      {/* Mark Complete Button - for owner or assignee under review/in progress */}
      {(isOwner || isAssignee) && ['in_progress', 'under_review'].includes(project.status) && <ProjectCompletionButton project={project} onComplete={loadProject} variant='button' size='md' />}

      {/* Reschedule Project Button - for owner */}
      {isOwner && !['completed', 'archived', 'cancelled', 'deleted_by_owner'].includes(project.status) && (
        <button onClick={() => setIsRescheduleModalOpen(true)} className='w-full py-3 bg-blue-500/10 text-blue-500 hover:bg-blue-500 hover:text-white rounded-lg hover:shadow-lg transition-all duration-300'>
          Reschedule Project
        </button>
      )}

      {/* Reschedule Modal */}
      <RescheduleModal isOpen={isRescheduleModalOpen} project={project} onClose={() => setIsRescheduleModalOpen(false)} onReschedule={loadProject} />

      {/* Archive Project Button - for owner when completed */}
      {isOwner && project.status === 'completed' && (
        <button onClick={handleArchiveProject} className='w-full py-3 bg-accent text-white rounded-lg hover:bg-accent/90 hover:shadow-lg transition-all duration-300'>
          Archive Project
        </button>
      )}

      {/* Favorite Button */}
      <button
        onClick={() => {
          if (!currentUser) {
            alert('Please login to favorite projects')
            return
          }
          handleToggleFavorite()
        }}
        disabled={favoriteLoading}
        className={`w-full py-3 border-2 rounded-lg transition-all duration-300 ${isFavorited ? 'bg-accent text-white border-accent hover:bg-accent/90 hover:shadow-lg' : 'border-accent text-accent hover:bg-accent/10 hover:shadow-lg'}`}>
        {favoriteLoading ? 'Loading...' : isFavorited ? 'Unfavorite' : 'Save to Favorites'}
      </button>
    </motion.div>
  )
}

export default ProjectActions

import { motion } from 'framer-motion'
import { FaCheck } from 'react-icons/fa'

const RateNegotiationCard = ({ project, currentUser, rateAmount, setRateAmount, rateType, setRateType, rateLoading, rateError, handleProposeRate, handleCounterRate, handleAcceptRate }) => {
  const isOwner = currentUser?._id === project?.user?._id
  const isAssignee = currentUser?._id === project?.assignee?._id
  const currentOffer = project?.rateNegotiation?.currentOffer
  const isRateProposedByMe = currentOffer?.proposedBy?.toString() === currentUser?._id
  const negotiationHistory = project?.rateNegotiation?.history || []

  // Helper Functions
  const getOfferLabel = (userId) => {
    if (!userId) return 'User'
    if (project?.user?._id && userId.toString() === project.user._id.toString()) return 'Client'
    if (project?.assignee?._id && userId.toString() === project.assignee._id.toString()) return 'Freelancer'
    return 'User'
  }

  const formatOfferType = (type) => (type === 'fixed' ? 'fixed' : '/hr')

  // Only show if user is owner or assignee with an active project
  if (!(isOwner || isAssignee) || !project.assignee || ['completed', 'archived', 'cancelled', 'cancelled_by_admin', 'deleted_by_owner'].includes(project.status)) {
    return null
  }

  return (
    <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3 }} className='theme-card p-6 rounded-lg space-y-4 border border-accent/20'>
      <h3 className='text-xl font-semibold theme-text'>Rate Negotiation</h3>

      {rateError && <div className='p-2 bg-red-100 text-red-700 rounded text-sm'>{rateError}</div>}

      {/* Show Accepted Status */}
      {project.rateNegotiation?.status === 'accepted' && (
        <div className='bg-green-500/10 border border-green-500/30 p-4 rounded-lg'>
          <div className='flex items-center gap-2 text-green-600 font-semibold mb-2'>
            <FaCheck />
            <span>Rate Accepted</span>
          </div>
          <p className='text-lg font-bold theme-text'>
            Γé¼{currentOffer?.amount} {currentOffer?.type === 'hourly' ? '/hr' : 'fixed'}
          </p>
          <p className='text-xs theme-text-secondary mt-1'>Agreed on {project.rateNegotiation.agreedAt ? new Date(project.rateNegotiation.agreedAt).toLocaleDateString() : ''}</p>
        </div>
      )}

      {/* Show Current Offer when not accepted */}
      {project.rateNegotiation?.status !== 'accepted' && (
        <>
          {currentOffer ? (
            <div className='bg-accent/10 p-3 rounded-lg'>
              <p className='text-sm theme-text-secondary'>Current Offer</p>
              <p className='text-lg font-semibold theme-text'>
                Γé¼{currentOffer.amount} {currentOffer.type === 'hourly' ? '/hr' : 'fixed'}
              </p>
              <p className='text-xs theme-text-secondary mt-1'>Proposed by {getOfferLabel(currentOffer.proposedBy)}</p>
            </div>
          ) : (
            <p className='text-sm theme-text-secondary'>No offer yet</p>
          )}

          {/* Input fields for new offer */}
          <div className='grid grid-cols-2 gap-3'>
            <input type='number' value={rateAmount} onChange={(e) => setRateAmount(e.target.value)} className='p-2 rounded border dark:border-light/10 border-primary/10 theme-bg theme-text' placeholder='Amount' />
            <select value={rateType} onChange={(e) => setRateType(e.target.value)} className='p-2 rounded border dark:border-light/10 border-primary/10 theme-bg theme-text'>
              <option value='hourly'>Hourly</option>
              <option value='fixed'>Fixed</option>
            </select>
          </div>

          {/* Propose button for owner */}
          {isOwner && (
            <button
              onClick={handleProposeRate}
              disabled={rateLoading || ['in_progress', 'under_review'].includes(project.status)}
              className='w-full py-2 bg-accent text-white rounded-lg hover:bg-accent/90 hover:shadow-lg transition-all duration-300 disabled:opacity-50'>
              Propose Rate
            </button>
          )}

          {/* Counter button for assignee */}
          {isAssignee && (
            <button
              onClick={handleCounterRate}
              disabled={rateLoading || ['in_progress', 'under_review'].includes(project.status)}
              className='w-full py-2 bg-accent/10 text-accent rounded-lg hover:bg-accent hover:text-white hover:shadow-lg transition-all duration-300 disabled:opacity-50'>
              Counter Offer
            </button>
          )}

          {/* Accept button - show if offer exists and not proposed by me */}
          {currentOffer && !isRateProposedByMe && (
            <button
              onClick={handleAcceptRate}
              disabled={rateLoading || ['in_progress', 'under_review'].includes(project.status)}
              className='w-full py-2 bg-green-500/10 text-green-600 rounded-lg hover:bg-green-500 hover:text-white hover:shadow-lg transition-all duration-300 disabled:opacity-50 font-semibold'>
              Accept Offer
            </button>
          )}
        </>
      )}

      {/* Negotiation History */}
      {negotiationHistory.length > 0 && (
        <div className='pt-3 border-t dark:border-light/10 border-primary/10'>
          <p className='text-sm font-semibold theme-text mb-2'>Negotiation History</p>
          <div className='space-y-2 max-h-32 overflow-y-auto'>
            {negotiationHistory.map((offer, idx) => (
              <div key={idx} className='text-sm theme-text-secondary flex justify-between gap-2'>
                <span>
                  {getOfferLabel(offer.proposedBy)}: Γé¼{offer.amount} {formatOfferType(offer.type)}
                </span>
                <span className='text-xs'>{offer.proposedAt ? new Date(offer.proposedAt).toLocaleDateString() : ''}</span>
              </div>
            ))}
          </div>
        </div>
      )}
    </motion.div>
  )
}

