import { useEffect, useMemo, useState } from 'react'
import { Link } from 'react-router-dom'
import { FaBell, FaCheckCircle, FaUserFriends, FaEnvelope, FaCheckDouble, FaBriefcase, FaClipboardCheck, FaTasks } from 'react-icons/fa'
import { getMyNotifications, markAllNotificationsAsRead, markNotificationAsRead } from '../../services/userService'

const typeIconMap = {
  message_received: <FaEnvelope className='text-[11px]' />,
  connection_requested: <FaUserFriends className='text-[11px]' />,
  connection_accepted: <FaCheckCircle className='text-[11px]' />,
  project_assigned: <FaBriefcase className='text-[11px]' />,
  project_submitted: <FaClipboardCheck className='text-[11px]' />,
  project_reviewed: <FaTasks className='text-[11px]' />
}

const formatRelativeTime = (value) => {
  if (!value) return ''

  const timestamp = new Date(value).getTime()
  if (Number.isNaN(timestamp)) return ''

  const diffMs = Date.now() - timestamp
  const diffMinutes = Math.max(Math.floor(diffMs / (1000 * 60)), 0)

  if (diffMinutes < 1) return 'Just now'
  if (diffMinutes < 60) return `${diffMinutes}m ago`

  const diffHours = Math.floor(diffMinutes / 60)
  if (diffHours < 24) return `${diffHours}h ago`

  const diffDays = Math.floor(diffHours / 24)
  if (diffDays < 7) return `${diffDays}d ago`

  return new Date(value).toLocaleDateString()
}

const resolveNotificationLink = (notification) => {
  if (notification?.type === 'connection_accepted' && notification?.metadata?.userId) {
    return {
      pathname: `/freelancer/${notification.metadata.userId}`
    }
  }

  if (notification?.type === 'connection_requested') {
    return {
      pathname: '/profile',
      state: {
        activeTab: 'connections'
      }
    }
  }

  if (notification?.type === 'message_received') {
    return {
      pathname: '/profile',
      state: {
        activeTab: 'messages'
      }
    }
  }

  return {
    pathname: notification?.link || '/profile'
  }
}

const NotificationDropdown = ({ isOpen, onClose, unreadCount, onUnreadCountChange }) => {
  const [notifications, setNotifications] = useState([])
  const [loading, setLoading] = useState(false)
  const [markingAllRead, setMarkingAllRead] = useState(false)

  useEffect(() => {
    const loadNotifications = async () => {
      if (!isOpen) {
        return
      }

      try {
        setLoading(true)
        const data = await getMyNotifications(8)
        setNotifications(Array.isArray(data) ? data : [])
      } catch (error) {
        console.error('Failed to load notifications:', error.response?.data || error.message)
        setNotifications([])
      } finally {
        setLoading(false)
      }
    }

    loadNotifications()
  }, [isOpen])

  const visibleUnreadCount = useMemo(() => notifications.filter((item) => !item.isRead).length, [notifications])

  const handleMarkOneAsRead = async (notificationId) => {
    try {
      const updated = await markNotificationAsRead(notificationId)

      setNotifications((prev) => prev.map((item) => (item._id === notificationId ? updated : item)))

      if (typeof onUnreadCountChange === 'function') {
        onUnreadCountChange(Math.max(unreadCount - 1, 0))
      }
    } catch (error) {
      console.error('Failed to mark notification as read:', error.response?.data || error.message)
    }
  }

  const handleMarkAllAsRead = async () => {
    try {
      setMarkingAllRead(true)
      await markAllNotificationsAsRead()

      setNotifications((prev) =>
        prev.map((item) => ({
          ...item,
          isRead: true,
          readAt: item.readAt || new Date().toISOString()
        }))
      )

      if (typeof onUnreadCountChange === 'function') {
        onUnreadCountChange(0)
      }
    } catch (error) {
      console.error('Failed to mark all notifications as read:', error.response?.data || error.message)
    } finally {
      setMarkingAllRead(false)
    }
  }

  if (!isOpen) {
    return null
  }

  return (
    <div className='absolute right-0 top-14 z-[70] w-[22rem] overflow-hidden rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800 shadow-xl backdrop-blur-sm'>
      <div className='flex items-center justify-between border-b border-gray-200 dark:border-gray-700 px-4 py-3 hover:bg-gray-50 dark:hover:bg-gray-750 transition-colors'>
        <div>
          <p className='text-sm font-semibold theme-text'>Notifications</p>
          <p className='text-xs theme-text-secondary'>{visibleUnreadCount > 0 ? `${visibleUnreadCount} unread` : 'All caught up'}</p>
        </div>

        <button
          type='button'
          onClick={handleMarkAllAsRead}
          disabled={markingAllRead || visibleUnreadCount === 0}
          className='text-xs font-semibold text-accent transition-all duration-300 hover:shadow-lg hover:opacity-90 disabled:cursor-not-allowed disabled:opacity-40'>
          Mark all read
        </button>
      </div>

      <div className='max-h-[26rem] overflow-y-auto'>
        {loading ? (
          <div className='px-4 py-8 text-center text-sm text-white/65'>Loading notifications...</div>
        ) : notifications.length === 0 ? (
          <div className='flex flex-col items-center gap-3 px-4 py-10 text-center text-white/65'>
            <div className='flex h-12 w-12 items-center justify-center rounded-full border border-white/10 bg-white/5'>
              <FaBell className='text-sm' />
            </div>
            <div>
              <p className='text-sm font-medium text-white'>No notifications yet</p>
              <p className='mt-1 text-xs text-white/60'>New messages, project updates, and network activity will appear here.</p>
            </div>
          </div>
        ) : (
          notifications.map((notification) => {
            const destination = resolveNotificationLink(notification)

            return (
              <div key={notification._id} className={`border-b border-white/5 px-4 py-3 transition-colors ${notification.isRead ? 'bg-transparent' : 'bg-white/[0.04]'}`}>
                <div className='flex items-start gap-3'>
                  <div className='mt-0.5 flex h-8 w-8 flex-shrink-0 items-center justify-center rounded-full border border-white/10 bg-white/5 text-accent'>
                    {typeIconMap[notification.type] || <FaBell className='text-[11px]' />}
                  </div>

                  <div className='min-w-0 flex-1'>
                    <Link to={destination} onClick={onClose} className='block'>
                      <div className='flex items-start justify-between gap-3'>
                        <p className='text-sm font-semibold text-white'>{notification.title}</p>
                        {!notification.isRead && <span className='mt-1 h-2 w-2 flex-shrink-0 rounded-full bg-accent' />}
                      </div>

                      <p className='mt-1 text-xs leading-5 text-white/70'>{notification.body}</p>
                      <p className='mt-2 text-[11px] uppercase tracking-[0.18em] text-white/40'>{formatRelativeTime(notification.createdAt)}</p>
                    </Link>
                  </div>
                </div>

                {!notification.isRead && (
                  <button
                    type='button'
                    onClick={() => handleMarkOneAsRead(notification._id)}
                    className='mt-3 inline-flex items-center gap-2 text-[11px] font-semibold uppercase tracking-[0.16em] text-accent transition-all duration-300 hover:shadow-lg hover:opacity-90'>
                    <FaCheckDouble className='text-[10px]' />
                    Mark read
                  </button>
                )}
              </div>
            )
          })
        )}
      </div>
    </div>
  )
}

export default NotificationDropdown

import { FaChevronLeft, FaChevronRight } from 'react-icons/fa'

const PaginationControls = ({ currentPage, totalPages, onPrev, onNext, label }) => {
  if (!totalPages || totalPages < 1) return null

  return (
    <div className='mt-6 flex items-center justify-between px-4 py-3 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg hover:shadow-lg transition-all duration-300'>
      <div className='text-sm theme-text-secondary'>{label || `Page ${currentPage} of ${totalPages}`}</div>

      <div className='flex items-center space-x-2'>
        <button
          onClick={onPrev}
          disabled={currentPage === 1}
          className='px-3 py-1 rounded-md bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 theme-text hover:border-accent/50 hover:bg-gray-50 dark:hover:bg-gray-600 hover:shadow-md transition-all duration-300 disabled:opacity-50 disabled:cursor-not-allowed'>
          <FaChevronLeft className='w-4 h-4' />
        </button>

        <span className='px-3 py-1 text-sm rounded-md bg-gray-100 dark:bg-gray-700 theme-text border border-gray-200 dark:border-gray-600'>{currentPage}</span>

        <button
          onClick={onNext}
          disabled={currentPage === totalPages}
          className='px-3 py-1 rounded-md bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 theme-text hover:border-accent/50 hover:bg-gray-50 dark:hover:bg-gray-600 hover:shadow-md transition-all duration-300 disabled:opacity-50 disabled:cursor-not-allowed'>
          <FaChevronRight className='w-4 h-4' />
        </button>
      </div>
    </div>
  )
}

export default PaginationControls

import { motion } from 'framer-motion'
import { FaCheckCircle } from 'react-icons/fa'
import { useState } from 'react'
import ProjectCompletionModal from '../../modal/ProjectCompletionModal'

const ProjectCompletionButton = ({ project, onComplete, variant = 'button', size = 'md' }) => {
  const [showModal, setShowModal] = useState(false)

  const isCompleted = project?.status === 'completed'

  if (isCompleted) {
    return (
      <motion.div
        initial={{ opacity: 0, scale: 0.8 }}
        animate={{ opacity: 1, scale: 1 }}
        className='flex items-center gap-2 px-3 py-2 bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-400 rounded-lg text-sm font-medium'>
        <FaCheckCircle />
        <span>Completed</span>
      </motion.div>
    )
  }

  const sizeClasses = {
    sm: 'px-2 py-1 text-xs',
    md: 'px-4 py-2 text-sm',
    lg: 'px-6 py-3 text-base'
  }

  if (variant === 'icon') {
    return (
      <>
        <motion.button
          onClick={() => setShowModal(true)}
          whileHover={{ scale: 1.1 }}
          whileTap={{ scale: 0.95 }}
          className='p-2 rounded-lg bg-green-100 dark:bg-green-900/30 text-green-600 dark:text-green-400 hover:bg-green-200 dark:hover:bg-green-900/50 transition-colors duration-200'
          title='Mark project as complete'>
          <FaCheckCircle />
        </motion.button>
        <ProjectCompletionModal isOpen={showModal} project={project} onClose={() => setShowModal(false)} onComplete={onComplete} />
      </>
    )
  }

  return (
    <>
      <motion.button
        onClick={() => setShowModal(true)}
        whileHover={{ scale: 1.02 }}
        whileTap={{ scale: 0.98 }}
        className={`flex items-center gap-2 rounded-lg bg-green-600 hover:bg-green-700 text-white font-medium transition-colors duration-200 ${sizeClasses[size]}`}>
        <FaCheckCircle />
        <span>Mark Complete</span>
      </motion.button>
      <ProjectCompletionModal isOpen={showModal} project={project} onClose={() => setShowModal(false)} onComplete={onComplete} />
    </>
  )
}

export default ProjectCompletionButton

import { useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'

export const ProjectFilterPanel = ({ filters, onFilterChange, onClearAll, hasActiveFilters }) => {
  const [expandedSections, setExpandedSections] = useState({
    budget: true,
    status: true,
    skills: true,
    priority: false,
    sort: false
  })

  const toggleSection = (section) => {
    setExpandedSections((prev) => ({
      ...prev,
      [section]: !prev[section]
    }))
  }

  const statusOptions = ['draft', 'active', 'assigned', 'in_progress', 'under_review', 'completed', 'cancelled', 'negotiating']
  const priorityOptions = ['low', 'medium', 'high', 'urgent']
  const sortOptions = [
    { value: 'newest', label: 'Newest First' },
    { value: 'oldest', label: 'Oldest First' },
    { value: 'budget-asc', label: 'Budget: Low to High' },
    { value: 'budget-desc', label: 'Budget: High to Low' }
  ]
  const matchTypeOptions = [
    { value: 'any', label: 'Any Skill Match' },
    { value: 'all', label: 'All Skills Match' }
  ]

  const getStatusColor = (status) => {
    const colors = {
      draft: 'bg-primary/10 dark:bg-light/10 text-primary dark:text-light',
      active: 'bg-emerald-500/10 text-emerald-600 dark:text-emerald-300',
      assigned: 'bg-accent/10 text-accent',
      in_progress: 'bg-purple-500/10 text-purple-600 dark:text-purple-300',
      under_review: 'bg-orange-500/10 text-orange-600 dark:text-orange-300',
      completed: 'bg-emerald-500/10 text-emerald-600 dark:text-emerald-300',
      cancelled: 'bg-red-500/10 text-red-600 dark:text-red-300',
      negotiating: 'bg-yellow-500/10 text-yellow-600 dark:text-yellow-300'
    }
    return colors[status] || 'bg-primary/10 dark:bg-light/10 text-primary dark:text-light'
  }

  return (
    <div className='rounded-lg p-4 md:p-6 border border-primary/10 dark:border-light/10 backdrop-blur-sm'>
      {/* Header with Clear Button */}
      <div className='flex items-center justify-between mb-4'>
        <h3 className='text-lg font-semibold theme-text'>Filters</h3>
        {hasActiveFilters && (
          <button
            onClick={onClearAll}
            className='text-sm px-3 py-1 bg-primary/10 dark:bg-light/10 text-primary/60 dark:text-light/60 rounded-md hover:bg-primary/20 dark:hover:bg-light/20 hover:text-primary dark:hover:text-light transition-all duration-300 hover:shadow-lg font-medium'>
            Clear All
          </button>
        )}
      </div>

      {/* Budget Range */}
      <div className='border-b theme-border mb-4 pb-4'>
        <button onClick={() => toggleSection('budget')} className='w-full flex items-center justify-between py-2 text-left font-medium theme-text hover:theme-text-secondary transition-all duration-300'>
          <span>Budget Range</span>
          <span className={`transform transition-transform ${expandedSections.budget ? 'rotate-180' : ''}`}>Γû╝</span>
        </button>
        <AnimatePresence>
          {expandedSections.budget && (
            <motion.div initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: 'auto' }} exit={{ opacity: 0, height: 0 }} className='overflow-hidden'>
              <div className='grid grid-cols-2 gap-3 mt-3'>
                <input
                  type='number'
                  placeholder='Min Budget'
                  value={filters.minBudget}
                  onChange={(e) => onFilterChange('minBudget', e.target.value)}
                  className='px-3 py-2 border theme-border rounded-lg text-sm theme-text focus:outline-none focus:ring-2 focus:ring-accent theme-input'
                />
                <input
                  type='number'
                  placeholder='Max Budget'
                  value={filters.maxBudget}
                  onChange={(e) => onFilterChange('maxBudget', e.target.value)}
                  className='px-3 py-2 border theme-border rounded-lg text-sm theme-text focus:outline-none focus:ring-2 focus:ring-accent theme-input'
                />
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      {/* Status Filter */}
      <div className='border-b theme-border mb-4 pb-4'>
        <button onClick={() => toggleSection('status')} className='w-full flex items-center justify-between py-2 text-left font-medium theme-text hover:theme-text-secondary transition-all duration-300'>
          <span>Status</span>
          <span className={`transform transition-transform ${expandedSections.status ? 'rotate-180' : ''}`}>Γû╝</span>
        </button>
        <AnimatePresence>
          {expandedSections.status && (
            <motion.div initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: 'auto' }} exit={{ opacity: 0, height: 0 }} className='overflow-hidden'>
              <div className='grid grid-cols-2 gap-2 mt-3'>
                {statusOptions.map((status) => (
                  <label key={status} className='flex items-center cursor-pointer'>
                    <input type='checkbox' checked={filters.status.includes(status)} onChange={() => onFilterChange('addStatus', status)} className='w-4 h-4 rounded border-accent text-accent focus:ring-accent' />
                    <span className='ml-2 text-sm theme-text capitalize'>{status.replace('_', ' ')}</span>
                  </label>
                ))}
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      {/* Skills Filter */}
      <div className='border-b theme-border mb-4 pb-4'>
        <button onClick={() => toggleSection('skills')} className='w-full flex items-center justify-between py-2 text-left font-medium theme-text hover:theme-text-secondary transition-all duration-300'>
          <span>Skills</span>
          <span className={`transform transition-transform ${expandedSections.skills ? 'rotate-180' : ''}`}>Γû╝</span>
        </button>
        <AnimatePresence>
          {expandedSections.skills && (
            <motion.div initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: 'auto' }} exit={{ opacity: 0, height: 0 }} className='overflow-hidden'>
              <textarea
                placeholder='Enter skills (comma-separated)'
                value={filters.skills.join(', ')}
                onChange={(e) => {
                  const skills = e.target.value
                    .split(',')
                    .map((s) => s.trim().toLowerCase())
                    .filter((s) => s.length > 0)
                  onFilterChange('skills', skills)
                }}
                className='w-full mt-3 px-3 py-2 border theme-border rounded-lg text-sm theme-text focus:outline-none focus:ring-2 focus:ring-accent resize-none theme-input'
                rows='3'
              />
              {/* Match Type Toggle */}
              <div className='mt-3 flex gap-2'>
                {matchTypeOptions.map((option) => (
                  <button
                    key={option.value}
                    onClick={() => onFilterChange('matchType', option.value)}
                    className={`flex-1 px-2 py-2 text-xs font-medium rounded-lg transition-all duration-300 hover:shadow-lg ${filters.matchType === option.value ? 'bg-accent text-white' : 'bg-primary/10 dark:bg-light/10 theme-text-secondary hover:bg-primary/20 dark:hover:bg-light/20'}`}>
                    {option.label}
                  </button>
                ))}
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      {/* Priority Filter */}
      <div className='border-b theme-border mb-4 pb-4'>
        <button onClick={() => toggleSection('priority')} className='w-full flex items-center justify-between py-2 text-left font-medium theme-text hover:theme-text-secondary transition-all duration-300'>
          <span>Priority</span>
          <span className={`transform transition-transform ${expandedSections.priority ? 'rotate-180' : ''}`}>Γû╝</span>
        </button>
        <AnimatePresence>
          {expandedSections.priority && (
            <motion.div initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: 'auto' }} exit={{ opacity: 0, height: 0 }} className='overflow-hidden'>
              <div className='grid grid-cols-2 gap-2 mt-3'>
                {priorityOptions.map((priority) => (
                  <label key={priority} className='flex items-center cursor-pointer'>
                    <input type='checkbox' checked={filters.priority.includes(priority)} onChange={() => onFilterChange('addPriority', priority)} className='w-4 h-4 rounded border-accent text-accent focus:ring-accent' />
                    <span className='ml-2 text-sm theme-text capitalize'>{priority}</span>
                  </label>
                ))}
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      {/* Sort Options - Always Visible */}
      <div className='pt-4 border-t theme-border mt-4'>
        <div className='flex items-center justify-between mb-3'>
          <h4 className='font-medium theme-text'>Sort Results</h4>
          <div className='flex-1 ml-3 h-0.5 bg-gradient-to-r from-accent to-transparent'></div>
        </div>
        <div className='flex flex-col gap-2'>
          {sortOptions.map((option) => (
            <motion.label key={option.value} whileHover={{ x: 4 }} className='flex items-center cursor-pointer group'>
              <input
                type='radio'
                name='sort'
                value={option.value}
                checked={filters.sort === option.value}
                onChange={(e) => onFilterChange('sort', e.target.value)}
                className='w-4 h-4 border-accent text-accent focus:ring-accent'
              />
              <span className='ml-2 text-sm theme-text group-hover:text-accent transition-colors'>{option.label}</span>
              {filters.sort === option.value && <motion.div layoutId='activeSort' className='ml-auto w-2 h-2 bg-accent rounded-full' initial={{ scale: 0 }} animate={{ scale: 1 }} />}
            </motion.label>
          ))}
        </div>
      </div>
    </div>
  )
}

import { motion } from 'framer-motion'

const ProjectStatusBadge = ({ status, size = 'md' }) => {
