import { useState, useCallback, useEffect } from 'react'
import { toast } from 'react-toastify'

export const useProjectFilters = () => {
  const [filters, setFilters] = useState({
    minBudget: '',
    maxBudget: '',
    status: [],
    skills: [],
    priority: [],
    matchType: 'any',
    sort: 'newest'
  })

  const [loading, setLoading] = useState(false)
  const [error, setError] = useState(null)
  const [results, setResults] = useState({
    projects: [],
    pagination: { total: 0, page: 1, limit: 10, pages: 0 },
    appliedFilters: {}
  })

  // Load filters from localStorage on mount
  useEffect(() => {
    const savedFilters = localStorage.getItem('projectFilters')
    if (savedFilters) {
      try {
        const parsed = JSON.parse(savedFilters)
        setFilters(parsed)
      } catch (err) {
        console.error('Failed to parse saved filters:', err)
      }
    }
  }, [])

  // Save filters to localStorage when changed
  useEffect(() => {
    localStorage.setItem('projectFilters', JSON.stringify(filters))
  }, [filters])

  const updateFilter = useCallback((filterName, value) => {
    setFilters((prev) => ({
      ...prev,
      [filterName]: value,
      // Reset pagination when filter changes
      page: 1
    }))
  }, [])

  const updateMultipleFilters = useCallback((newFilters) => {
    setFilters((prev) => ({
      ...prev,
      ...newFilters,
      page: 1
    }))
  }, [])

  const addStatusFilter = useCallback((status) => {
    setFilters((prev) => ({
      ...prev,
      status: prev.status.includes(status) ? prev.status.filter((s) => s !== status) : [...prev.status, status],
      page: 1
    }))
  }, [])

  const addSkillFilter = useCallback((skill) => {
    setFilters((prev) => ({
      ...prev,
      skills: prev.skills.includes(skill) ? prev.skills.filter((s) => s !== skill) : [...prev.skills, skill],
      page: 1
    }))
  }, [])

  const addPriorityFilter = useCallback((priority) => {
    setFilters((prev) => ({
      ...prev,
      priority: prev.priority.includes(priority) ? prev.priority.filter((p) => p !== priority) : [...prev.priority, priority],
      page: 1
    }))
  }, [])

  const removeFilter = useCallback((filterName, value) => {
    setFilters((prev) => ({
      ...prev,
      [filterName]: Array.isArray(prev[filterName]) ? prev[filterName].filter((item) => item !== value) : '',
      page: 1
    }))
  }, [])

  const clearAllFilters = useCallback(() => {
    setFilters({
      minBudget: '',
      maxBudget: '',
      status: [],
      skills: [],
      priority: [],
      matchType: 'any',
      sort: 'newest'
    })
    setResults({
      projects: [],
      pagination: { total: 0, page: 1, limit: 10, pages: 0 },
      appliedFilters: {}
    })
  }, [])

  const hasActiveFilters = useCallback(() => {
    return filters.minBudget || filters.maxBudget || filters.status.length > 0 || filters.skills.length > 0 || filters.priority.length > 0 || filters.sort !== 'newest'
  }, [filters])

  const fetchFilteredProjects = useCallback(
    async (page = 1) => {
      try {
        setLoading(true)
        setError(null)

        // Build query parameters
        const params = new URLSearchParams()

        if (filters.minBudget) params.append('minBudget', filters.minBudget)
        if (filters.maxBudget) params.append('maxBudget', filters.maxBudget)
        if (filters.status.length > 0) params.append('status', filters.status.join(','))
        if (filters.skills.length > 0) params.append('skills', filters.skills.join(','))
        if (filters.priority.length > 0) params.append('priority', filters.priority.join(','))

        params.append('matchType', filters.matchType)
        params.append('sort', filters.sort)
        params.append('page', page)
        params.append('limit', 10)

        const response = await fetch(`${import.meta.env.VITE_API_URL}/api/projects/filter?${params.toString()}`, {
          method: 'GET',
          headers: { 'Content-Type': 'application/json' },
          credentials: 'include'
        })

        if (!response.ok) {
          throw new Error('Failed to fetch filtered projects')
        }

        const data = await response.json()
        setResults(data.data)
        setError(null)
      } catch (err) {
        console.error('Error fetching filtered projects:', err)
        setError(err.message)
        toast.error('Failed to fetch filtered projects')
      } finally {
        setLoading(false)
      }
    },
    [filters]
  )

  const updatePage = useCallback(
    (page) => {
      setFilters((prev) => ({ ...prev, page }))
      fetchFilteredProjects(page)
    },
    [fetchFilteredProjects]
  )

  return {
    filters,
    loading,
    error,
    results,
    updateFilter,
    updateMultipleFilters,
    addStatusFilter,
    addSkillFilter,
    addPriorityFilter,
    removeFilter,
    clearAllFilters,
    hasActiveFilters,
    fetchFilteredProjects,
    updatePage
  }
}

import { useState, useCallback, useEffect } from 'react'
import { toast } from 'react-toastify'

const STORAGE_KEY = 'projectFilterPresets'

export const useSavedFilterPresets = () => {
  const [presets, setPresets] = useState([])
  const [loading, setLoading] = useState(true)

  // Load presets from localStorage on mount
  useEffect(() => {
    const savedPresets = localStorage.getItem(STORAGE_KEY)
    if (savedPresets) {
      try {
        const parsed = JSON.parse(savedPresets)
        setPresets(Array.isArray(parsed) ? parsed : [])
      } catch (err) {
        console.error('Failed to parse saved filter presets:', err)
        setPresets([])
      }
    }
    setLoading(false)
  }, [])

  // Save presets to localStorage whenever they change
  useEffect(() => {
    if (!loading) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(presets))
    }
  }, [presets, loading])

  const createPreset = useCallback(
    (name, filters) => {
      // Check for duplicate names
      if (presets.some((p) => p.name.toLowerCase() === name.toLowerCase())) {
        toast.warning('A preset with this name already exists')
        return false
      }

      const newPreset = {
        id: Date.now().toString(),
        name,
        filters: { ...filters },
        createdAt: new Date().toISOString(),
        usageCount: 0
      }

      setPresets((prev) => [...prev, newPreset])
      toast.success(`Filter preset "${name}" saved`)
      return true
    },
    [presets]
  )

  const updatePreset = useCallback((presetId, updates) => {
    setPresets((prev) =>
      prev.map((p) =>
        p.id === presetId
          ? {
              ...p,
              ...updates,
              updatedAt: new Date().toISOString()
            }
          : p
      )
    )
  }, [])

  const deletePreset = useCallback(
    (presetId) => {
      const preset = presets.find((p) => p.id === presetId)
      setPresets((prev) => prev.filter((p) => p.id !== presetId))
      toast.success(`Filter preset "${preset?.name}" deleted`)
    },
    [presets]
  )

  const loadPreset = useCallback(
    (presetId) => {
      const preset = presets.find((p) => p.id === presetId)
      if (preset) {
        // Increment usage count
        updatePreset(presetId, {
          usageCount: (preset.usageCount || 0) + 1,
          lastUsedAt: new Date().toISOString()
        })
        return preset.filters
      }
      return null
    },
    [presets, updatePreset]
  )

  const renamePreset = useCallback(
    (presetId, newName) => {
      // Check for duplicate names
      if (presets.some((p) => p.id !== presetId && p.name.toLowerCase() === newName.toLowerCase())) {
        toast.warning('A preset with this name already exists')
        return false
      }

      updatePreset(presetId, { name: newName })
      toast.success(`Filter preset renamed to "${newName}"`)
      return true
    },
    [presets, updatePreset]
  )

  const getRecentPresets = useCallback(
    (limit = 5) => {
      return presets
        .sort((a, b) => {
          const aDate = new Date(a.lastUsedAt || a.createdAt)
          const bDate = new Date(b.lastUsedAt || b.createdAt)
          return bDate - aDate
        })
        .slice(0, limit)
    },
    [presets]
  )

  const getMostUsedPresets = useCallback(
    (limit = 5) => {
      return presets.sort((a, b) => (b.usageCount || 0) - (a.usageCount || 0)).slice(0, limit)
    },
    [presets]
  )

  return {
    presets,
    loading,
    createPreset,
    updatePreset,
    deletePreset,
    loadPreset,
    renamePreset,
    getRecentPresets,
    getMostUsedPresets
  }
}

