              <button type='submit' className='px-5 py-2 rounded-lg bg-red-600 text-white font-semibold shadow hover:bg-red-700'>
                Lock Account
              </button>
            </div>
          </form>
        </motion.div>
      </motion.div>
    </AnimatePresence>
  )
}

