import { useEffect, useMemo, useState } from 'react'
import PageBackground from '../components/shared/PageBackground'
import LoadingSpinner from '../components/shared/LoadingSpinner'
import AboutHero from '../components/About/AboutHero'
import AboutHighlights from '../components/About/AboutHighlights'
import AboutCta from '../components/About/AboutCta'
import { getPublicSystemConfig } from '../services/configService'
import { getSectionBackgroundClass } from '../components/Home/homeSectionLayout'

const DEFAULT_ABOUT_SECTION_ORDER = ['hero', 'highlights', 'cta']

const About = () => {
  const [publicConfig, setPublicConfig] = useState(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')

  useEffect(() => {
    const loadConfig = async () => {
      try {
        setLoading(true)
        setError('')
        const data = await getPublicSystemConfig()
        setPublicConfig(data || null)
      } catch (err) {
        setError(err.response?.data?.message || 'Failed to load About page.')
      } finally {
        setLoading(false)
      }
    }

    loadConfig()
  }, [])

  const aboutContent = useMemo(() => {
    if (!publicConfig?.about?.enabled) return {}
    return publicConfig.about.values || {}
  }, [publicConfig])

  const aboutHeroBuilder = useMemo(() => {
    if (!publicConfig?.siteBuilder?.enabled) return {}
    return publicConfig.siteBuilder.values?.aboutHero || {}
  }, [publicConfig])

  const aboutHighlightsBuilder = useMemo(() => {
    if (!publicConfig?.siteBuilder?.enabled) return {}
    return publicConfig.siteBuilder.values?.aboutHighlights || {}
  }, [publicConfig])

  const aboutCtaBuilder = useMemo(() => {
    if (!publicConfig?.siteBuilder?.enabled) return {}
    return publicConfig.siteBuilder.values?.aboutCta || {}
  }, [publicConfig])

  const aboutSectionVisibility = useMemo(() => {
    if (!publicConfig?.siteBuilder?.enabled) return {}
    return publicConfig.siteBuilder.values?.aboutSections || {}
  }, [publicConfig])

  const aboutSectionOrder = useMemo(() => {
    if (!publicConfig?.siteBuilder?.enabled) return DEFAULT_ABOUT_SECTION_ORDER

    const savedOrder = publicConfig.siteBuilder.values?.aboutSectionOrder
    if (!Array.isArray(savedOrder) || !savedOrder.length) {
      return DEFAULT_ABOUT_SECTION_ORDER
    }

    const allowedKeys = new Set(DEFAULT_ABOUT_SECTION_ORDER)
    const sanitizedOrder = savedOrder.filter((key) => allowedKeys.has(key))
    const missingKeys = DEFAULT_ABOUT_SECTION_ORDER.filter((key) => !sanitizedOrder.includes(key))

    return [...sanitizedOrder, ...missingKeys]
  }, [publicConfig])

  const aboutSectionBackgrounds = useMemo(() => {
    if (!publicConfig?.siteBuilder?.enabled) return {}
    return publicConfig.siteBuilder.values?.aboutSectionBackgrounds || {}
  }, [publicConfig])

  const headline = aboutContent.headline || 'Build your freelance career with confidence'
  const subheadline = aboutContent.subheadline || 'Connect clients and freelancers in one place'
  const mission = aboutContent.mission || 'SkillBridge helps people find the right collaboration faster. We bring serious clients and capable freelancers into one workflow that feels clear, practical, and trustworthy.'
  const vision = aboutContent.vision || 'We want project collaboration to feel simpler: fewer dead ends, better matches, stronger communication, and a platform that scales with both independent talent and growing teams.'
  const ctaEyebrow = aboutContent.ctaEyebrow || 'Next Step'
  const ctaHeadline = aboutContent.ctaHeadline || 'Explore the platform or create your account'
  const ctaBody = aboutContent.ctaBody || 'Whether you are hiring, freelancing, or doing both, SkillBridge is built to make project collaboration easier to start and easier to manage.'
  const ctaPrimaryLabel = aboutContent.ctaPrimaryLabel || 'Explore Listings'
  const ctaPrimaryHref = aboutContent.ctaPrimaryHref || '/listings'
  const ctaSecondaryLabel = aboutContent.ctaSecondaryLabel || 'Join SkillBridge'
  const ctaSecondaryHref = aboutContent.ctaSecondaryHref || '/register'
  const showHero = aboutSectionVisibility.showHero ?? true
  const showHighlights = aboutSectionVisibility.showHighlights ?? true
  const showCta = aboutSectionVisibility.showCta ?? true

  return (
    <section className='w-full relative z-[1] pt-[80px]'>
      <PageBackground />

      {loading && (
        <div className='container mx-auto px-4 py-12 relative z-10 min-h-[calc(100vh-336px)]'>
          <div className='flex items-center justify-center min-h-[320px]'>
            <LoadingSpinner />
          </div>
        </div>
      )}

      {!loading && error && (
        <div className='container mx-auto px-4 py-12 relative z-10 min-h-[calc(100vh-336px)]'>
          <div className='rounded-xl border border-red-200 dark:border-red-900/40 bg-red-50 dark:bg-red-900/20 px-5 py-4 text-red-700 dark:text-red-300'>{error}</div>
        </div>
      )}

      {!loading && !error && (
        <div className='relative z-10 flex flex-col gap-4 pb-20'>
          {aboutSectionOrder
            .map((sectionKey) => {
              switch (sectionKey) {
                case 'hero':
                  return showHero ? (
                    <section key='hero' className='relative z-10'>
                      <div className='container mx-auto px-4'>
                        <AboutHero eyebrow='About SkillBridge' headline={headline} subheadline={subheadline} layout={aboutHeroBuilder} />
                      </div>
                    </section>
                  ) : null

                case 'highlights':
                  return showHighlights ? (
                    <section key='highlights' className='relative z-10'>
                      <div className='container mx-auto px-4'>
                        <AboutHighlights mission={mission} vision={vision} layout={aboutHighlightsBuilder} />
                      </div>
                    </section>
                  ) : null

                case 'cta':
                  return showCta ? (
                    <section key='cta' className='relative z-10'>
                      <div className='container mx-auto px-4'>
                        <AboutCta
                          eyebrow={ctaEyebrow}
                          headline={ctaHeadline}
                          body={ctaBody}
                          primaryLabel={ctaPrimaryLabel}
                          primaryHref={ctaPrimaryHref}
                          secondaryLabel={ctaSecondaryLabel}
                          secondaryHref={ctaSecondaryHref}
                          layout={aboutCtaBuilder}
                        />
                      </div>
                    </section>
                  ) : null

                default:
                  return null
              }
            })
            .filter(Boolean)}
        </div>
      )}
    </section>
  )
}

export default About

import { useEffect, useMemo, useState } from 'react'
import { Link, useSearchParams } from 'react-router-dom'
import AdminHeader from '../components/Admin/AdminHeader'
import AdminSidebar from '../components/Admin/AdminSidebar'
import AdminStats from '../components/Admin/AdminStats'
import AdminUsersList from '../components/Admin/AdminUsersList'
import AdminProjectsList from '../components/Admin/AdminProjectsList'
import AdminAnnouncementsList from '../components/Admin/AdminAnnouncementsList'
import AdminSettings from '../components/Admin/AdminSettings'
import AdminBlogPostsList from '../components/Admin/AdminBlogPostsList'
import { useAuth } from '../context/AuthContext'
import { canAccessAdminSection, getAdminSections, getDefaultAdminSection } from '../utils/accessRoles'
import { DEFAULT_SETTINGS_SECTION } from '../components/Admin/settingsNavigation'

const formatLabel = (value) => {
  if (!value) return ''
  return value.replace(/[-_.]/g, ' ').replace(/\b\w/g, (char) => char.toUpperCase())
}

const getSettingsBreadcrumbItems = (activeSettingsSection) => {
  const items = [{ label: 'Admin', to: '/admin' }, { label: 'Settings' }]

  if (!activeSettingsSection) {
    return items
  }

  if (activeSettingsSection.startsWith('home.')) {
    const [, child] = activeSettingsSection.split('.')
    items.push({ label: 'Home Page' })
    items.push({ label: formatLabel(child === 'hero' ? 'hero sections' : child) })
    return items
  }

  items.push({ label: formatLabel(activeSettingsSection) })
  return items
}

const Admin = () => {
  const { currentUser } = useAuth()
  const [activeSection, setActiveSection] = useState('dashboard')
  const [activeSettingsSection, setActiveSettingsSection] = useState(DEFAULT_SETTINGS_SECTION)
  const [adminSectionRequest, setAdminSectionRequest] = useState(null)
  const [searchParams, setSearchParams] = useSearchParams()

  const availableSections = useMemo(() => getAdminSections(currentUser), [currentUser])
  const defaultSection = useMemo(() => getDefaultAdminSection(currentUser), [currentUser])

  const buildRequestFromSearchParams = () => {
    const section = searchParams.get('section') || 'dashboard'

    const filters = {
      status: searchParams.get('status') || '',
      verification: searchParams.get('verification') || '',
      passwordResetRequired: searchParams.get('passwordResetRequired') || '',
      stalled: searchParams.get('stalled') || '',
      sort: searchParams.get('sort') || ''
    }

    return { section, filters }
  }

  const updateAdminSearchParams = (section, filters = {}) => {
    const nextParams = new URLSearchParams()

    nextParams.set('section', section)

    Object.entries(filters).forEach(([key, value]) => {
      if (value) {
        nextParams.set(key, value)
      }
    })

    setSearchParams(nextParams)
  }

  const handleSetActiveSection = (section) => {
    setActiveSection(section)
    setAdminSectionRequest(null)
    updateAdminSearchParams(section)
  }

  const handleOpenSection = (section, filters = {}) => {
    setActiveSection(section)
    setAdminSectionRequest({
      section,
      filters,
      requestId: Date.now()
    })
    updateAdminSearchParams(section, filters)
  }

  useEffect(() => {
    if (!defaultSection) {
      return
    }

    if (!canAccessAdminSection(currentUser, activeSection)) {
      setActiveSection(defaultSection)
      setAdminSectionRequest(null)
      updateAdminSearchParams(defaultSection)
    }
  }, [currentUser, activeSection, defaultSection])

  const breadcrumbItems = useMemo(() => {
    if (activeSection === 'settings') {
      return getSettingsBreadcrumbItems(activeSettingsSection)
    }

    return [{ label: 'Admin', to: '/admin' }, { label: formatLabel(activeSection) }]
  }, [activeSection, activeSettingsSection])

  if (!availableSections.length) {
    return null
  }

  useEffect(() => {
    const { section, filters } = buildRequestFromSearchParams()

    if (!canAccessAdminSection(currentUser, section)) {
      return
    }

    setActiveSection(section)

    if (section === 'users' || section === 'projects') {
      setAdminSectionRequest({
        section,
        filters,
        requestId: Date.now()
      })
    } else {
      setAdminSectionRequest(null)
    }
  }, [searchParams, currentUser])

  return (
    <div className='flex min-h-[calc(100vh-68px)] bg-gray-100 dark:bg-gray-900 pt-[68px]'>
      <AdminSidebar activeSection={activeSection} setActiveSection={handleSetActiveSection} activeSettingsSection={activeSettingsSection} setActiveSettingsSection={setActiveSettingsSection} />

      <div className='flex-1 min-w-0 flex flex-col'>
        <AdminHeader activeSection={activeSection} />
        <main className='flex-1 overflow-x-hidden'>
          <div className='container mx-auto px-6 py-8'>
            <nav aria-label='Breadcrumb' className='mb-4'>
              <ol className='flex flex-wrap items-center gap-2 text-sm text-gray-500 dark:text-gray-400'>
                {breadcrumbItems.map((item, index) => {
                  const isLast = index === breadcrumbItems.length - 1

                  return (
                    <li key={`${item.label}-${index}`} className='flex items-center gap-2'>
                      {index > 0 && <span>/</span>}
                      {item.to && !isLast ? (
                        <Link to={item.to} className='hover:text-accent transition-all duration-300'>
                          {item.label}
                        </Link>
                      ) : (
                        <span className={isLast ? 'text-gray-900 dark:text-white font-medium' : ''}>{item.label}</span>
                      )}
                    </li>
                  )
                })}
              </ol>
            </nav>

            {activeSection === 'dashboard' && canAccessAdminSection(currentUser, 'dashboard') && <AdminStats onOpenSection={handleOpenSection} />}
            {activeSection === 'users' && canAccessAdminSection(currentUser, 'users') && <AdminUsersList navigationRequest={adminSectionRequest} />}
            {activeSection === 'projects' && canAccessAdminSection(currentUser, 'projects') && <AdminProjectsList navigationRequest={adminSectionRequest} />}
            {activeSection === 'announcements' && canAccessAdminSection(currentUser, 'announcements') && <AdminAnnouncementsList />}
            {activeSection === 'blog' && canAccessAdminSection(currentUser, 'blog') && <AdminBlogPostsList />}
            {activeSection === 'settings' && canAccessAdminSection(currentUser, 'settings') && <AdminSettings activeSectionId={activeSettingsSection} />}
          </div>
        </main>
      </div>
    </div>
  )
}

export default Admin

import { useEffect, useMemo, useState } from 'react'
import { Link, useNavigate, useParams } from 'react-router-dom'
import { toast } from 'react-toastify'
import { getAdminUserAnnouncements, getAdminUserDetail, getAdminUserProjects, toggleUserLock, updateAdminUser } from '../services/userService'
import { deleteAnnouncementAsAdmin, toggleAnnouncementStatusAsAdmin } from '../services/announcementService'
import { deleteProjectAsAdmin, removeAssigneeAsAdmin, toggleProjectLockAsAdmin } from '../services/projectService'
import AdminLockProjectModal from '../modal/AdminLockProjectModal'
import AdminUserEditModal from '../modal/AdminUserEditModal'
import AdminLockUserModal from '../modal/AdminLockUserModal'
import AdminMailUserModal from '../modal/AdminMailUserModal'
import PaginationControls from '../components/shared/PaginationControls'

const tabs = [
  { id: 'details', label: 'User Details' },
  { id: 'stats', label: 'Stats' },
  { id: 'projects', label: 'Projects' },
  { id: 'announcements', label: 'Announcements' }
]

const formatDateTime = (value) => {
  if (!value) return 'N/A'
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return 'N/A'
  return date.toLocaleString()
}

const formatMoney = (value) => {
  if (value === undefined || value === null || Number.isNaN(Number(value))) return 'N/A'
  return `Γé¼${Number(value)}`
}

const AdminUserDetail = () => {
  const { id } = useParams()
  const navigate = useNavigate()
  const [activeTab, setActiveTab] = useState('details')

  // User detail state
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [user, setUser] = useState(null)
  const [metrics, setMetrics] = useState(null)

  // Projects state
  const [projects, setProjects] = useState([])
  const [projectsMeta, setProjectsMeta] = useState({ total: 0, page: 1, pages: 1 })
  const [projectsLoading, setProjectsLoading] = useState(false)
  const [projectQuery, setProjectQuery] = useState({
    page: 1,
    limit: 10,
    status: 'all',
    scope: 'all',
    sort: 'createdAt:desc'
  })

  // Announcements state
  const [announcements, setAnnouncements] = useState([])
  const [announcementsMeta, setAnnouncementsMeta] = useState({ total: 0, page: 1, pages: 1 })
  const [announcementsLoading, setAnnouncementsLoading] = useState(false)
  const [announcementQuery, setAnnouncementQuery] = useState({
    page: 1,
    limit: 10,
    status: 'all',
    sort: 'createdAt:desc'
  })

  // Modals state
  const [isEditModalOpen, setIsEditModalOpen] = useState(false)
  const [isLockModalOpen, setIsLockModalOpen] = useState(false)
  const [isMailModalOpen, setIsMailModalOpen] = useState(false)
  const [isProjectLockModalOpen, setIsProjectLockModalOpen] = useState(false)
  const [projectToLock, setProjectToLock] = useState(null)
  const [projectActionLoadingId, setProjectActionLoadingId] = useState(null)
  const [announcementActionLoadingId, setAnnouncementActionLoadingId] = useState(null)

  const headerSubtitle = useMemo(() => {
    if (!id) return 'No user selected'
    if (!user) return `User ID: ${id}`
    return `${user.firstName || ''} ${user.lastName || ''}`.trim() || `User ID: ${id}`
  }, [id, user])

  const breadcrumbItems = useMemo(() => {
    const items = [
      { label: 'Admin', to: '/admin' },
      { label: 'Users', to: '/admin' }
    ]

    if (user) {
      items.push({
        label: `${user.firstName || ''} ${user.lastName || ''}`.trim() || `User ID: ${id}`
      })
    } else if (id) {
      items.push({ label: `User ID: ${id}` })
    }

    return items
  }, [id, user])

  const loadUserDetail = async ({ showToastOnError = true } = {}) => {
    if (!id) {
      setError('Missing user id in route')
      setLoading(false)
      return false
    }

    try {
      setLoading(true)
      setError('')
      const response = await getAdminUserDetail(id)
      setUser(response.user || null)
      setMetrics(response.metrics || null)
      return true
    } catch (err) {
      const message = err?.response?.data?.message || 'Failed to load user details'
      setError(message)
      if (showToastOnError) toast.error(message)
      return false
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadUserDetail()
  }, [id])

  useEffect(() => {
    setProjectQuery((prev) => ({ ...prev, page: 1 }))
    setAnnouncementQuery((prev) => ({ ...prev, page: 1 }))
  }, [id])

  useEffect(() => {
    const loadProjects = async () => {
      if (!id || activeTab !== 'projects') return
      try {
        setProjectsLoading(true)
        const response = await getAdminUserProjects(id, projectQuery)
        setProjects(response.projects || [])
        setProjectsMeta({
          total: response.total || 0,
          page: response.page || 1,
          pages: response.pages || 1
        })
      } catch (err) {
        toast.error(err?.response?.data?.message || 'Failed to load user projects')
      } finally {
        setProjectsLoading(false)
      }
    }

    loadProjects()
  }, [activeTab, id, projectQuery])

  useEffect(() => {
    const loadAnnouncements = async () => {
      if (!id || activeTab !== 'announcements') return
      try {
        setAnnouncementsLoading(true)
        const response = await getAdminUserAnnouncements(id, announcementQuery)
        setAnnouncements(response.announcements || [])
        setAnnouncementsMeta({
          total: response.total || 0,
          page: response.page || 1,
          pages: response.pages || 1
        })
      } catch (err) {
        toast.error(err?.response?.data?.message || 'Failed to load user announcements')
      } finally {
        setAnnouncementsLoading(false)
      }
    }

    loadAnnouncements()
  }, [activeTab, announcementQuery, id])

  const statusLabel = useMemo(() => {
    if (!user) return 'Unknown'
    if (user.isLocked) return 'Locked'
    return 'Active'
  }, [user])

  const refreshAll = async () => {
    const ok = await loadUserDetail({ showToastOnError: true })
    if (!ok) return

    if (activeTab === 'projects') {
      setProjectQuery((prev) => ({ ...prev }))
    }

    if (activeTab === 'announcements') {
      setAnnouncementQuery((prev) => ({ ...prev }))
    }

    toast.success('User data refreshed')
  }

  const handleSaveUser = async (payload) => {
    try {
      if (!payload?._id) {
        toast.error('Invalid user payload')
        return
      }
      await updateAdminUser(payload._id, payload)
      setIsEditModalOpen(false)
      await loadUserDetail({ showToastOnError: false })
      toast.success('User updated successfully')
    } catch (err) {
      toast.error(err?.response?.data?.message || 'Failed to update user')
    }
  }

  const handleConfirmLock = async ({ reason, durationDays }) => {
    try {
      if (!user?._id) return
      await toggleUserLock(user._id, { reason, durationDays })
      setIsLockModalOpen(false)
      await loadUserDetail({ showToastOnError: false })
      toast.success('User locked successfully')
    } catch (err) {
      toast.error(err?.response?.data?.message || 'Failed to lock user')
    }
  }

  const handleUnlock = async () => {
    if (!user?._id) return
    const confirmed = window.confirm(`Unlock ${user.firstName} ${user.lastName}?`)
    if (!confirmed) return

    try {
      await toggleUserLock(user._id)
      await loadUserDetail({ showToastOnError: false })
      toast.success('User unlocked successfully')
    } catch (err) {
      toast.error(err?.response?.data?.message || 'Failed to unlock user')
    }
  }

  const reloadProjects = async () => {
    if (!id) return
    try {
      setProjectsLoading(true)
      const response = await getAdminUserProjects(id, projectQuery)
      setProjects(response.projects || [])
      setProjectsMeta({
        total: response.total || 0,
        page: response.page || 1,
        pages: response.pages || 1
      })
    } catch (err) {
      toast.error(err?.response?.data?.message || 'Failed to reload projects')
    } finally {
      setProjectsLoading(false)
    }
  }

  const handleToggleProjectLock = async (project) => {
    if (!project?._id) return

    if (!project.isLocked) {
      setProjectToLock(project)
      setIsProjectLockModalOpen(true)
      return
    }

    try {
      setProjectActionLoadingId(project._id)
      await toggleProjectLockAsAdmin(project._id)
      await reloadProjects()
      await loadUserDetail({ showToastOnError: false })
      toast.success('Project unlocked successfully')
    } catch (err) {
      toast.error(err?.response?.data?.message || 'Failed to unlock project')
    } finally {
      setProjectActionLoadingId(null)
    }
  }

  const handleConfirmProjectLock = async ({ reason, durationDays }) => {
    if (!projectToLock?._id) return

    try {
      setProjectActionLoadingId(projectToLock._id)
      await toggleProjectLockAsAdmin(projectToLock._id, { reason, durationDays })
      setIsProjectLockModalOpen(false)
      setProjectToLock(null)
      await reloadProjects()
      await loadUserDetail({ showToastOnError: false })
      toast.success('Project locked successfully')
    } catch (err) {
      toast.error(err?.response?.data?.message || 'Failed to lock project')
    } finally {
      setProjectActionLoadingId(null)
    }
  }

  const handleRemoveProjectAssignee = async (project) => {
    if (!project?._id) return

    if (!project.assignee) {
      toast.info('This project has no assignee')
      return
    }

    const assigneeName = `${project.assignee.firstName || ''} ${project.assignee.lastName || ''}`.trim() || 'Unknown user'
    const confirmed = window.confirm(`Remove assignee "${assigneeName}" from this project?`)
    if (!confirmed) return

    try {
      setProjectActionLoadingId(project._id)
      await removeAssigneeAsAdmin(project._id)
      await reloadProjects()
      await loadUserDetail({ showToastOnError: false })
      toast.success('Assignee removed successfully')
    } catch (err) {
      toast.error(err?.response?.data?.message || 'Failed to remove assignee')
    } finally {
      setProjectActionLoadingId(null)
    }
  }

  const handleCancelProject = async (project) => {
    if (!project?._id) return

    const confirmed = window.confirm(`Cancel project "${project.title || 'Untitled project'}" as admin?`)
    if (!confirmed) return

    try {
      setProjectActionLoadingId(project._id)
      await deleteProjectAsAdmin(project._id)
      await reloadProjects()
      await loadUserDetail({ showToastOnError: false })
      toast.success('Project canceled by admin')
    } catch (err) {
      toast.error(err?.response?.data?.message || 'Failed to cancel project')
    } finally {
      setProjectActionLoadingId(null)
    }
  }

  const reloadAnnouncements = async () => {
    if (!id) return
    try {
      setAnnouncementsLoading(true)
      const response = await getAdminUserAnnouncements(id, announcementQuery)
      setAnnouncements(response.announcements || [])
      setAnnouncementsMeta({
        total: response.total || 0,
        page: response.page || 1,
        pages: response.pages || 1
      })
    } catch (err) {
      toast.error(err?.response?.data?.message || 'Failed to reload announcements')
    } finally {
      setAnnouncementsLoading(false)
    }
  }

  const handleToggleAnnouncement = async (announcementId) => {
    try {
      setAnnouncementActionLoadingId(announcementId)
      await toggleAnnouncementStatusAsAdmin(announcementId)
      await reloadAnnouncements()
      await loadUserDetail({ showToastOnError: false })
      toast.success('Announcement status updated')
    } catch (err) {
      toast.error(err?.response?.data?.message || 'Failed to update announcement status')
    } finally {
      setAnnouncementActionLoadingId(null)
    }
  }

  const handleDeleteAnnouncement = async (announcementId, title) => {
    const confirmed = window.confirm(`Delete announcement "${title}"?`)
    if (!confirmed) return

    try {
      setAnnouncementActionLoadingId(announcementId)
      await deleteAnnouncementAsAdmin(announcementId)
      await reloadAnnouncements()
      await loadUserDetail({ showToastOnError: false })
      toast.success('Announcement deleted')
    } catch (err) {
      toast.error(err?.response?.data?.message || 'Failed to delete announcement')
    } finally {
      setAnnouncementActionLoadingId(null)
    }
  }

  const resetProjectFilters = () => {
    setProjectQuery({
      page: 1,
      limit: 10,
      status: 'all',
      scope: 'all',
      sort: 'createdAt:desc'
    })
  }

  const resetAnnouncementFilters = () => {
    setAnnouncementQuery({
      page: 1,
      limit: 10,
      status: 'all',
      sort: 'createdAt:desc'
    })
  }

  const getTabCount = (tabId) => {
    if (tabId === 'stats') {
      return (metrics?.createdProjects ?? 0) + (metrics?.assignedProjects ?? 0)
    }
    if (tabId === 'projects') {
      return projectsMeta?.total ?? 0
    }
    if (tabId === 'announcements') {
      return announcementsMeta?.total ?? 0
    }
    return null
  }

  const hasProjectFilters = projectQuery.scope !== 'all' || projectQuery.status !== 'all' || projectQuery.sort !== 'createdAt:desc' || projectQuery.limit !== 10
  const hasAnnouncementFilters = announcementQuery.status !== 'all' || announcementQuery.sort !== 'createdAt:desc' || announcementQuery.limit !== 10

  return (
    <div className='min-h-screen bg-gray-100 dark:bg-gray-900 pt-[68px]'>
      <div className='container mx-auto px-6 py-8'>
        <div className='mb-6 flex items-start justify-between gap-4'>
          <div>
            <nav aria-label='Breadcrumb' className='mb-3'>
              <ol className='flex flex-wrap items-center gap-2 text-sm text-gray-500 dark:text-gray-400'>
                {breadcrumbItems.map((item, index) => {
                  const isLast = index === breadcrumbItems.length - 1

                  return (
                    <li key={`${item.label}-${index}`} className='flex items-center gap-2'>
                      {index > 0 && <span>/</span>}
                      {item.to && !isLast ? (
                        <Link to={item.to} className='hover:text-accent transition-all duration-300'>
                          {item.label}
                        </Link>
                      ) : (
                        <span className={isLast ? 'text-gray-900 dark:text-white font-medium' : ''}>{item.label}</span>
                      )}
                    </li>
                  )
                })}
              </ol>
            </nav>
            <h1 className='text-2xl font-bold text-gray-900 dark:text-white'>Admin User Detail</h1>
            <p className='text-sm text-gray-500 dark:text-gray-400 mt-1'>{headerSubtitle}</p>
          </div>

          <div className='flex flex-wrap items-center gap-2'>
            <button
              onClick={refreshAll}
              className='px-4 py-2 rounded-lg border border-gray-300 dark:border-gray-700 text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-800 transition-all duration-300 hover:shadow-lg'>
              Refresh
            </button>

            {user && (
              <>
                <button onClick={() => setIsEditModalOpen(true)} className='px-4 py-2 rounded-lg bg-accent text-white hover:bg-accent/90 transition-all duration-300 hover:shadow-lg'>
                  Edit User
                </button>

                {!user.isLocked ? (
                  <button onClick={() => setIsLockModalOpen(true)} className='px-4 py-2 rounded-lg bg-red-600 text-white hover:bg-red-700 transition-all duration-300 hover:shadow-lg'>
                    Lock User
                  </button>
                ) : (
                  <button onClick={handleUnlock} className='px-4 py-2 rounded-lg bg-emerald-600 text-white hover:bg-emerald-700 transition-all duration-300 hover:shadow-lg'>
                    Unlock User
                  </button>
                )}

                <button
                  onClick={() => setIsMailModalOpen(true)}
                  className='px-4 py-2 rounded-lg border border-gray-300 dark:border-gray-700 text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-800 transition-all duration-300 hover:shadow-lg'>
                  Mail User
                </button>
              </>
            )}

            <button
              onClick={() => navigate('/admin')}
              className='px-4 py-2 rounded-lg border border-gray-300 dark:border-gray-700 text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-800 transition-all duration-300 hover:shadow-lg'>
              Back to Admin
            </button>
          </div>
        </div>

        <div className='bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 shadow-sm'>
          <div className='border-b border-gray-200 dark:border-gray-700 px-4 pt-4'>
            <div className='flex flex-wrap gap-2'>
              {tabs.map((tab) => (
                <button
                  key={tab.id}
                  onClick={() => setActiveTab(tab.id)}
                  className={`px-4 py-2 rounded-t-lg text-sm font-medium transition-all duration-300 hover:shadow-lg ${
                    activeTab === tab.id ? 'bg-accent text-white' : 'bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-600'
                  }`}>
                  <span className='inline-flex items-center gap-2'>
                    <span>{tab.label}</span>
                    {getTabCount(tab.id) !== null && (
                      <span
                        className={`inline-flex min-w-5 h-5 items-center justify-center rounded-full px-1.5 text-[11px] font-semibold ${
                          activeTab === tab.id ? 'bg-white/20 text-white' : 'bg-gray-200 dark:bg-gray-600 text-gray-700 dark:text-gray-200'
                        }`}>
                        {getTabCount(tab.id)}
                      </span>
                    )}
                  </span>
                </button>
              ))}
            </div>
          </div>

          {/* Announcements Tab */}
          <div className='p-6'>
            {loading && <p className='text-gray-700 dark:text-gray-200'>Loading user details...</p>}
            {!loading && error && <p className='text-red-600 dark:text-red-400'>{error}</p>}

            {!loading && !error && activeTab === 'details' && user && (
              <div className='grid grid-cols-1 md:grid-cols-2 gap-4'>
                <div className='rounded-lg border border-gray-200 dark:border-gray-700 p-4'>
                  <p className='text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400'>Full Name</p>
                  <p className='text-gray-900 dark:text-white font-medium'>{`${user.firstName || ''} ${user.lastName || ''}`.trim() || 'N/A'}</p>
                </div>
                <div className='rounded-lg border border-gray-200 dark:border-gray-700 p-4'>
                  <p className='text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400'>Email</p>
                  <p className='text-gray-900 dark:text-white font-medium'>{user.email || 'N/A'}</p>
                </div>
                <div className='rounded-lg border border-gray-200 dark:border-gray-700 p-4'>
                  <p className='text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400'>Role</p>
                  <p className='text-gray-900 dark:text-white font-medium capitalize'>{user.userType || 'N/A'}</p>
                </div>
                <div className='rounded-lg border border-gray-200 dark:border-gray-700 p-4'>
                  <p className='text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400'>Status</p>
                  <p className='text-gray-900 dark:text-white font-medium'>{statusLabel}</p>
                </div>
                <div className='rounded-lg border border-gray-200 dark:border-gray-700 p-4'>
                  <p className='text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400'>Created At</p>
                  <p className='text-gray-900 dark:text-white font-medium'>{formatDateTime(user.createdAt)}</p>
                </div>
                <div className='rounded-lg border border-gray-200 dark:border-gray-700 p-4'>
                  <p className='text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400'>Last Login</p>
                  <p className='text-gray-900 dark:text-white font-medium'>{formatDateTime(user.lastLogin)}</p>
                </div>
                <div className='rounded-lg border border-gray-200 dark:border-gray-700 p-4'>
                  <p className='text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400'>Phone</p>
                  <p className='text-gray-900 dark:text-white font-medium'>{user?.phone || 'N/A'}</p>
                </div>
                <div className='rounded-lg border border-gray-200 dark:border-gray-700 p-4'>
                  <p className='text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400'>Location</p>
                  <p className='text-gray-900 dark:text-white font-medium'>{user?.location || 'N/A'}</p>
                </div>
                <div className='rounded-lg border border-gray-200 dark:border-gray-700 p-4'>
                  <p className='text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400'>Skills</p>
                  <p className='text-gray-900 dark:text-white font-medium'>{user?.skills || 'N/A'}</p>
                </div>
                <div className='rounded-lg border border-gray-200 dark:border-gray-700 p-4'>
                  <p className='text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400'>Hourly Rate</p>
                  <p className='text-gray-900 dark:text-white font-medium'>{formatMoney(user?.hourlyRate)}</p>
                </div>
                <div className='rounded-lg border border-gray-200 dark:border-gray-700 p-4 md:col-span-2'>
                  <p className='text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400'>Internal Tags</p>
                  <div className='mt-2 flex flex-wrap gap-2'>
                    {Array.isArray(user?.adminTags) && user.adminTags.length > 0 ? (
                      user.adminTags.map((tag) => (
                        <span key={tag} className='inline-flex items-center rounded-full bg-amber-100 px-2.5 py-1 text-xs font-medium text-amber-800 dark:bg-amber-900/30 dark:text-amber-300'>
                          {tag}
                        </span>
                      ))
                    ) : (
                      <p className='text-gray-900 dark:text-white font-medium'>No internal tags</p>
                    )}
                  </div>
                </div>

                <div className='rounded-lg border border-gray-200 dark:border-gray-700 p-4 md:col-span-2'>
                  <p className='text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400'>Internal Admin Notes</p>
                  <p className='mt-2 text-gray-900 dark:text-white font-medium whitespace-pre-wrap'>{user?.adminNotes || 'No internal notes recorded.'}</p>
                </div>
              </div>
            )}

            {!loading && !error && activeTab === 'stats' && (
              <div className='grid grid-cols-1 md:grid-cols-2 gap-4'>
                <div className='rounded-lg border border-gray-200 dark:border-gray-700 p-4'>
                  <p className='text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400'>Created Projects</p>
                  <p className='text-gray-900 dark:text-white font-medium'>{metrics?.createdProjects ?? 0}</p>
                </div>
                <div className='rounded-lg border border-gray-200 dark:border-gray-700 p-4'>
                  <p className='text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400'>Assigned Projects</p>
                  <p className='text-gray-900 dark:text-white font-medium'>{metrics?.assignedProjects ?? 0}</p>
                </div>
                <div className='rounded-lg border border-gray-200 dark:border-gray-700 p-4'>
                  <p className='text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400'>Completed Projects</p>
                  <p className='text-gray-900 dark:text-white font-medium'>{metrics?.completedProjects ?? 0}</p>
                </div>
                <div className='rounded-lg border border-gray-200 dark:border-gray-700 p-4'>
                  <p className='text-xs uppercase tracking-wide text-gray-500 dark:text-gray-400'>Active Announcements</p>
                  <p className='text-gray-900 dark:text-white font-medium'>
                    {metrics?.activeAnnouncements ?? 0} / {metrics?.totalAnnouncements ?? 0}
                  </p>
                </div>
              </div>
            )}

            {!loading && !error && activeTab === 'projects' && (
              <div className='space-y-4'>
                <div className='flex flex-wrap items-center gap-2'>
                  <select
                    value={projectQuery.scope}
                    onChange={(e) => setProjectQuery((prev) => ({ ...prev, scope: e.target.value, page: 1 }))}
                    className='px-4 py-2 rounded-lg border border-gray-200 dark:border-gray-700 focus:outline-none focus:ring-2 focus:ring-accent dark:bg-gray-700 dark:text-white'>
                    <option value='all'>All Scopes</option>
                    <option value='created'>Created</option>
                    <option value='assigned'>Assigned</option>
                  </select>

                  <select
                    value={projectQuery.status}
                    onChange={(e) => setProjectQuery((prev) => ({ ...prev, status: e.target.value, page: 1 }))}
                    className='px-4 py-2 rounded-lg border border-gray-200 dark:border-gray-700 focus:outline-none focus:ring-2 focus:ring-accent dark:bg-gray-700 dark:text-white'>
                    <option value='all'>All Statuses</option>
                    <option value='draft'>Draft</option>
                    <option value='active'>Active</option>
                    <option value='assigned'>Assigned</option>
                    <option value='in_progress'>In Progress</option>
                    <option value='under_review'>Under Review</option>
                    <option value='completed'>Completed</option>
                    <option value='cancelled'>Cancelled</option>
                    <option value='archived'>Archived</option>
                    <option value='paused'>Paused</option>
                  </select>

                  <select
                    value={projectQuery.sort}
                    onChange={(e) => setProjectQuery((prev) => ({ ...prev, sort: e.target.value, page: 1 }))}
                    className='px-4 py-2 rounded-lg border border-gray-200 dark:border-gray-700 focus:outline-none focus:ring-2 focus:ring-accent dark:bg-gray-700 dark:text-white'>
                    <option value='createdAt:desc'>Newest</option>
                    <option value='createdAt:asc'>Oldest</option>
                    <option value='deadline:asc'>Deadline Γåæ</option>
                    <option value='deadline:desc'>Deadline Γåô</option>
                    <option value='budget:desc'>Budget Γåô</option>
                    <option value='budget:asc'>Budget Γåæ</option>
                  </select>

                  <select
                    value={projectQuery.limit}
                    onChange={(e) => setProjectQuery((prev) => ({ ...prev, limit: Number(e.target.value), page: 1 }))}
                    className='px-3 py-2 rounded-lg border border-gray-200 dark:border-gray-700 focus:outline-none focus:ring-2 focus:ring-accent dark:bg-gray-700 dark:text-white'>
                    <option value={10}>10 / page</option>
                    <option value={20}>20 / page</option>
                    <option value={30}>30 / page</option>
                  </select>

                  <button onClick={resetProjectFilters} className='px-4 py-2 text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg transition-all duration-300 hover:shadow-lg'>
                    Reset
                  </button>
                </div>

                <div className='text-sm text-gray-500 dark:text-gray-400'>Total projects: {projectsMeta.total}</div>

                {projectsLoading && <p className='text-gray-700 dark:text-gray-200'>Loading projects...</p>}
                {!projectsLoading && projects.length === 0 && (
                  <div className='rounded-lg border border-gray-200 dark:border-gray-700 p-4'>
                    <p className='text-gray-700 dark:text-gray-200'>No projects found.</p>
                    {hasProjectFilters && (
                      <button
                        onClick={resetProjectFilters}
                        className='mt-3 px-4 py-2 text-sm text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg transition-all duration-300 hover:shadow-lg'>
                        Clear filters
                      </button>
                    )}
                  </div>
                )}

                {!projectsLoading &&
                  projects.map((project) => (
                    <div key={project._id} className='rounded-lg border border-gray-200 dark:border-gray-700 p-4'>
                      <div className='flex items-center justify-between gap-3'>
                        <p className='text-gray-900 dark:text-white font-medium'>{project.title || 'Untitled project'}</p>
                        <span
                          className={`text-xs px-2 py-1 rounded capitalize ${
                            project.isLocked ? 'bg-red-100 text-red-700 dark:bg-red-900 dark:text-red-300' : 'bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-200'
                          }`}>
                          {project.status || 'unknown'}
                        </span>
                      </div>
                      <p className='text-sm text-gray-500 dark:text-gray-400 mt-2'>
                        Budget: {formatMoney(project.budget)} | Deadline: {formatDateTime(project.deadline)}
                      </p>

                      {project.isLocked && (
                        <div className='mt-2 rounded-md border border-red-200 dark:border-red-800 bg-red-50 dark:bg-red-900/20 px-3 py-2'>
                          <p className='text-xs font-medium text-red-700 dark:text-red-300'>
                            Locked
                            {project.lockExpiresAt ? ` until ${formatDateTime(project.lockExpiresAt)}` : ''}
                          </p>
                          {project.lockReason && <p className='text-xs text-red-600 dark:text-red-300/90 mt-1'>Reason: {project.lockReason}</p>}
                        </div>
                      )}
                      <div className='mt-3 flex flex-wrap gap-2'>
                        <button
                          onClick={() => handleToggleProjectLock(project)}
                          disabled={projectActionLoadingId === project._id}
                          className='px-3 py-1.5 text-sm rounded-lg border border-gray-300 dark:border-gray-700 text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 transition-all duration-300 hover:shadow-lg disabled:opacity-60'>
                          {project.isLocked ? 'Unlock' : 'Lock'}
                        </button>

                        <button
                          onClick={() => handleRemoveProjectAssignee(project)}
                          disabled={projectActionLoadingId === project._id}
                          className='px-3 py-1.5 text-sm rounded-lg border border-gray-300 dark:border-gray-700 text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 transition-all duration-300 hover:shadow-lg disabled:opacity-60'>
                          Remove Assignee
                        </button>

                        <button
                          onClick={() => handleCancelProject(project)}
                          disabled={projectActionLoadingId === project._id}
                          className='px-3 py-1.5 text-sm rounded-lg bg-red-600 text-white hover:bg-red-700 transition-all duration-300 hover:shadow-lg disabled:opacity-60'>
                          Cancel
                        </button>
                      </div>
                    </div>
                  ))}

                <PaginationControls
                  currentPage={projectsMeta.page}
                  totalPages={projectsMeta.pages}
                  onPrev={() => setProjectQuery((prev) => ({ ...prev, page: Math.max(1, prev.page - 1) }))}
                  onNext={() => setProjectQuery((prev) => ({ ...prev, page: Math.min(projectsMeta.pages, prev.page + 1) }))}
                  label={`Page ${projectsMeta.page} of ${projectsMeta.pages}`}
                />
              </div>
            )}

            {!loading && !error && activeTab === 'announcements' && (
              <div className='space-y-4'>
                <div className='flex flex-wrap items-center gap-2'>
                  <select
                    value={announcementQuery.status}
                    onChange={(e) => setAnnouncementQuery((prev) => ({ ...prev, status: e.target.value, page: 1 }))}
                    className='px-4 py-2 rounded-lg border border-gray-200 dark:border-gray-700 focus:outline-none focus:ring-2 focus:ring-accent dark:bg-gray-700 dark:text-white'>
                    <option value='all'>All Statuses</option>
                    <option value='active'>Active</option>
                    <option value='inactive'>Inactive</option>
                  </select>

                  <select
                    value={announcementQuery.sort}
                    onChange={(e) => setAnnouncementQuery((prev) => ({ ...prev, sort: e.target.value, page: 1 }))}
                    className='px-4 py-2 rounded-lg border border-gray-200 dark:border-gray-700 focus:outline-none focus:ring-2 focus:ring-accent dark:bg-gray-700 dark:text-white'>
                    <option value='createdAt:desc'>Newest</option>
                    <option value='createdAt:asc'>Oldest</option>
                    <option value='title:asc'>Title A-Z</option>
                    <option value='title:desc'>Title Z-A</option>
                    <option value='hourlyRate:desc'>Rate Γåô</option>
                    <option value='hourlyRate:asc'>Rate Γåæ</option>
                  </select>

                  <select
                    value={announcementQuery.limit}
                    onChange={(e) => setAnnouncementQuery((prev) => ({ ...prev, limit: Number(e.target.value), page: 1 }))}
                    className='px-3 py-2 rounded-lg border border-gray-200 dark:border-gray-700 focus:outline-none focus:ring-2 focus:ring-accent dark:bg-gray-700 dark:text-white'>
                    <option value={10}>10 / page</option>
                    <option value={20}>20 / page</option>
                    <option value={30}>30 / page</option>
                  </select>

                  <button onClick={resetAnnouncementFilters} className='px-4 py-2 text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg transition-all duration-300 hover:shadow-lg'>
                    Reset
                  </button>
                </div>

                <div className='text-sm text-gray-500 dark:text-gray-400'>Total announcements: {announcementsMeta.total}</div>

                {announcementsLoading && <p className='text-gray-700 dark:text-gray-200'>Loading announcements...</p>}
                {!announcementsLoading && announcements.length === 0 && (
                  <div className='rounded-lg border border-gray-200 dark:border-gray-700 p-4'>
                    <p className='text-gray-700 dark:text-gray-200'>No announcements found.</p>
                    {hasAnnouncementFilters && (
                      <button
                        onClick={resetAnnouncementFilters}
                        className='mt-3 px-4 py-2 text-sm text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg transition-all duration-300 hover:shadow-lg'>
                        Clear filters
                      </button>
                    )}
                  </div>
                )}

                {!announcementsLoading &&
                  announcements.map((announcement) => (
                    <div key={announcement._id} className='rounded-lg border border-gray-200 dark:border-gray-700 p-4'>
                      <div className='flex items-center justify-between gap-3'>
                        <p className='text-gray-900 dark:text-white font-medium'>{announcement.title}</p>
                        <span
                          className={`text-xs px-2 py-1 rounded ${
                            announcement.isActive ? 'bg-green-100 text-green-700 dark:bg-green-900 dark:text-green-300' : 'bg-gray-100 text-gray-700 dark:bg-gray-700 dark:text-gray-200'
                          }`}>
                          {announcement.isActive ? 'Active' : 'Inactive'}
                        </span>
                      </div>
                      <p className='text-sm text-gray-500 dark:text-gray-400 mt-2'>
                        Hourly: {formatMoney(announcement.hourlyRate)} | Skills: {(announcement.skills || []).join(', ') || 'N/A'}
                      </p>
                      <div className='mt-3 flex flex-wrap gap-2'>
                        <button
                          onClick={() => handleToggleAnnouncement(announcement._id)}
                          disabled={announcementActionLoadingId === announcement._id}
                          className='px-3 py-1.5 text-sm rounded-lg border border-gray-300 dark:border-gray-700 text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 transition-all duration-300 hover:shadow-lg disabled:opacity-60'>
                          {announcement.isActive ? 'Pause' : 'Resume'}
                        </button>

                        <button
                          onClick={() => handleDeleteAnnouncement(announcement._id, announcement.title)}
                          disabled={announcementActionLoadingId === announcement._id}
                          className='px-3 py-1.5 text-sm rounded-lg bg-red-600 text-white hover:bg-red-700 transition-all duration-300 hover:shadow-lg disabled:opacity-60'>
                          Delete
                        </button>
                      </div>
                    </div>
                  ))}

                <PaginationControls
                  currentPage={announcementsMeta.page}
                  totalPages={announcementsMeta.pages}
                  onPrev={() => setAnnouncementQuery((prev) => ({ ...prev, page: Math.max(1, prev.page - 1) }))}
                  onNext={() => setAnnouncementQuery((prev) => ({ ...prev, page: Math.min(announcementsMeta.pages, prev.page + 1) }))}
                  label={`Page ${announcementsMeta.page} of ${announcementsMeta.pages}`}
                />
              </div>
            )}
          </div>
        </div>
      </div>

      <AdminUserEditModal isOpen={isEditModalOpen} onClose={() => setIsEditModalOpen(false)} user={user} onSave={handleSaveUser} />

      <AdminLockUserModal isOpen={isLockModalOpen} onClose={() => setIsLockModalOpen(false)} onConfirm={handleConfirmLock} user={user} />

      <AdminMailUserModal
        isOpen={isMailModalOpen}
        onClose={() => setIsMailModalOpen(false)}
        recipient={user}
        onSent={() => {
          toast.success('Mail sent successfully')
        }}
      />

      <AdminLockProjectModal
        isOpen={isProjectLockModalOpen}
        onClose={() => {
          setIsProjectLockModalOpen(false)
          setProjectToLock(null)
        }}
        onConfirm={handleConfirmProjectLock}
        project={projectToLock ? { id: projectToLock._id, name: projectToLock.title || 'Untitled project' } : null}
        loading={projectActionLoadingId === projectToLock?._id}
      />
    </div>
  )
}

export default AdminUserDetail

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import { FaClipboardList, FaShieldAlt } from 'react-icons/fa'
import { getFreelancerAnalytics } from '../services/analyticsService'
import LoadingSpinner from '../components/shared/LoadingSpinner'
import AnalyticsOverview from '../components/Analytics/AnalyticsOverview'
import ApplicationsTrend from '../components/Analytics/ApplicationsTrend'
import ApplicationStatus from '../components/Analytics/ApplicationStatus'
import VerificationMetrics from '../components/Analytics/VerificationMetrics'

const Analytics = () => {
  const [analyticsData, setAnalyticsData] = useState(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)

  useEffect(() => {
    const fetchAnalytics = async () => {
      try {
        const data = await getFreelancerAnalytics()
        setAnalyticsData(data)
      } catch (err) {
        setError('Failed to load analytics')
        console.error(err)
      } finally {
        setLoading(false)
      }
    }

    fetchAnalytics()
  }, [])

  if (loading) return <LoadingSpinner />
  if (error) return <div className='text-center text-red-500 p-8'>{error}</div>
  if (!analyticsData) return <div className='text-center p-8'>No data available</div>

  return (
    <main className='min-h-screen py-12 px-4 sm:px-6 bg-white dark:bg-primary'>
      <div className='max-w-7xl mx-auto'>
        <motion.div initial={{ opacity: 0, y: -20 }} animate={{ opacity: 1, y: 0 }} className='mb-12'>
          <h1 className='text-4xl font-bold mb-2 theme-text'>Analytics Dashboard</h1>
          <p className='theme-text-secondary'>Track your applications, profile performance, and conversion metrics</p>
        </motion.div>

        {/* Overview Stats */}
        <AnalyticsOverview stats={analyticsData.stats} />

        {/* Charts Row */}
        <div className='grid grid-cols-1 lg:grid-cols-2 gap-6 mt-8'>
          <ApplicationsTrend data={analyticsData.trendData} />
          <ApplicationStatus data={analyticsData.statusBreakdown} />
        </div>

        {/* Verification Metrics */}
        <VerificationMetrics stats={analyticsData.stats} />

        {/* Recent Applications */}
        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.3 }} className='mt-8 bg-white dark:bg-gray-800 rounded-xl p-6 border border-gray-200 dark:border-gray-700'>
          <h2 className='text-xl font-bold mb-4 theme-text'>Recent Applications</h2>
          {analyticsData.recentApplications.length > 0 ? (
            <div className='space-y-3'>
              {analyticsData.recentApplications.map((app, idx) => (
                <div key={idx} className='flex items-center justify-between p-3 bg-gray-50 dark:bg-gray-900 rounded border border-gray-200 dark:border-gray-700'>
                  <div>
                    <p className='font-semibold theme-text'>{app.projectTitle}</p>
                    <p className='text-sm theme-text-secondary'>{new Date(app.applicationDate).toLocaleDateString()}</p>
                  </div>
                  <span
                    className={`px-3 py-1 rounded text-sm font-semibold ${
                      app.status === 'accepted' ? 'bg-green-500/20 text-green-400' : app.status === 'rejected' ? 'bg-red-500/20 text-red-400' : 'bg-yellow-500/20 text-yellow-400'
                    }`}>
                    {app.status.charAt(0).toUpperCase() + app.status.slice(1)}
                  </span>
                </div>
              ))}
            </div>
          ) : (
            <p className='theme-text-secondary'>No applications yet</p>
          )}
        </motion.div>
      </div>
    </main>
  )
}

