import React, { useState, useEffect } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { FaUser, FaUserFriends, FaProjectDiagram, FaCog, FaLock, FaEnvelope, FaBriefcase, FaStar, FaShieldAlt, FaCheckCircle, FaExclamationTriangle, FaSyncAlt, FaTimes } from 'react-icons/fa'
import { toast } from 'react-toastify'
import ProfileStats from '../components/Profile/ProfileStats'
import ProjectsList from '../components/Profile/ProjectsList'
import ProfileSettings from '../components/Profile/ProfileSettings'
import SecuritySettings from '../components/Profile/SecuritySettings'
import FreelanceTab from '../components/Profile/FreelanceTab'
import RatingsSection from '../components/Profile/RatingsSection'
import MessagesList from '../components/Profile/MessagesList'
import ConnectionsTab from '../components/Profile/ConnectionsTab'
import PageBackground from '../components/shared/PageBackground'
import LoadingSpinner from '../components/shared/LoadingSpinner'

import { getUserMessages } from '../services/messageService'
import { getMyConnections } from '../services/userService'
import { calculateProfileCompleteness } from '../utils/profileCompleteness'
import { getFreelancerRatings, getRatingStats } from '../services/ratingService'
import { requestEmailVerification as requestEmailVerificationService } from '../services/authService'
import { useLocation, useNavigate } from 'react-router-dom'
import { useAuth } from '../context/AuthContext'
import { hasAdminPanelAccess, getAdminRoleLabel, isFullAdmin } from '../utils/accessRoles'

const Profile = () => {
  const [activeTab, setActiveTab] = useState('overview')
  const [messages, setMessages] = useState([])
  const [messagesLoading, setMessagesLoading] = useState(false)
  const [hasLoadedMessages, setHasLoadedMessages] = useState(false)
  const [incomingConnectionCount, setIncomingConnectionCount] = useState(0)
  const [hasLoadedConnections, setHasLoadedConnections] = useState(false)
  const { currentUser, getUserProfile } = useAuth()
  const [ratings, setRatings] = useState(null)
  const [ratingStats, setRatingStats] = useState(null)
  const [ratingsLoading, setRatingsLoading] = useState(false)
  const navigate = useNavigate()
  const location = useLocation()
  const profileCompleteness = calculateProfileCompleteness(currentUser)
  const [isResendingVerification, setIsResendingVerification] = useState(false)
  const [dismissedBanners, setDismissedBanners] = useState({})

  // Redirect if not authenticated
  useEffect(() => {
    if (!currentUser) {
      navigate('/login')
    }
  }, [currentUser, navigate])

  useEffect(() => {
    const requestedTab = location.state?.activeTab

    if (!requestedTab) {
      return
    }

    setActiveTab(requestedTab)
  }, [location.state])

  // Fetch messages once so the unread badge and messages tab can share the same data
  useEffect(() => {
    const fetchMessages = async () => {
      if (!currentUser || hasLoadedMessages) return

      try {
        setMessagesLoading(true)
        const data = await getUserMessages()
        setMessages(data)
        setHasLoadedMessages(true)
      } catch (error) {
        console.error('Error fetching messages:', error)
      } finally {
        setMessagesLoading(false)
      }
    }

    fetchMessages()
  }, [currentUser, hasLoadedMessages])

  useEffect(() => {
    const fetchConnections = async () => {
      if (!currentUser || hasLoadedConnections) return

      try {
        const data = await getMyConnections()
        setIncomingConnectionCount(data?.summary?.incomingCount || 0)
        setHasLoadedConnections(true)
      } catch (error) {
        console.error('Error fetching connections:', error)
        setIncomingConnectionCount(0)
      }
    }

    fetchConnections()
  }, [currentUser, hasLoadedConnections])

  useEffect(() => {
    if (!currentUser?._id) return

    const nextDismissed = {}
    const lockBannerId = getLockBannerId()
    const emailBannerId = getEmailBannerId()

    if (lockBannerId) {
      nextDismissed[lockBannerId] = localStorage.getItem(getBannerStorageKey(lockBannerId)) === 'true'
    }

    if (emailBannerId) {
      nextDismissed[emailBannerId] = localStorage.getItem(getBannerStorageKey(emailBannerId)) === 'true'
    }

    setDismissedBanners(nextDismissed)
  }, [currentUser?._id, currentUser?.isLocked, currentUser?.lockReason, currentUser?.lockDurationDays, currentUser?.lockExpiresAt, currentUser?.isEmailVerified, currentUser?.emailVerifiedAt])

  const unreadMessageCount = Array.isArray(messages) ? messages.filter((message) => !message.isRead && (message.receiver?._id || message.receiver) === currentUser?._id).length : 0

  // Fetch ratings for freelancers
  useEffect(() => {
    const fetchRatings = async () => {
      // Only fetch if user is freelancer
      if (!currentUser || (currentUser.userType !== 'freelancer' && currentUser.userType !== 'both')) {
        return
      }

      try {
        setRatingsLoading(true)
        const ratingsData = await getFreelancerRatings(currentUser._id)
        const statsData = await getRatingStats(currentUser._id)
        setRatings(ratingsData)
        setRatingStats(statsData)
      } catch (error) {
        console.error('Error fetching ratings:', error)
      } finally {
        setRatingsLoading(false)
      }
    }

    fetchRatings()
  }, [currentUser])

  const getRoleLabel = () => {
    if (!currentUser) return ''
    if (currentUser.userType === 'client') return 'Client'
    if (currentUser.userType === 'freelancer') return 'Freelancer'
    if (currentUser.userType === 'both') return 'Client & Freelancer'

    const adminRoleLabel = getAdminRoleLabel(currentUser)
    if (adminRoleLabel) return adminRoleLabel

    return currentUser.userType
  }

  const formatLockDuration = (durationDays) => {
    if (!durationDays) return 'Manual review'
    return `${durationDays} day${durationDays === 1 ? '' : 's'}`
  }

  const getLockCountdown = (lockExpiresAt) => {
    if (!lockExpiresAt) return 'Pending admin review'
    const diffMs = new Date(lockExpiresAt) - new Date()
    if (diffMs <= 0) return 'Unlocking shortly'
    const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24))
    if (diffDays > 0) return `${diffDays} day${diffDays === 1 ? '' : 's'} remaining`
    const diffHours = Math.floor(diffMs / (1000 * 60 * 60))
    if (diffHours > 0) return `${diffHours} hour${diffHours === 1 ? '' : 's'} remaining`
    const diffMinutes = Math.floor(diffMs / (1000 * 60))
    return `${diffMinutes} minute${diffMinutes === 1 ? '' : 's'} remaining`
  }

  const getBannerStorageKey = (bannerId) => {
    if (!currentUser?._id) return ''
    return `profile-banner-dismissed:${currentUser._id}:${bannerId}`
  }

  const getLockBannerId = () => {
    if (!currentUser?.isLocked) return ''
    return ['locked', currentUser.lockReason || 'no-reason', currentUser.lockDurationDays || 'manual', currentUser.lockExpiresAt || 'no-expiry'].join(':')
  }

  const getEmailBannerId = () => {
    if (!currentUser) return ''
    return currentUser.isEmailVerified ? `email-verified:${currentUser.emailVerifiedAt || 'no-date'}` : 'email-unverified'
  }

  const dismissBanner = (bannerId) => {
    const storageKey = getBannerStorageKey(bannerId)
    if (storageKey) {
      localStorage.setItem(storageKey, 'true')
    }

    setDismissedBanners((prev) => ({
      ...prev,
      [bannerId]: true
    }))
  }

  const isBannerDismissed = (bannerId) => {
    if (!bannerId) return false
    return Boolean(dismissedBanners[bannerId])
  }

  const tabs = [
    { id: 'overview', label: 'Overview', icon: <FaUser /> },
    // Projects tab - not visible to admins
    ...(!hasAdminPanelAccess(currentUser) ? [{ id: 'projects', label: 'Projects', icon: <FaProjectDiagram /> }] : []),
    { id: 'connections', label: 'Connections', icon: <FaUserFriends />, badge: incomingConnectionCount > 0 ? incomingConnectionCount : null },
    { id: 'messages', label: 'Messages', icon: <FaEnvelope />, badge: unreadMessageCount > 0 ? unreadMessageCount : null },
    // Freelance tab - only visible to freelancers
    ...(currentUser?.userType === 'freelancer' || currentUser?.userType === 'both'
      ? [
          { id: 'freelance', label: 'Freelance', icon: <FaBriefcase /> },
          { id: 'ratings', label: 'Ratings', icon: <FaStar /> }
        ]
      : []),
    // Admin tab - visible only to admins; click redirects immediately
    ...(hasAdminPanelAccess(currentUser) ? [{ id: 'admin', label: 'Admin', icon: <FaShieldAlt /> }] : []),
    { id: 'settings', label: 'Settings', icon: <FaCog /> },
    { id: 'security', label: 'Security', icon: <FaLock /> }
  ]

  // If still loading or no user, could show a loading state
  if (!currentUser) {
    return <LoadingSpinner fullScreen />
  }

  const handleTabClick = (tabId) => {
    if (tabId === 'admin') {
      navigate('/admin')
      return
    }

    setActiveTab(tabId)
  }

  const handleOpenSettings = () => {
    setActiveTab('settings')
  }

  const handleOpenProjects = () => {
    setActiveTab('projects')
  }

  const handleOpenConnections = () => {
    setActiveTab('connections')
  }

  const handleOpenMessages = () => {
    setActiveTab('messages')
  }

  const handleOpenFreelance = () => {
    setActiveTab('freelance')
  }

  const handleRefreshMessages = async () => {
    if (!currentUser) return

    try {
      setMessagesLoading(true)
      const data = await getUserMessages()
      setMessages(data)
      setHasLoadedMessages(true)
    } catch (error) {
      console.error('Error refreshing messages:', error)
    } finally {
      setMessagesLoading(false)
    }
  }

  const handleResendVerification = async () => {
    try {
      setIsResendingVerification(true)
      const response = await requestEmailVerificationService()
      toast.success(response.message || 'Verification email sent.')

      try {
        await getUserProfile()
      } catch (profileError) {
        console.warn('Failed to refresh profile after resending verification email:', profileError)
      }
    } catch (error) {
      const message = error.response?.data?.message || 'Failed to resend verification email.'
      toast.error(message)
    } finally {
      setIsResendingVerification(false)
    }
  }

  const lockBannerId = getLockBannerId()
  const emailBannerId = getEmailBannerId()
  const isEmailVerified = Boolean(currentUser?.isEmailVerified)
  const isLocked = Boolean(currentUser?.isLocked)

  return (
    <section className='w-full relative z-[1] pt-[80px]'>
      <PageBackground variant='profile' />

      <div className='container mx-auto px-4 py-12 relative z-10 min-h-[calc(100vh-336px)]'>
        {/* Locked Account Banner */}
        {currentUser?.isLocked && !isBannerDismissed(lockBannerId) && (
          <motion.div className='mb-6 p-5 rounded-lg border border-red-200 bg-red-50 dark:border-red-800/60 dark:bg-red-900/20'>
            <div className='flex items-start gap-3'>
              <FaLock className='text-red-600 dark:text-red-300 mt-1 shrink-0' />

              <div className='flex-1'>
                <div className='flex items-start justify-between gap-4'>
                  <div>
                    <p className='font-semibold text-red-700 dark:text-red-200 mb-1'>Account Locked</p>
                    <p className='text-sm text-red-600 dark:text-red-300 mb-4'>You can finish ongoing work, but new projects, proposals, and outbound messages stay disabled until the lock lifts.</p>
                  </div>

                  <button
                    type='button'
                    onClick={() => dismissBanner(lockBannerId)}
                    className='inline-flex items-center justify-center rounded-full p-2 text-red-600 hover:bg-red-100 dark:text-red-300 dark:hover:bg-red-900/40 transition-all duration-300'
                    aria-label='Dismiss account locked message'>
                    <FaTimes />
                  </button>
                </div>

                <dl className='text-sm text-red-700 dark:text-red-200 space-y-1'>
                  <div className='flex flex-wrap gap-1'>
                    <dt className='font-semibold mr-1'>Reason:</dt>
                    <dd>{currentUser.lockReason || 'No reason provided.'}</dd>
                  </div>
                  <div className='flex flex-wrap gap-1'>
                    <dt className='font-semibold mr-1'>Lock length:</dt>
                    <dd>{formatLockDuration(currentUser.lockDurationDays)}</dd>
                  </div>
                  <div className='flex flex-wrap gap-1'>
                    <dt className='font-semibold mr-1'>Unlocks:</dt>
                    <dd>{currentUser.lockExpiresAt ? `${new Date(currentUser.lockExpiresAt).toLocaleString()} ┬╖ ${getLockCountdown(currentUser.lockExpiresAt)}` : 'Manual admin review required'}</dd>
                  </div>
                </dl>
              </div>
            </div>
          </motion.div>
        )}
        {/* Email Verification Banner */}
        {currentUser?.isEmailVerified
          ? !isBannerDismissed(emailBannerId) && (
              <motion.div className='mb-6 p-5 rounded-lg border border-green-200 bg-green-50 dark:border-green-800/60 dark:bg-green-900/20'>
                <div className='flex items-start gap-3'>
                  <FaCheckCircle className='text-green-600 dark:text-green-300 mt-1 shrink-0' />

                  <div className='flex-1'>
                    <div className='flex items-start justify-between gap-4'>
                      <div>
                        <p className='font-semibold text-green-700 dark:text-green-200 mb-1'>Email Verified</p>
                        <p className='text-sm text-green-600 dark:text-green-300'>
                          Your account email has been verified{currentUser.emailVerifiedAt ? ` on ${new Date(currentUser.emailVerifiedAt).toLocaleString()}` : ''}.
                        </p>
                      </div>

                      <button
                        type='button'
                        onClick={() => dismissBanner(emailBannerId)}
                        className='inline-flex items-center justify-center rounded-full p-2 text-green-600 hover:bg-green-100 dark:text-green-300 dark:hover:bg-green-900/40 transition-all duration-300'
                        aria-label='Dismiss email verified message'>
                        <FaTimes />
                      </button>
                    </div>
                  </div>
                </div>
              </motion.div>
            )
          : !isBannerDismissed(emailBannerId) && (
              <motion.div className='mb-6 p-5 rounded-lg border border-amber-200 bg-amber-50 dark:border-amber-800/60 dark:bg-amber-900/20'>
                <div className='flex items-start gap-3'>
                  <FaExclamationTriangle className='text-amber-600 dark:text-amber-300 mt-1 shrink-0' />

                  <div className='flex-1'>
                    <div className='flex items-start justify-between gap-4'>
                      <div>
                        <p className='font-semibold text-amber-700 dark:text-amber-200 mb-1'>Email Not Verified</p>
                        <p className='text-sm text-amber-700 dark:text-amber-300 mb-4'>Verify your email address to complete account verification and make account recovery more reliable.</p>
                      </div>

                      <button
                        type='button'
                        onClick={() => dismissBanner(emailBannerId)}
                        className='inline-flex items-center justify-center rounded-full p-2 text-amber-600 hover:bg-amber-100 dark:text-amber-300 dark:hover:bg-amber-900/40 transition-all duration-300'
                        aria-label='Dismiss email verification message'>
                        <FaTimes />
                      </button>
                    </div>

                    <div className='flex flex-wrap gap-3'>
                      <button
                        type='button'
                        onClick={handleResendVerification}
                        disabled={isResendingVerification}
                        className={`px-4 py-2 rounded-lg text-sm font-medium transition-all duration-300 ${isResendingVerification ? 'bg-gray-400 text-white cursor-not-allowed' : 'bg-accent text-white hover:bg-accent/90 hover:shadow-lg'}`}>
                        {isResendingVerification ? 'Sending...' : 'Resend Verification Email'}
                      </button>

                      <button
                        type='button'
                        onClick={() => navigate('/verify-email')}
                        className='px-4 py-2 rounded-lg text-sm font-medium border border-amber-300 dark:border-amber-700 text-amber-700 dark:text-amber-200 hover:bg-amber-100 dark:hover:bg-amber-900/30 transition-all duration-300 hover:shadow-lg'>
                        Open Verification Page
                      </button>
                    </div>
                  </div>
                </div>
              </motion.div>
            )}
        {/* Profile Header */}
        <motion.div className='flex items-center gap-6 mb-12' initial={{ opacity: 0, y: 20 }} whileInView={{ opacity: 1, y: 0 }} transition={{ duration: 0.6 }}>
          <motion.div className='w-24 h-24 rounded-full overflow-hidden border-4 border-accent' whileHover={{ scale: 1.05 }} transition={{ duration: 0.3 }}>
            <img src={currentUser?.profilePicture || `https://i.pravatar.cc/150?u=${currentUser?._id}`} alt='Profile' className='w-full h-full object-cover' onError={(e) => (e.target.src = '/default-avatar.png')} />
          </motion.div>
          <div>
            <h1 className='text-3xl font-bold theme-text'>
              {currentUser?.firstName} {currentUser?.lastName}
            </h1>

            <div className='mt-1 flex flex-wrap items-center gap-2'>
              <p className='theme-text-secondary'>{getRoleLabel()}</p>

              {isEmailVerified && (
                <span className='inline-flex items-center gap-2 rounded-full bg-green-100 px-3 py-1 text-sm font-medium text-green-700 dark:bg-green-900/30 dark:text-green-300'>
                  <FaCheckCircle className='w-4 h-4' />
                  <span>Verified</span>
                </span>
              )}

              {isLocked && (
                <span className='inline-flex items-center gap-2 rounded-full bg-red-100 px-3 py-1 text-sm font-medium text-red-700 dark:bg-red-900/30 dark:text-red-300'>
                  <FaLock className='w-4 h-4' />
                  <span>Locked</span>
                </span>
              )}
            </div>

            {!hasAdminPanelAccess(currentUser) && (
              <div className='flex items-center gap-2 mt-3'>
                {ratingStats?.totalRatings > 0 ? (
                  <>
                    <div className='flex items-center gap-1'>
                      <span className='text-lg font-semibold text-accent'>{ratingStats.averageRating.toFixed(1)}</span>
                      <div className='flex'>
                        {[1, 2, 3, 4, 5].map((star) => (
                          <FaStar key={star} size={14} className={star <= Math.round(ratingStats.averageRating) ? 'text-accent' : 'text-gray-300 dark:text-gray-600'} />
                        ))}
                      </div>
                    </div>
                    <span className='text-sm theme-text-secondary'>
                      ({ratingStats.totalRatings} {ratingStats.totalRatings === 1 ? 'rating' : 'ratings'})
                    </span>
                  </>
                ) : (
                  <p className='text-sm theme-text-secondary mt-3'>No ratings yet</p>
                )}
              </div>
            )}
          </div>
        </motion.div>
        {/* Navigation Tabs */}
        <motion.div className='flex flex-wrap gap-2 border-b dark:border-light/10 border-primary/10 mb-8' initial={{ opacity: 0, y: 20 }} whileInView={{ opacity: 1, y: 0 }} transition={{ duration: 0.6, delay: 0.2 }}>
          {tabs.map((tab, index) => (
            <motion.button
              key={tab.id}
              onClick={() => handleTabClick(tab.id)}
              className={`flex items-center gap-2 px-6 py-3 font-medium transition-all duration-300 hover:shadow-lg ${activeTab === tab.id ? 'border-b-2 border-accent text-accent' : 'theme-text-secondary hover:text-accent'}`}
              whileHover={{ y: -2 }}
              whileTap={{ scale: 0.95 }}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.3, delay: index * 0.1 }}>
              {tab.icon}
              <span>{tab.label}</span>
              {tab.badge ? <span className='min-w-[1.5rem] h-6 px-2 rounded-full bg-accent text-white text-xs font-semibold flex items-center justify-center'>{tab.badge}</span> : null}
            </motion.button>
          ))}
        </motion.div>
        {/* Content Area */}
        <AnimatePresence mode='wait'>
          <motion.div key={activeTab} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -20 }} transition={{ duration: 0.3 }}>
            {activeTab === 'overview' && (
              <ProfileStats
                user={currentUser}
                profileCompleteness={profileCompleteness}
                onOpenSettings={handleOpenSettings}
                onOpenProjects={!hasAdminPanelAccess(currentUser) ? handleOpenProjects : undefined}
                onOpenConnections={handleOpenConnections}
                onOpenMessages={handleOpenMessages}
                onOpenFreelance={currentUser?.userType === 'freelancer' || currentUser?.userType === 'both' ? handleOpenFreelance : undefined}
              />
            )}
            {activeTab === 'connections' && <ConnectionsTab />}
            {activeTab === 'projects' && <ProjectsList user={currentUser} />}
            {activeTab === 'messages' && (
              <div className='space-y-4'>
                <div className='flex items-center justify-between gap-3'>
                  <div>
                    <h2 className='text-xl font-semibold theme-text'>Messages</h2>
                    <p className='text-sm theme-text-secondary'>Review recent conversations and refresh when you want the latest state.</p>
                  </div>

                  <button
                    type='button'
                    onClick={handleRefreshMessages}
                    disabled={messagesLoading}
                    className='inline-flex items-center gap-2 px-4 py-2 rounded-lg border dark:border-light/10 border-primary/10 theme-text hover:text-accent hover:border-accent/40 transition-all duration-300 hover:shadow-lg disabled:opacity-60'>
                    <FaSyncAlt className={messagesLoading ? 'animate-spin' : ''} />
                    <span>{messagesLoading ? 'Refreshing...' : 'Refresh'}</span>
                  </button>
                </div>

                <MessagesList messages={messages} loading={messagesLoading} onReplySent={handleRefreshMessages} />
              </div>
            )}
            {activeTab === 'freelance' && (
              <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3, delay: 0.1 }}>
                <FreelanceTab user={currentUser} onOpenProjects={handleOpenProjects} />
              </motion.div>
            )}

            {activeTab === 'ratings' && <RatingsSection ratings={ratings} stats={ratingStats} loading={ratingsLoading} />}
            {activeTab === 'settings' && (
              <div className='space-y-4'>
                <div>
                  <h2 className='text-xl font-semibold theme-text'>Profile Settings</h2>
                  <p className='text-sm theme-text-secondary'>Update your personal details, public profile information, and freelancer presence.</p>
                </div>

                <ProfileSettings user={currentUser} />
              </div>
            )}
            {activeTab === 'security' && (
              <div className='space-y-4'>
                <div>
                  <h2 className='text-xl font-semibold theme-text'>Security Settings</h2>
                  <p className='text-sm theme-text-secondary'>Manage your password and keep your account protected.</p>
                </div>

                <SecuritySettings user={currentUser} />
              </div>
            )}
          </motion.div>
        </AnimatePresence>
      </div>
    </section>
  )
}

export default Profile

import { useState, useEffect } from 'react'
import { useParams, useNavigate, useLocation } from 'react-router-dom'
import { motion } from 'framer-motion'
import { FaArrowLeft, FaTimes, FaCheck, FaEnvelope } from 'react-icons/fa'
import { getProjectById } from '../services/projectService'
import { useAuth } from '../context/AuthContext'
import ContactModal from '../modal/ContactModal'
import ProjectModal from '../modal/ProjectModal'
import { getCollaborationStageClasses, getCollaborationStageLabel, getDisplayName, getProjectRelationshipSummary } from '../utils/projectDetailUI'
import SubmitProjectModal from '../modal/SubmitProjectModal'
import PageBackground from '../components/shared/PageBackground'
import LoadingSpinner from '../components/shared/LoadingSpinner'
import ReviewProjectModal from '../modal/ReviewProjectModal'
import VerificationBadge from '../components/shared/VerificationBadge'
import { useRateNegotiation } from '../hooks/useRateNegotiation'
import { useProjectModals } from '../hooks/useProjectModals'
import { useFavorites } from '../hooks/useFavorites'
import { useProjectMessages } from '../hooks/useProjectMessages'
import { ProjectHeader, RateNegotiationCard, ProjectActions, MessagesTab } from '../components/ProjectDetail'
import { normalizeSkills } from '../utils/skillUtils'

const PROJECT_BRIEF_LABELS = {
  experienceLevel: {
    not_specified: 'Not specified',
    junior: 'Junior',
    mid: 'Mid',
    senior: 'Senior',
    expert: 'Expert'
  },
  duration: {
    not_specified: 'Not specified',
    less_than_1_week: 'Less than 1 week',
    '1_to_2_weeks': '1 to 2 weeks',
    '2_to_4_weeks': '2 to 4 weeks',
    '1_to_3_months': '1 to 3 months',
    '3_plus_months': '3+ months',
    ongoing: 'Ongoing'
  },
  workload: {
    not_specified: 'Not specified',
    under_10_hours: 'Under 10 hrs/week',
    '10_to_20_hours': '10 to 20 hrs/week',
    '20_to_30_hours': '20 to 30 hrs/week',
    '30_plus_hours': '30+ hrs/week',
    full_time: 'Full time'
  },
  startPreference: {
    not_specified: 'Not specified',
    immediately: 'Immediately',
    this_week: 'This week',
    within_2_weeks: 'Within 2 weeks',
    flexible: 'Flexible'
  },
  budgetType: {
    not_specified: 'Not specified',
    fixed: 'Fixed',
    hourly: 'Hourly',
    negotiable: 'Negotiable'
  }
}

const getProjectBriefLabel = (group, value) => {
  if (!value) return 'Not specified'
  return PROJECT_BRIEF_LABELS[group]?.[value] || 'Not specified'
}

const ProjectDetail = () => {
  const { id } = useParams()
  const navigate = useNavigate()
  const location = useLocation()
  const { currentUser, loading: authLoading } = useAuth()

  const [project, setProject] = useState(null)
  const [activeTab, setActiveTab] = useState('details')
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)

  // Extract modal state into hook
  const {
    isContactModalOpen,
    setIsContactModalOpen,
    isEditModalOpen,
    setIsEditModalOpen,
    isSubmitModalOpen,
    setIsSubmitModalOpen,
    isReviewModalOpen,
    setIsReviewModalOpen,
    isRescheduleModalOpen,
    setIsRescheduleModalOpen
  } = useProjectModals()

  // Extract favorites into hook
  const { isFavorited, favoriteLoading, handleToggleFavorite } = useFavorites(id, currentUser)

  // Extract messages into hook
  const { messages, messagesLoading } = useProjectMessages(project, currentUser)

  // Load project data
  const loadProject = async () => {
    try {
      setLoading(true)
      setError(null)
      const data = await getProjectById(id)
      setProject(data)
    } catch (err) {
      console.error('Error fetching project:', err)
      if (err.response?.status === 404) {
        setError('Project not found or not yet published.')
      } else if (err.response?.status === 401) {
        setError('Authentication required. Please log in.')
      } else {
        setError('Failed to load project. Please try again.')
      }
    } finally {
      setLoading(false)
    }
  }

  const { rateAmount, setRateAmount, rateType, setRateType, rateLoading, rateError, setRateError, handleProposeRate, handleCounterRate, handleAcceptRate } = useRateNegotiation(id, loadProject)

  const isOwner = currentUser && project && currentUser._id === project.user?._id
  const isAssignee = currentUser && project && (project.assignee?._id ? project.assignee._id === currentUser._id : project.assignee === currentUser._id)
  const hasApplied = Boolean(
    currentUser &&
    Array.isArray(project?.interestedUsers) &&
    project.interestedUsers.some((entry) => {
      const userId = entry?.userId?._id || entry?.userId
      return userId?.toString() === currentUser._id?.toString()
    })
  )

  // Fetch project on mount or when id/currentUser changes
  useEffect(() => {
    if (authLoading) return

    // If user logged out while on this page, redirect to home or show message
    if (!currentUser) {
      setError('You have been logged out. Please log in to view this project.')
      return
    }

    if (id) loadProject()
  }, [id, currentUser, authLoading])

  // Build negotiation timeline for MessagesTab
  const negotiationHistory = project?.rateNegotiation?.history || []
  const getOfferLabel = (userId) => {
    if (!userId) return 'User'
    if (project?.user?._id && userId.toString() === project.user._id.toString()) return 'Client'
    if (project?.assignee?._id && userId.toString() === project.assignee._id.toString()) return 'Freelancer'
    return 'User'
  }
  const formatOfferType = (type) => (type === 'fixed' ? 'fixed' : '/hr')
  const negotiationTimeline = negotiationHistory.map((offer) => {
    const label = getOfferLabel(offer.proposedBy)
    const time = offer.proposedAt ? new Date(offer.proposedAt) : null
    return {
      text: `${label} proposed Γé¼${offer.amount} ${formatOfferType(offer.type)}`,
      time
    }
  })

  const collaborationStageLabel = getCollaborationStageLabel(project?.status)
  const collaborationStageClasses = getCollaborationStageClasses(project?.status)

  const relationshipSummary = getProjectRelationshipSummary({
    isOwner,
    isAssignee,
    hasAssignee: Boolean(project?.assignee)
  })

  const canContactAssignee = (project?.user?._id === currentUser?._id || project?.user === currentUser?._id) && !['completed', 'archived', 'cancelled_by_admin', 'deleted_by_owner'].includes(project?.status)

  const clientDisplayName = getDisplayName(project?.user, 'Client not available')
  const assigneeDisplayName = getDisplayName(project?.assignee, 'No freelancer assigned yet')
  const projectBrief = project?.projectBrief || {}
  const deliverables = Array.isArray(projectBrief.deliverables) ? projectBrief.deliverables : []
  const normalizedSkills = normalizeSkills(project?.skills)

  const experienceLevelLabel = getProjectBriefLabel('experienceLevel', projectBrief.experienceLevel)
  const durationLabel = getProjectBriefLabel('duration', projectBrief.duration)
  const workloadLabel = getProjectBriefLabel('workload', projectBrief.workload)
  const startPreferenceLabel = getProjectBriefLabel('startPreference', projectBrief.startPreference)
  const budgetTypeLabel = getProjectBriefLabel('budgetType', projectBrief.budgetType)

  const handleBack = () => {
    if (location.state?.returnTo) {
      navigate(location.state.returnTo)
      return
    }

    navigate(-1)
  }

  // Loading state
  if (loading) {
    return (
      <section className='w-full theme-bg relative z-[1] pt-[80px]'>
        <div className='container mx-auto px-4 py-12 relative z-10 min-h-[calc(100vh-336px)]'>
          <div className='flex items-center justify-center min-h-[400px]'>
            <LoadingSpinner />
          </div>
        </div>
      </section>
    )
  }

  // Error state
  if (error) {
    return (
      <section className='w-full theme-bg relative z-[1] pt-[80px]'>
        <div className='container mx-auto px-4 py-12 relative z-10 min-h-[calc(100vh-336px)]'>
          <div className='flex flex-col items-center justify-center min-h-[400px]'>
            <p className='text-red-500 text-xl mb-4'>{error}</p>
            <button onClick={handleBack} className='px-6 py-2 bg-accent text-white rounded-lg hover:bg-accent/90 hover:shadow-lg transition-all duration-300'>
              Go Back
            </button>
          </div>
        </div>
      </section>
    )
  }

  // No project found
  if (!project) {
    return (
      <section className='w-full theme-bg relative z-[1] pt-[80px]'>
        <div className='container mx-auto px-4 py-12 relative z-10 min-h-[calc(100vh-336px)]'>
          <div className='flex flex-col items-center justify-center min-h-[400px]'>
            <p className='theme-text text-xl mb-4'>Project not found</p>
            <button onClick={handleBack} className='px-6 py-2 bg-accent text-white rounded-lg hover:bg-accent/90 hover:shadow-lg transition-all duration-300'>
              Go Back
            </button>
          </div>
        </div>
      </section>
    )
  }

  return (
    <section className='w-full relative z-[1] pt-[80px]'>
      <PageBackground variant='profile' />

      <div className='container mx-auto px-4 py-12 relative z-10 min-h-[calc(100vh-336px)]'>
        {/* Back Button */}
        <motion.button
          onClick={handleBack}
          className='flex items-center gap-2 mb-6 theme-text-secondary hover:text-accent transition-all duration-300'
          whileHover={{ x: -5 }}
          initial={{ opacity: 0, x: -20 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.3 }}>
          <FaArrowLeft />
          <span>Back</span>
        </motion.button>

        {/* Project Header */}
        <ProjectHeader project={project} />

        {/* Project Content */}
        {/* Tabs for project owner */}
        {project?.user?._id === currentUser?._id && (
          <motion.div className='flex gap-4 mb-8 border-b dark:border-light/10 border-primary/10' initial={{ opacity: 0, y: -20 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3 }}>
            <button
              onClick={() => setActiveTab('details')}
              className={`py-4 px-6 transition-all duration-300 font-medium ${activeTab === 'details' ? 'border-b-2 border-accent text-accent' : 'theme-text-secondary hover:text-accent hover:transition-all'}`}>
              Project Details
            </button>
            <button
              onClick={() => setActiveTab('messages')}
              className={`py-4 px-6 transition-all duration-300 font-medium flex items-center gap-2 ${activeTab === 'messages' ? 'border-b-2 border-accent text-accent' : 'theme-text-secondary hover:text-accent'}`}>
              Messages
              {messages.length > 0 && <span className='px-2 py-1 bg-accent text-white rounded-full text-sm'>{messages.length}</span>}
            </button>
          </motion.div>
        )}

        {/* Project Content */}
        {activeTab === 'details' && (
          <div className='grid grid-cols-1 lg:grid-cols-3 gap-8'>
            {/* Main Content */}
            <motion.div className='lg:col-span-2 space-y-6' initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.5, delay: 0.2 }}>
              {/* Project Brief Section */}
              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                className='p-6 rounded-lg space-y-6 border theme-border bg-gradient-to-br dark:from-light/5 dark:via-light/[0.02] from-primary/5 via-primary/[0.02] to-transparent backdrop-blur-sm'>
                <div className='space-y-2'>
                  <h3 className='text-xl font-semibold theme-text'>Project Brief</h3>
                  <p className='text-sm leading-6 theme-text-secondary'>Summary of the project scope, expectations, and delivery requirements.</p>
                </div>

                <div className='grid grid-cols-1 md:grid-cols-2 gap-4'>
                  <div className='rounded-xl border theme-border bg-gradient-to-br dark:from-light/5 dark:via-light/[0.02] from-primary/5 via-primary/[0.02] to-transparent backdrop-blur-sm p-4'>
                    <p className='text-xs font-semibold uppercase tracking-[0.14em] theme-text-secondary'>Experience Level</p>
                    <p className='mt-2 text-base font-semibold theme-text'>{experienceLevelLabel}</p>
                  </div>

                  <div className='rounded-xl border theme-border bg-gradient-to-br dark:from-light/5 dark:via-light/[0.02] from-primary/5 via-primary/[0.02] to-transparent backdrop-blur-sm p-4'>
                    <p className='text-xs font-semibold uppercase tracking-[0.14em] theme-text-secondary'>Start Preference</p>
                    <p className='mt-2 text-base font-semibold theme-text'>{startPreferenceLabel}</p>
                  </div>

                  <div className='rounded-xl border theme-border bg-gradient-to-br dark:from-light/5 dark:via-light/[0.02] from-primary/5 via-primary/[0.02] to-transparent backdrop-blur-sm p-4'>
                    <p className='text-xs font-semibold uppercase tracking-[0.14em] theme-text-secondary'>Estimated Duration</p>
                    <p className='mt-2 text-base font-semibold theme-text'>{durationLabel}</p>
                  </div>

                  <div className='rounded-xl border theme-border bg-gradient-to-br dark:from-light/5 dark:via-light/[0.02] from-primary/5 via-primary/[0.02] to-transparent backdrop-blur-sm p-4'>
                    <p className='text-xs font-semibold uppercase tracking-[0.14em] theme-text-secondary'>Workload</p>
                    <p className='mt-2 text-base font-semibold theme-text'>{workloadLabel}</p>
                  </div>

                  <div className='rounded-xl border theme-border bg-gradient-to-br dark:from-light/5 dark:via-light/[0.02] from-primary/5 via-primary/[0.02] to-transparent backdrop-blur-sm p-4'>
                    <p className='text-xs font-semibold uppercase tracking-[0.14em] theme-text-secondary'>Budget Model</p>
                    <p className='mt-2 text-base font-semibold theme-text'>{budgetTypeLabel}</p>
                    <p className='mt-1 text-sm theme-text-secondary'>{project.rateNegotiation?.currentOffer ? 'Active rate discussion in progress.' : 'No active rate negotiation.'}</p>
                  </div>

                  <div className='rounded-xl border theme-border bg-gradient-to-br dark:from-light/5 dark:via-light/[0.02] from-primary/5 via-primary/[0.02] to-transparent backdrop-blur-sm p-4'>
                    <p className='text-xs font-semibold uppercase tracking-[0.14em] theme-text-secondary'>Skills Required</p>

                    {normalizedSkills.length > 0 ? (
                      <div className='mt-3 flex flex-wrap gap-2'>
                        {normalizedSkills.map((skill, index) => (
                          <span key={`${skill}-${index}`} className='inline-flex items-center rounded-full px-3 py-1 text-xs font-semibold bg-accent/10 text-accent border border-accent/20'>
                            {skill}
                          </span>
                        ))}
                      </div>
                    ) : (
                      <p className='mt-2 text-base font-semibold theme-text'>Not specified</p>
                    )}
                  </div>
                </div>

                {projectBrief.objective && (
                  <div className='space-y-2'>
                    <p className='text-xs font-semibold uppercase tracking-[0.14em] theme-text-secondary'>Objective</p>
                    <p className='text-sm leading-7 theme-text'>{projectBrief.objective}</p>
                  </div>
                )}

                {deliverables.length > 0 && (
                  <div className='space-y-3'>
                    <p className='text-xs font-semibold uppercase tracking-[0.14em] theme-text-secondary'>Deliverables</p>
                    <div className='flex flex-wrap gap-2'>
                      {deliverables.map((deliverable, index) => (
                        <span key={`${deliverable}-${index}`} className='inline-flex items-center rounded-full px-3 py-1 text-sm font-medium bg-accent/10 text-accent'>
                          {deliverable}
                        </span>
                      ))}
                    </div>
                  </div>
                )}

                {projectBrief.scopeNotes && (
                  <div className='space-y-2'>
                    <p className='text-xs font-semibold uppercase tracking-[0.14em] theme-text-secondary'>Scope Notes</p>
                    <p className='text-sm leading-7 theme-text'>{projectBrief.scopeNotes}</p>
                  </div>
                )}

                {projectBrief.applicationInstructions && (
                  <div className='rounded-xl border border-accent/30 bg-gradient-to-br dark:from-accent/5 dark:via-accent/[0.02] from-accent/5 via-accent/[0.02] to-transparent backdrop-blur-sm p-4 space-y-2'>
                    <p className='text-xs font-semibold uppercase tracking-[0.14em] text-accent'>Application Instructions</p>
                    <p className='text-sm leading-7 theme-text'>{projectBrief.applicationInstructions}</p>
                  </div>
                )}

                <div className='pt-2 space-y-4'>
                  <h3 className='text-xl font-semibold theme-text'>Delivery Snapshot</h3>

                  {project.rateNegotiation?.currentOffer ? (
                    <div className='rounded-xl border theme-border bg-gradient-to-br dark:from-light/5 dark:via-light/[0.02] from-primary/5 via-primary/[0.02] to-transparent backdrop-blur-sm p-4'>
                      <p className='text-xs font-semibold uppercase tracking-[0.14em] theme-text-secondary'>Commercial Model</p>
                      <div className='mt-2 flex flex-wrap items-center gap-2'>
                        <span className='inline-flex items-center rounded-full px-3 py-1 text-xs font-semibold bg-accent/10 text-accent'>
                          {project.rateNegotiation.currentOffer.type === 'hourly' ? 'Hourly Rate' : 'Fixed Price'}
                        </span>

                        {project.rateNegotiation?.status === 'proposed' && (
                          <span className='inline-flex items-center rounded-full px-3 py-1 text-xs font-semibold bg-orange-100 text-orange-700 dark:bg-orange-900/30 dark:text-orange-300'>Offer Pending</span>
                        )}
                      </div>
                    </div>
                  ) : (
                    <div className='rounded-xl border theme-border bg-gradient-to-br dark:from-light/5 dark:via-light/[0.02] from-primary/5 via-primary/[0.02] to-transparent backdrop-blur-sm p-4'>
                      <p className='text-xs font-semibold uppercase tracking-[0.14em] theme-text-secondary'>Commercial Model</p>
                      <p className='mt-2 text-sm theme-text-secondary'>Fixed project budget with no active negotiation.</p>
                    </div>
                  )}

                  <div className='grid grid-cols-1 md:grid-cols-2 gap-4'>
                    <div className='rounded-xl border theme-border bg-gradient-to-br dark:from-light/5 dark:via-light/[0.02] from-primary/5 via-primary/[0.02] to-transparent backdrop-blur-sm p-4'>
                      <p className='text-xs font-semibold uppercase tracking-[0.14em] theme-text-secondary'>Timeline</p>
                      <p className='mt-2 text-base font-semibold theme-text'>{project.deadline ? new Date(project.deadline).toLocaleDateString() : 'Flexible deadline'}</p>
                      <p className='mt-1 text-sm theme-text-secondary'>
                        {project.status === 'under_review'
                          ? 'Work is completed and waiting for client review.'
                          : project.status === 'in_progress'
                            ? 'Delivery is actively in progress.'
                            : project.status === 'negotiating'
                              ? 'Budget and rate are still being finalized.'
                              : 'Project timing depends on the current collaboration stage.'}
                      </p>
                    </div>

                    <div className='rounded-xl border theme-border bg-gradient-to-br dark:from-light/5 dark:via-light/[0.02] from-primary/5 via-primary/[0.02] to-transparent backdrop-blur-sm p-4'>
                      <p className='text-xs font-semibold uppercase tracking-[0.14em] theme-text-secondary'>Work Expectations</p>
                      <div className='mt-2 flex flex-col gap-2 text-sm theme-text-secondary'>
                        <p>
                          <span className='font-semibold theme-text'>Experience:</span> {experienceLevelLabel}
                        </p>
                        <p>
                          <span className='font-semibold theme-text'>Duration:</span> {durationLabel}
                        </p>
                        <p>
                          <span className='font-semibold theme-text'>Workload:</span> {workloadLabel}
                        </p>
                      </div>
                    </div>
                  </div>
                </div>
              </motion.div>

              {/* Review Feedback Section - visible to both */}
              {project.review && project.review.decision && (
                <motion.div
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  className='p-6 rounded-lg border-l-4 border-accent space-y-3 border theme-border bg-gradient-to-br dark:from-light/5 dark:via-light/[0.02] from-primary/5 via-primary/[0.02] to-transparent backdrop-blur-sm'>
                  <div className='flex items-center gap-2'>
                    {project.review.decision === 'accepted' ? (
                      <>
                        <FaCheck className='text-green-500 text-xl' />
                        <h3 className='text-lg font-semibold text-green-600 dark:text-green-400'>Project Accepted</h3>
                      </>
                    ) : (
                      <>
                        <FaTimes className='text-red-500 text-xl' />
                        <h3 className='text-lg font-semibold text-red-600 dark:text-red-400'>Changes Requested</h3>
                      </>
                    )}
                  </div>

                  {project.review.feedback && (
                    <div className='rounded-lg p-4 border theme-border bg-gradient-to-br dark:from-light/5 dark:via-light/[0.02] from-primary/5 via-primary/[0.02] to-transparent backdrop-blur-sm'>
                      <p className='text-xs font-semibold theme-text-secondary mb-2'>Feedback from Client:</p>
                      <p className='text-sm theme-text leading-relaxed'>{project.review.feedback}</p>
                    </div>
                  )}

                  <p className='text-xs theme-text-secondary'>
                    {new Date(project.review.reviewedAt).toLocaleDateString()} at {new Date(project.review.reviewedAt).toLocaleTimeString()}
                  </p>
                </motion.div>
              )}
            </motion.div>

            {/* Sidebar */}
            <motion.div className='space-y-5' initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.5, delay: 0.4 }}>
              {/* Collaboration Overview */}
              {project.user && (
                <div className='p-6 rounded-lg space-y-5 border theme-border bg-gradient-to-br dark:from-light/5 dark:via-light/[0.02] from-primary/5 via-primary/[0.02] to-transparent backdrop-blur-sm'>
                  <div className='space-y-3'>
                    <div className='flex flex-wrap items-center justify-between gap-3'>
                      <h3 className='text-xl font-semibold theme-text'>Collaboration Overview</h3>
                      <span className={`inline-flex items-center rounded-full px-3 py-1 text-xs font-semibold ${collaborationStageClasses}`}>{collaborationStageLabel}</span>
                    </div>
                    <p className='text-sm leading-6 theme-text-secondary'>{relationshipSummary}</p>
                  </div>

                  <div className='space-y-4'>
                    <div className='rounded-lg border theme-border bg-gradient-to-br dark:from-light/5 dark:via-light/[0.02] from-primary/5 via-primary/[0.02] to-transparent backdrop-blur-sm p-4'>
                      <p className='text-xs font-semibold uppercase tracking-[0.14em] theme-text-secondary mb-3'>Client</p>
                      <div className='flex items-center gap-3'>
                        <img src={project.user.profilePicture || `https://i.pravatar.cc/150?u=${project.user._id}`} alt={project.user.firstName} className='w-12 h-12 rounded-full object-cover border border-accent/20' />
                        <div className='min-w-0'>
                          <div className='flex items-center gap-2 flex-wrap'>
                            <p className='font-semibold theme-text'>{clientDisplayName}</p>
                            <VerificationBadge isVerified={project.user.isEmailVerified} />
                          </div>
                          <p className='text-sm theme-text-secondary'>{project.user.headline || 'Project owner'}</p>
                          <p className='text-xs theme-text-muted mt-1 inline-flex items-center gap-1'>
                            <FaEnvelope className='text-[10px]' />
                            <span className='truncate'>{project.user.email}</span>
                          </p>
                        </div>
                      </div>
                    </div>

                    <div className='rounded-xl border theme-border bg-gradient-to-br dark:from-light/5 dark:via-light/[0.02] from-primary/5 via-primary/[0.02] to-transparent backdrop-blur-sm p-4'>
                      <p className='text-xs font-semibold uppercase tracking-[0.14em] theme-text-secondary mb-3'>Freelancer</p>

                      {project.assignee ? (
                        <div className='flex items-center gap-3'>
                          <img
                            src={project.assignee.profilePicture || `https://i.pravatar.cc/150?u=${project.assignee._id}`}
                            alt={project.assignee.firstName}
                            className='w-12 h-12 rounded-full object-cover border border-accent/20'
                          />
                          <div className='min-w-0'>
                            <div className='flex items-center gap-2 flex-wrap'>
                              <p className='font-semibold theme-text'>{assigneeDisplayName}</p>
                              <VerificationBadge isVerified={project.assignee.isEmailVerified} />
                            </div>
                            <p className='text-sm theme-text-secondary'>{project.assignee.headline || 'Assigned freelancer'}</p>
                            <p className='text-xs theme-text-muted mt-1 inline-flex items-center gap-1'>
                              <FaEnvelope className='text-[10px]' />
                              <span className='truncate'>{project.assignee.email}</span>
                            </p>
                          </div>
                        </div>
                      ) : (
                        <div className='rounded-lg border border-dashed dark:border-light/10 border-primary/10 p-4'>
                          <p className='font-medium theme-text'>{assigneeDisplayName}</p>
                          <p className='text-sm theme-text-secondary mt-1'>The project is still open and no freelancer has been assigned yet.</p>
                        </div>
                      )}
                    </div>
                  </div>

                  {project.assignee && canContactAssignee && (
                    <motion.button
                      onClick={() => navigate('/messages')}
                      className='w-full py-3 bg-accent/10 text-accent hover:bg-accent hover:text-white rounded-lg transition-all text-sm font-medium'
                      whileHover={{ scale: 1.02 }}
                      whileTap={{ scale: 0.98 }}>
                      Contact Assignee
                    </motion.button>
                  )}
                </div>
              )}

              {/* Action Buttons */}
              <ProjectActions
                project={project}
                currentUser={currentUser}
                isOwner={isOwner}
                isAssignee={isAssignee}
                hasApplied={hasApplied}
                isFavorited={isFavorited}
                favoriteLoading={favoriteLoading}
                handleToggleFavorite={handleToggleFavorite}
                setIsEditModalOpen={setIsEditModalOpen}
                setIsContactModalOpen={setIsContactModalOpen}
                setIsSubmitModalOpen={setIsSubmitModalOpen}
                setIsReviewModalOpen={setIsReviewModalOpen}
                isRescheduleModalOpen={isRescheduleModalOpen}
                setIsRescheduleModalOpen={setIsRescheduleModalOpen}
                loadProject={loadProject}
              />

              {/* Rate Negotiation */}
              <RateNegotiationCard
                project={project}
                currentUser={currentUser}
                rateAmount={rateAmount}
                setRateAmount={setRateAmount}
                rateType={rateType}
                setRateType={setRateType}
                rateLoading={rateLoading}
                rateError={rateError}
                handleProposeRate={handleProposeRate}
                handleCounterRate={handleCounterRate}
                handleAcceptRate={handleAcceptRate}
              />
            </motion.div>
          </div>
        )}

        {/* Messages Tab */}
        {activeTab === 'messages' && <MessagesTab project={project} currentUser={currentUser} messages={messages} messagesLoading={messagesLoading} negotiationTimeline={negotiationTimeline} id={id} />}
      </div>
      {/* Edit Project Modal */}
      {project && <ProjectModal isOpen={isEditModalOpen} onClose={() => setIsEditModalOpen(false)} mode='edit' initialData={project} onProjectUpdated={loadProject} />}

      {/* Contact Modal */}
      {project && project.user && <ContactModal isOpen={isContactModalOpen} onClose={() => setIsContactModalOpen(false)} project={project} hasApplied={hasApplied} />}

      {/* Submit and Review Modals */}
      {project && <SubmitProjectModal isOpen={isSubmitModalOpen} onClose={() => setIsSubmitModalOpen(false)} project={project} onSubmitSuccess={loadProject} />}

      {project && <ReviewProjectModal isOpen={isReviewModalOpen} onClose={() => setIsReviewModalOpen(false)} project={project} onReviewSuccess={loadProject} />}
    </section>
  )
}

export default ProjectDetail

import { motion } from 'framer-motion'
import { useState, useEffect, useRef } from 'react'
import PageBackground from '../components/shared/PageBackground'
import { FaLock, FaEye, FaEyeSlash } from 'react-icons/fa'
import { useNavigate, Link } from 'react-router-dom'
import { toast, ToastContainer } from 'react-toastify'
import 'react-toastify/dist/ReactToastify.css'
import { useAuth } from '../context/AuthContext'

const Register = () => {
  const navigate = useNavigate()
  const [isLoading, setIsLoading] = useState(false)

  // Get the register function and currentUser from context
  const { register, currentUser } = useAuth()

  // Add check to redirect if already logged in
  useEffect(() => {
    if (currentUser) {
      navigate('/profile')
    }
  }, [currentUser, navigate])

  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    password: '',
    confirmPassword: '',
    userType: ''
  })

  const [contentHeight, setContentHeight] = useState('100vh')
  const registerRef = useRef(null)

  const [showPasswords, setShowPasswords] = useState({
    password: false,
    confirmPassword: false
  })

  const [errors, setErrors] = useState({})

  const handleChange = (e) => {
    const { name, value } = e.target
    setFormData((prev) => ({
      ...prev,
      [name]: value
    }))
  }

  const validateForm = () => {
    const newErrors = {}

    // Name validation
    if (!formData.firstName.trim()) newErrors.firstName = 'First name is required'
    if (!formData.lastName.trim()) newErrors.lastName = 'Last name is required'

    // Email validation
    if (!formData.email.trim()) {
      newErrors.email = 'Email is required'
    } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
      newErrors.email = 'Email is invalid'
    }

    // Password validation
    if (!formData.password) {
      newErrors.password = 'Password is required'
    } else {
      if (formData.password.length < 8) {
        newErrors.password = 'Password must be at least 8 characters'
      }
      if (!/[A-Z]/.test(formData.password)) {
        newErrors.password = 'Password must contain at least one uppercase letter'
      }
      if (!/[a-z]/.test(formData.password)) {
        newErrors.password = 'Password must contain at least one lowercase letter'
      }
      if (!/[0-9]/.test(formData.password)) {
        newErrors.password = 'Password must contain at least one number'
      }
      if (!/[!@#$%^&*]/.test(formData.password)) {
        newErrors.password = 'Password must contain at least one special character'
      }
    }

    // Confirm password validation
    if (formData.password !== formData.confirmPassword) {
      newErrors.confirmPassword = 'Passwords do not match'
    }

    // Select field
    if (!formData.userType) {
      newErrors.userType = 'Please select your account type'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    if (validateForm()) {
      setIsLoading(true)

      try {
        // Create the user data object to send to the backend
        const userData = {
          firstName: formData.firstName,
          lastName: formData.lastName,
          email: formData.email,
          password: formData.password,
          userType: formData.userType
        }

        // Call the register function from context instead of direct service
        await register(userData)

        // Navigate to profile (no need for timeout since toast is handled in context)
        navigate('/profile')
      } catch (error) {
        // Error handling is done in context
        console.error('Registration error:', error)
      } finally {
        setIsLoading(false)
      }
    }
  }

  // Password requirements component
  const PasswordRequirements = ({ password }) => {
    const requirements = [
      { label: 'At least 8 characters', test: (pwd) => pwd.length >= 8 },
      { label: 'Contains uppercase letter', test: (pwd) => /[A-Z]/.test(pwd) },
      { label: 'Contains lowercase letter', test: (pwd) => /[a-z]/.test(pwd) },
      { label: 'Contains number', test: (pwd) => /[0-9]/.test(pwd) },
      { label: 'Contains special character', test: (pwd) => /[!@#$%^&*]/.test(pwd) }
    ]

    return (
      <div className='mt-2 space-y-2'>
        {requirements.map((req, index) => (
          <motion.div key={index} className='flex items-center space-x-2' initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: index * 0.1 }}>
            <span className={`text-sm ${req.test(password) ? 'text-green-500' : 'text-red-500'}`}>{req.test(password) ? 'Γ£ô' : '├ù'}</span>
            <span className='text-sm theme-text-secondary'>{req.label}</span>
          </motion.div>
        ))}
      </div>
    )
  }

  const getInputClasses = (fieldName) => `
  w-full p-3 rounded-lg
  bg-transparent
  transition-all duration-300
  dark:text-light text-primary
  dark:placeholder:text-light/40 placeholder:text-primary/40
  dark:focus:placeholder:text-light/60 focus:placeholder:text-primary/60
  focus:outline-none focus:ring-2 focus:ring-accent/50
  hover:scale-[1.02]
  ${errors[fieldName] ? 'border-2 border-red-500' : 'border dark:border-light/10 border-primary/10'}
`

  useEffect(() => {
    const calculateHeight = () => {
      const footerElement = document.querySelector('footer')
      if (footerElement) {
        const footerHeight = footerElement.offsetHeight
        setContentHeight(`calc(100vh - ${footerHeight}px)`)
      }
    }

    // Calculate on mount and window resize
    calculateHeight()
    window.addEventListener('resize', calculateHeight)

    return () => {
      window.removeEventListener('resize', calculateHeight)
    }
  }, [])

  return (
    <div ref={registerRef} className='flex items-center justify-center px-6 relative z-[1]' style={{ minHeight: contentHeight }}>
      <PageBackground variant='auth' />

      <div className='container mx-auto px-4 relative z-10'>
