                    className={`p-4 rounded-lg border transition-all duration-300 hover:shadow-lg ${formData.userType === 'client' ? 'border-accent bg-accent/10' : 'dark:border-light/10 border-primary/10'} cursor-pointer hover:border-accent`}>
                    <input type='radio' name='userType' value='client' onChange={handleChange} className='sr-only' />
                    <div className='flex flex-col items-center text-center'>
                      <span className='text-xl mb-2'>≡ƒºá</span>
                      <span className='dark:text-light text-primary font-medium'>Hire Talent</span>
                      <span className='text-sm dark:text-light/70 text-primary/70'>I have projects that need skills</span>
                    </div>
                  </label>

                  <label
                    className={`p-4 rounded-lg border transition-all duration-300 hover:shadow-lg ${formData.userType === 'freelancer' ? 'border-accent bg-accent/10' : 'dark:border-light/10 border-primary/10'} cursor-pointer hover:border-accent`}>
                    <input type='radio' name='userType' value='freelancer' onChange={handleChange} className='sr-only' />
                    <div className='flex flex-col items-center text-center'>
                      <span className='text-xl mb-2'>≡ƒÆ╗</span>
                      <span className='dark:text-light text-primary font-medium'>Work as Freelancer</span>
                      <span className='text-sm dark:text-light/70 text-primary/70'>I have skills to offer</span>
                    </div>
                  </label>

                  <label
                    className={`p-4 rounded-lg border transition-all duration-300 hover:shadow-lg ${formData.userType === 'both' ? 'border-accent bg-accent/10' : 'dark:border-light/10 border-primary/10'} cursor-pointer hover:border-accent`}>
                    <input type='radio' name='userType' value='both' onChange={handleChange} className='sr-only' />
                    <div className='flex flex-col items-center text-center'>
                      <span className='text-xl mb-2'>≡ƒöä</span>
                      <span className='dark:text-light text-primary font-medium'>Both</span>
                      <span className='text-sm dark:text-light/70 text-primary/70'>I want to do both</span>
                    </div>
                  </label>
                </div>
                {errors.userType && (
                  <motion.p initial={{ opacity: 0 }} animate={{ opacity: 1 }} className='text-red-500 text-sm mt-1'>
                    {errors.userType}
                  </motion.p>
                )}
              </div>

              <motion.button
                whileHover={{ scale: 1.02 }}
                whileTap={{ scale: 0.98 }}
                type='submit'
                disabled={isLoading}
                className='w-full p-3 bg-accent text-white rounded-lg hover:bg-accent/90 transition-all duration-300 hover:shadow-lg font-medium flex items-center justify-center'>
                {isLoading ? (
                  <>
                    <svg className='animate-spin -ml-1 mr-3 h-5 w-5 text-white' xmlns='http://www.w3.org/2000/svg' fill='none' viewBox='0 0 24 24'>
                      <circle className='opacity-25' cx='12' cy='12' r='10' stroke='currentColor' strokeWidth='4'></circle>
                      <path className='opacity-75' fill='currentColor' d='M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z'></path>
                    </svg>
                    Registering...
                  </>
                ) : (
                  'Register'
                )}
              </motion.button>

              {/* In case user has an account */}
              <div className='mt-4 text-center'>
                <p className='theme-text-secondary'>
                  Already have an account?{' '}
                  <Link to='/login' className='text-accent hover:underline'>
                    Sign in
                  </Link>
                </p>
              </div>
            </form>
          </motion.div>
        </div>
      </div>
    </div>
  )
}

